// ── Normalizar texto para búsqueda — elimina acentos y colapsa espacios múltiples ──
const norm = (str) => {
  if (!str) return "";
  return String(str)
    .toLowerCase()
    .normalize("NFD")                    // descompone tildes: á → a + ́
    .replace(/[\u0300-\u036f]/g, "")   // elimina los diacríticos
    .replace(/\s+/g, " ")               // colapsa 2+ espacios en 1
    .trim();
};

