// PORTAL ADMIN
// ══════════════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════════════
// HELPERS FACTURACIÓN
// ══════════════════════════════════════════════════════════════
const MESES = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];

// ── Métodos de pago — editable desde Panel Superusuario / Admin ──────────
// Para agregar/quitar métodos sin tocar el código, usa el panel de configuración.
// Esta lista es el valor por defecto si no hay configuración guardada.
const METODOS_PAGO_DEFAULT = [
  { id: "Efectivo",       emoji: "💵", label: "Efectivo" },
  { id: "Transferencia",  emoji: "🏦", label: "Transferencia" },
  { id: "Nequi",          emoji: "📱", label: "Nequi" },
  { id: "Daviplata",      emoji: "📲", label: "Daviplata" },
  { id: "Pago en oficina",emoji: "🏢", label: "Pago en oficina" },
];
// Cargar desde localStorage si el admin los personalizó
let METODOS_PAGO = (() => {
  try {
    const saved = localStorage.getItem("gc_metodos_pago");
    if (saved) return JSON.parse(saved);
  } catch {}
  return METODOS_PAGO_DEFAULT;
})();
const getMetodoEmoji = (nombre) => (METODOS_PAGO.find(m => m.id === nombre) || METODOS_PAGO_DEFAULT.find(m => m.id === nombre))?.emoji || "💳";
const numeroALetras = (n) => {
  const u = ["","uno","dos","tres","cuatro","cinco","seis","siete","ocho","nueve","diez","once","doce","trece","catorce","quince","dieciséis","diecisiete","dieciocho","diecinueve","veinte","veintiuno","veintidós","veintitrés","veinticuatro","veinticinco","veintiséis","veintisiete","veintiocho","veintinueve"];
  const d = ["","","veinte","treinta","cuarenta","cincuenta","sesenta","setenta","ochenta","noventa"];
  const c = ["","cien","doscientos","trescientos","cuatrocientos","quinientos","seiscientos","setecientos","ochocientos","novecientos"];
  if (n === 0) return "cero";
  if (n < 0) return "menos " + numeroALetras(-n);
  let res = "";
  if (n >= 1000000) { res += numeroALetras(Math.floor(n/1000000)) + " millón "; n %= 1000000; }
  if (n >= 1000) { const m = Math.floor(n/1000); res += (m === 1 ? "mil" : numeroALetras(m) + " mil") + " "; n %= 1000; }
  if (n >= 100) { res += (n === 100 ? "cien" : c[Math.floor(n/100)]) + " "; n %= 100; }
  if (n > 0 && n < 30) { res += u[n]; }
  else if (n >= 30) { res += d[Math.floor(n/10)] + (n % 10 ? " y " + u[n % 10] : ""); }
  return res.trim().toUpperCase() + " PESOS";
};

// ── Componente Recibo de Pago (imprimible) ────────────────
function ModalConfirm({ titulo, mensaje, icono, onConfirm, onCancel }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "#00000066", zIndex: 9999, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && onCancel()}>
      <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 360, boxShadow: "0 20px 60px #00000033", overflow: "hidden" }}>
        <div style={{ padding: "28px 24px 20px", textAlign: "center" }}>
          <div style={{ fontSize: 44, marginBottom: 12 }}>{icono || "🗑️"}</div>
          <div style={{ fontWeight: 800, fontSize: 16, color: GC.ink, marginBottom: 8 }}>{titulo || "¿Eliminar?"}</div>
          <div style={{ fontSize: 13, color: GC.ink3, lineHeight: 1.5 }}>{mensaje || "Esta acción no se puede deshacer."}</div>
        </div>
        <div style={{ display: "flex", borderTop: "1px solid #f1f5f9" }}>
          <button onClick={onCancel} style={{ flex: 1, padding: "14px 0", border: "none", background: GC.bg2, color: GC.ink3, fontWeight: 700, fontSize: 14, cursor: "pointer", borderRight: "1px solid #f1f5f9" }}>Cancelar</button>
          <button onClick={onConfirm} style={{ flex: 1, padding: "14px 0", border: "none", background: "#fef2f2", color: GC.danger, fontWeight: 800, fontSize: 14, cursor: "pointer" }}>Sí, eliminar</button>
        </div>
      </div>
    </div>
  );
}

function ReciboImprimible({ factura, abonos, nombreEmpresa, telefono, onClose, db, usuario }) {
  const totalAbonado = abonos.reduce((s, a) => s + a.monto, 0);
  const descuentoPP  = Number(factura.descuento_pronto_pago || 0);
  const saldo = Math.max(0, factura.monto - totalAbonado - descuentoPP);
  const pagado = saldo <= 0;
  const mostrarAbonos = abonos.length > 0 && !pagado;
  const [qzEstado, setQzEstado] = useState("idle"); // idle | conectando | ok | error
  const [impresoras, setImpresoras] = useState([]);
  const [impresoraSeleccionada, setImpresoraSeleccionada] = useState("");
  const [enviandoCola, setEnviandoCola] = useState(false);

  useEffect(() => {
    if (db) db.getImpresoras().then(list => {
      const activas = list.filter(p => p.activa);
      setImpresoras(activas);
      if (activas.length === 1) setImpresoraSeleccionada(activas[0].id);
    }).catch(() => {});
  }, []);

  // ── Helpers ESC/POS ─────────────────────────────────────────────
  const ESC = "\x1B", GS = "\x1D";
  const INIT      = ESC + "@";
  const ALIGN_CTR = ESC + "a\x01";
  const ALIGN_LFT = ESC + "a\x00";
  const BOLD_ON   = ESC + "E\x01";
  const BOLD_OFF  = ESC + "E\x00";
  const LF        = "\n";
  const CUT       = GS  + "V\x41\x03";
  const COLS      = 40; // TM-U220D: 40 columnas en modo normal
  const SEP_DASH  = "-".repeat(COLS) + LF;
  const SEP_DOT   = ".".repeat(COLS) + LF;

  // Centrar en COLS columnas
  const center = txt => {
    const t = String(txt).slice(0, COLS);
    const pad = Math.max(0, Math.floor((COLS - t.length) / 2));
    return " ".repeat(pad) + t + LF;
  };

  // Dos columnas izq/der — total COLS chars
  const cols = (izq, der) => {
    const l = String(izq).slice(0, COLS - 8);
    const r = String(der).slice(0, 12);
    const espacio = Math.max(1, COLS - l.length - r.length);
    return l + " ".repeat(espacio) + r + LF;
  };

  // Formatear dinero SIN puntos de miles para la impresora de matriz
  // Usa coma como separador de miles (ej: $50,000) compatible con ASCII
  const fCOP = n => {
    const num = Math.round(Number(n) || 0);
    return "$" + num.toLocaleString("en-US").replace(/,/g, ".");
  };

  // ── Construir buffer ESC/POS ─────────────────────────────────────
  const buildEscPos = () => {
    const empresa  = (nombreEmpresa || "GC HOGAR.NET SAS").toUpperCase();
    const tel1     = "Tel: " + (telefono || "318-8255601");
    const tel2     = "Tel: 315-7613752";
    const recibo   = "#" + String(factura.numeroRecibo || factura.id?.slice(-6) || "0").padStart(5,"0");
    const lastAbono = abonos && abonos.length > 0 ? abonos[0] : null;
    const fecha    = lastAbono?.fecha || factura.fechaPago || factura.fechaEmision || new Date().toISOString().split("T")[0];
    const cliente  = (factura.clienteNombre || "").toUpperCase().slice(0, COLS);
    const concepto = (factura.concepto || `MES ${factura.mes||""} ${factura.anio||""}`).toUpperCase().slice(0, 24);

    let d = "";
    d += INIT + LF;

    // Encabezado — centrado manual con espacios
    d += ALIGN_LFT;
    d += center(empresa);
    d += BOLD_OFF + center(tel1);
    d += center(tel2);
    d += SEP_DASH;

    // Recibo, número de pago y fecha
    d += cols("Recibo No.:", recibo);
    // Número de pago consecutivo (se asigna al momento del cobro)
    const numPago = abonos && abonos.length > 0 && abonos[0].numeroPago
      ? "Pago #" + String(abonos[0].numeroPago).padStart(5, "0")
      : null;
    if (numPago) d += cols("No. de pago:", numPago);
    d += cols("Fecha:", fecha);
    d += SEP_DASH;

    // Cliente — centrado manual
    d += BOLD_ON + center(cliente) + BOLD_OFF;
    d += SEP_DASH;

    // Concepto
    d += cols(concepto, fCOP(factura.monto));
    d += SEP_DASH;

    // Detalle pago
    if (pagado) {
      if (descuentoPP > 0) {
        d += cols("Valor factura:", fCOP(factura.monto));
        d += cols("Desc. pronto pago:", "- " + fCOP(descuentoPP));
        d += cols("Valor cancelado:", fCOP(totalAbonado));
        d += SEP_DASH;
      }
      d += BOLD_ON;
      d += cols("VALOR PAGADO:", fCOP(totalAbonado));
      d += BOLD_OFF;
      d += BOLD_ON + center("*** CANCELADO ***") + BOLD_OFF;
    } else {
      d += cols("Total a pagar:", fCOP(factura.monto));
      if (descuentoPP > 0) d += cols("Desc. pronto pago:", "- " + fCOP(descuentoPP));
      d += cols("Abono:", "- " + fCOP(totalAbonado));
      d += SEP_DASH;
      d += BOLD_ON + cols("SALDO PENDIENTE:", fCOP(saldo)) + BOLD_OFF;
    }

    // Método de pago
    if (factura.metodoPago) {
      d += ALIGN_LFT + SEP_DOT;
      d += cols("Metodo de pago:", factura.metodoPago);
    }

    // Firma
    d += LF + SEP_DOT;
    d += ALIGN_CTR;
    d += center("______________________________");
    d += center("Firma secretario/a");
    d += LF + LF + LF;
    d += CUT;

    return d;
  };

  // ── Imprimir con QZ Tray (certificado real + firma via Supabase) ──
  const imprimirQZ = async () => {
    setQzEstado("conectando");
    try {
      // Si qz no está disponible aún, esperar hasta 3 segundos
      if (!window.qz) {
        await new Promise((res, rej) => {
          let intentos = 0;
          const check = setInterval(() => {
            intentos++;
            if (window.qz) { clearInterval(check); res(); }
            else if (intentos > 30) { clearInterval(check); rej(new Error("QZ_NO_CARGADO")); }
          }, 100);
        });
      }

      if (!window.qz) throw new Error("QZ_NO_CARGADO");

      // Conectar WebSocket con QZ Tray local
      if (!qz.websocket.isActive()) {
        await qz.websocket.connect({ retries: 3, delay: 1 });
      }

      // Buscar impresora Epson TM-U220
      let impresora = null;
      try {
        const lista = await qz.printers.find("TM-U220");
        impresora = Array.isArray(lista) ? lista[0] : lista;
      } catch {}
      if (!impresora) impresora = await qz.printers.getDefault();
      if (!impresora) throw new Error("Sin impresora detectada");

      const config = qz.configs.create(impresora, { encoding: "Cp1252", copies: 1, jobName: "GC HOGAR - Recibo" });
      await qz.print(config, [{ type: "raw", format: "plain", data: buildEscPos() }]);

      setQzEstado("ok");
      setTimeout(() => setQzEstado("idle"), 2500);

    } catch (e) {
      console.error("QZ Error:", e);
      setQzEstado("error");
      setTimeout(() => setQzEstado("idle"), 3000);
      const msg = String(e.message || e);

      if (msg === "QZ_NO_CARGADO" || msg.includes("object Event") || msg.includes("No cargado")) {
        alert("El archivo qz-tray.js no esta cargado.\n\nSolucion:\n1. Ve a github.com/qzind/tray\n2. Descarga el archivo js/qz-tray.js\n3. Subelo a la carpeta public/ del repositorio\n4. Recarga la pagina\n\nO usa el boton Navegador mientras tanto.");
      } else if (msg.includes("Unable to establish") || msg.includes("websocket")) {
        alert("QZ Tray no responde.\nVerifica que este corriendo (icono en barra de tareas).");
      } else if (msg.includes("certificate") || msg.includes("unsigned")) {
        alert("Error de certificado.\nClic derecho en QZ Tray → Advanced → Allow unsigned content");
      } else {
        alert("Error: " + msg + "\n\nUsa el boton Navegador.");
      }
    }
  };

  // ── Fallback: imprimir desde navegador ───────────────────────────
  const imprimirNavegador = () => {
    const contenido = document.getElementById("recibo-print").innerHTML;
    const ventana = window.open("", "_blank", "width=380,height=750");
    ventana.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><style>
      * { margin: 0; padding: 0; box-sizing: border-box; }
      html, body { width: 76mm; }
      body { font-family: 'Courier New', Courier, monospace; font-size: 10pt; color: #000; padding: 2mm 3mm; line-height: 1.4; }
      div { word-break: break-word; }
      @page { size: 76mm auto; margin: 2mm 3mm; }
      @media print { html, body { width: 76mm; font-size: 10pt; } button { display: none !important; } }
    </style></head><body>${contenido}</body></html>`);
    ventana.document.close();
    ventana.focus();
    setTimeout(() => { ventana.print(); ventana.close(); }, 600);
  };

  const row = (label, valor, bold = false) => (
    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 3, fontSize: 13, fontWeight: bold ? 700 : 400 }}>
      <span>{label}</span><span>{valor}</span>
    </div>
  );

  const qzLabel = { idle: "🖨️ Imprimir ESC/POS", conectando: "⏳ Conectando...", ok: "✅ Impreso!", error: "❌ Error QZ" }[qzEstado];
  const qzColor = { idle: GC.brand, conectando: "#f59e0b", ok: "#16a34a", error: "#ef4444" }[qzEstado];

  return (
    <div style={{ position: "fixed", inset: 0, background: "#00000077", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 380, maxHeight: "95vh", overflowY: "auto", boxShadow: "0 20px 60px #00000033" }}>
        <div style={{ display: "flex", gap: 8, padding: "14px 16px", borderBottom: "1px solid #e2e8f0", flexWrap: "wrap" }}>
          {/* Selector de impresora si hay varias */}
          {impresoras.length > 1 && (
            <Sel value={impresoraSeleccionada} onChange={e => setImpresoraSeleccionada(e.target.value)} style={{ flex: 2, fontSize: 12 }}>
              <option value="">Seleccionar impresora...</option>
              {impresoras.map(p => <option key={p.id} value={p.id}>{p.nombre} {p.zona_nombre ? "· " + p.zona_nombre : ""}</option>)}
            </Sel>
          )}

          {/* Botón enviar a cola remota */}
          {impresoras.length > 0 && (
            <button onClick={async () => {
              if (!impresoraSeleccionada) { alert("Selecciona una impresora."); return; }
              setEnviandoCola(true);
              try {
                await db.encolarImpresion(impresoraSeleccionada, buildEscPos(), factura.id, usuario?.usuario);
                alert("Trabajo enviado a la impresora. Se imprimirá automáticamente.");
              } catch(e) { alert("Error al enviar: " + e.message); }
              setEnviandoCola(false);
            }} disabled={enviandoCola || !impresoraSeleccionada}
              style={{ flex: 1, background: "#7c3aed", color: "#fff", border: "none", borderRadius: 9, padding: "10px 14px", cursor: "pointer", fontWeight: 700, fontSize: 13, fontFamily: "inherit", opacity: enviandoCola ? 0.7 : 1 }}>
              {enviandoCola ? "⏳ Enviando..." : "📡 " + (impresoras.length === 1 ? impresoras[0].nombre : "Enviar a impresora")}
            </button>
          )}

          {/* Botón principal ESC/POS local */}
          <button onClick={imprimirQZ} disabled={qzEstado === "conectando"}
            style={{ flex: impresoras.length > 0 ? 1 : 2, background: { idle: GC.brand, conectando: "#f59e0b", ok: "#16a34a", error: "#ef4444" }[qzEstado], color: "#fff", border: "none", borderRadius: 9, padding: "10px 14px", cursor: "pointer", fontWeight: 700, fontSize: 13, fontFamily: "inherit", opacity: qzEstado === "conectando" ? 0.7 : 1 }}>
            {{ idle: "🖨️ Este equipo", conectando: "⏳ Conectando...", ok: "✅ Impreso!", error: "❌ Error" }[qzEstado]}
          </button>

          {/* Fallback navegador */}
          <button onClick={imprimirNavegador}
            style={{ background: GC.bg3, color: GC.ink3, border: "none", borderRadius: 9, padding: "10px 10px", cursor: "pointer", fontSize: 12, fontFamily: "inherit" }}>
            🌐
          </button>
          <button onClick={onClose} style={{ background: GC.bg3, border: "none", borderRadius: 8, padding: "9px 14px", cursor: "pointer", fontWeight: 700, fontSize: 13, color: GC.ink3 }}>Cerrar</button>
        </div>

        {/* Banner QZ Tray - solo si no está cargado */}
        <div style={{ background: "#fef3c7", borderBottom: "1px solid #fde047", padding: "6px 14px", fontSize: 11, color: "#92400e" }}>
          💡 Impresión nítida ESC/POS via <a href="https://qz.io" target="_blank" rel="noreferrer" style={{ color: "#d97706", fontWeight: 700 }}>QZ Tray</a>
          {window.qz ? " — listo ✅" : " — no detectado, intenta igual o usa Navegador"}
        </div>

        {/* Preview */}
        <div id="recibo-print" style={{ padding: "8px 12px", fontFamily: "'Courier New', monospace", fontSize: 13, color: "#000", maxWidth: 290, margin: "0 auto", lineHeight: 1.4 }}>

          {/* Empresa */}
          <div style={{ textAlign: "center", marginBottom: 4 }}>
            <div style={{ fontSize: 13, fontWeight: 700 }}>{(nombreEmpresa || "GC HOGAR.NET SAS").toUpperCase()}</div>
            <div style={{ fontSize: 11 }}>Tel.: {telefono || "318-8255601"}</div>
          </div>

          <div style={{ borderTop: "1px dashed #000", margin: "4px 0" }} />

          {/* Número de recibo, número de pago y fecha */}
          {(() => {
            const lastAbono = abonos && abonos.length > 0 ? abonos[0] : null;
            const numPago = lastAbono?.numeroPago;
            const fechaPago = lastAbono?.fecha || factura.fechaPago || factura.fechaEmision || fechaLocal();
            return (
              <>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11 }}>
                  <span>Recibo No.:</span>
                  <span style={{ fontWeight: 700 }}>#{String(factura.numeroRecibo || factura.id?.slice(-6) || "0").padStart(5,"0")}</span>
                </div>
                {numPago && (
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, fontWeight: 800, color: "#7c3aed", marginTop: 2, marginBottom: 2 }}>
                    <span>No. de pago:</span>
                    <span>#{String(numPago).padStart(5,"0")}</span>
                  </div>
                )}
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11 }}>
                  <span>Fecha pago:</span>
                  <span style={{ fontWeight: 700 }}>{fechaPago}</span>
                </div>
              </>
            );
          })()}

          <div style={{ borderTop: "1px dashed #000", margin: "4px 0" }} />

          {/* Quien paga */}
          <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 2 }}>{(factura.clienteNombre || "").toUpperCase()}</div>

          <div style={{ borderTop: "1px dashed #000", margin: "4px 0" }} />

          {/* Concepto */}
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, marginBottom: 3 }}>
            <span>{(factura.concepto || `MES ${factura.mes || ""} ${factura.anio || ""}`).toUpperCase()}</span>
            <span>{formatCOP(factura.monto)}</span>
          </div>

          <div style={{ borderTop: "1px dashed #000", margin: "4px 0" }} />

          {/* Pago completo o abono */}
          {pagado ? (
            <>
              {descuentoPP > 0 && (
                <>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginBottom: 2 }}>
                    <span>Valor factura:</span>
                    <span>{formatCOP(factura.monto)}</span>
                  </div>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginBottom: 2 }}>
                    <span>Desc. pronto pago:</span>
                    <span>- {formatCOP(descuentoPP)}</span>
                  </div>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginBottom: 2 }}>
                    <span>Valor cancelado:</span>
                    <span>{formatCOP(totalAbonado)}</span>
                  </div>
                  <div style={{ borderTop: "1px solid #000", margin: "3px 0" }} />
                </>
              )}
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, fontWeight: 700 }}>
                <span>VALOR PAGADO:</span>
                <span>$ {totalAbonado.toLocaleString("es-CO")}</span>
              </div>
              <div style={{ textAlign: "center", fontSize: 12, marginTop: 3, fontWeight: 700 }}>*** CANCELADO ***</div>
            </>
          ) : (
            <>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginBottom: 2 }}>
                <span>Total a pagar:</span>
                <span>{formatCOP(factura.monto)}</span>
              </div>
              {descuentoPP > 0 && (
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginBottom: 2 }}>
                  <span>Desc. pronto pago:</span>
                  <span>- {formatCOP(descuentoPP)}</span>
                </div>
              )}
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginBottom: 2 }}>
                <span>Abono:</span>
                <span>- {formatCOP(totalAbonado)}</span>
              </div>
              <div style={{ borderTop: "1px solid #000", margin: "3px 0" }} />
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, fontWeight: 700 }}>
                <span>SALDO PENDIENTE:</span>
                <span>$ {saldo.toLocaleString("es-CO")}</span>
              </div>
            </>
          )}

          {/* Método de pago — siempre visible si existe */}
          {factura.metodoPago && (
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, marginTop: 4 }}>
              <span>Metodo de pago:</span>
              <span style={{ fontWeight: 700 }}>{factura.metodoPago}</span>
            </div>
          )}

          <div style={{ borderTop: "1px dashed #000", margin: "6px 0 4px" }} />

          {/* Firma secretario */}
          <div style={{ textAlign: "center", fontSize: 15, marginTop: 18 }}>
            ______________________________
            <div style={{ fontSize: 14, marginTop: 3 }}>Firma secretario/a</div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// ORDEN DE SERVICIO — Contrato de instalación imprimible
// ══════════════════════════════════════════════════════════════
function OrdenServicio({ cliente, perfilesPago = [], numeroContrato, secretario, onClose }) {
  const hoy = fechaLocal();
  const perfil = perfilesPago.find(p => p.id === cliente.perfilPagoId);
  const diasPago = perfil ? `entre el día ${perfil.diaInicio} y ${perfil.diaFin} de cada mes` : "según perfil de pago asignado";

  const buildCopia = (etiqueta) => `
    <div class="copia">
      <div class="header">
        <div class="empresa-info">
          <div class="empresa-nombre">GC HOGAR NET S.A.S</div>
          <div class="empresa-sub">Oficina Vijes, Valle del Cauca &nbsp;·&nbsp; Tel.: 318-8255601</div>
        </div>
        <div class="titulo-doc">
          <div class="doc-titulo">ORDEN DE SERVICIO</div>
          <div class="doc-sub">N° ${String(numeroContrato || "0001").padStart(4,"0")} &nbsp;·&nbsp; ${hoy}</div>
          <div class="copia-label">${etiqueta}</div>
        </div>
      </div>

      <div class="seccion">
        <div class="seccion-titulo">Datos del cliente</div>
        <div class="grid2">
          <div class="campo"><span class="lbl">Nombre completo</span><div class="val">${cliente.nombre || ""}</div></div>
          <div class="campo"><span class="lbl">Cédula / NIT</span><div class="val">${cliente.cedula || ""}</div></div>
          <div class="campo"><span class="lbl">Dirección</span><div class="val">${cliente.direccion || ""}</div></div>
          <div class="campo"><span class="lbl">Teléfono</span><div class="val">${cliente.telefono || ""}</div></div>
          <div class="campo"><span class="lbl">Servicio contratado</span><div class="val">${cliente.servicio || "Internet"}</div></div>
          <div class="campo"><span class="lbl">Plan</span><div class="val">${cliente.plan || "—"}</div></div>
          <div class="campo"><span class="lbl">Valor mensual</span><div class="val">${cliente.monto ? "$ " + Number(cliente.monto).toLocaleString("es-CO") : "—"}</div></div>
          <div class="campo"><span class="lbl">Días de pago</span><div class="val">${diasPago}</div></div>
        </div>
      </div>

      <div class="seccion">
        <div class="seccion-titulo">Equipo entregado en préstamo</div>
        <div class="grid3">
          <div class="campo"><span class="lbl">Tipo de equipo</span><div class="val">&nbsp;</div></div>
          <div class="campo"><span class="lbl">Marca / Modelo</span><div class="val">&nbsp;</div></div>
          <div class="campo"><span class="lbl">Serial / MAC</span><div class="val">&nbsp;</div></div>
        </div>
        <div class="alerta">⚠️ El equipo (ONU / Router) es propiedad de GC HOGAR NET S.A.S y se entrega en calidad de PRÉSTAMO. En caso de pérdida, daño o robo, el cliente deberá asumir <strong>$300.000 COP</strong> por reposición.</div>
      </div>

      <div class="seccion">
        <div class="seccion-titulo">Términos y condiciones</div>
        <div class="terminos">
          <span class="num">1.</span> Uso exclusivo residencial/empresarial. No reventa ni actividades ilícitas. &nbsp;
          <span class="num">2.</span> Pago ${diasPago}; incumplimiento genera suspensión automática. &nbsp;
          <span class="num">3.</span> Reactivación en máx. 24 h hábiles tras el pago. &nbsp;
          <span class="num">4.</span> El equipo técnico instalado es propiedad de GC HOGAR NET S.A.S; el cliente responde por su custodia. &nbsp;
          <span class="num">5.</span> Pérdida/daño del equipo: $300.000 COP. &nbsp;
          <span class="num">6.</span> El cliente autoriza acceso del técnico a su domicilio previo aviso. &nbsp;
          <span class="num">7.</span> Disponibilidad garantizada del 95% mensual; fuerza mayor no genera descuentos. &nbsp;
          <span class="num">8.</span> Contrato de vigencia indefinida; terminación con aviso mínimo de 10 días y devolución de equipos. &nbsp;
          <span class="num">9.</span> El cliente acepta notificaciones de cobro y comunicaciones por los datos suministrados. &nbsp;
          <span class="num">10.</span> La firma constituye aceptación plena de estos términos.
        </div>
      </div>

      <div class="firmas">
        <div class="firma-box">
          <div class="firma-linea"></div>
          <div class="firma-nombre">${(cliente.nombre || "").toUpperCase()}</div>
          <div class="firma-lbl">Firma del cliente · C.C. ${cliente.cedula || ""}</div>
        </div>
        <div class="firma-box">
          <div class="firma-linea"></div>
          <div class="firma-nombre">${(secretario || "").toUpperCase()}</div>
          <div class="firma-lbl">Firma GC HOGAR NET S.A.S</div>
        </div>
      </div>
    </div>
  `;

  const imprimir = () => {
    const ventana = window.open("", "_blank", "width=794,height=1123");
    ventana.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Orden de Servicio</title><style>
      * { margin: 0; padding: 0; box-sizing: border-box; }
      body { font-family: Arial, sans-serif; font-size: 9px; color: #000; background: #fff; }
      .pagina { width: 210mm; padding: 6mm 14mm; }
      .copia { height: 136mm; padding: 5mm 0; border-bottom: 2px dashed #aaa; display: flex; flex-direction: column; gap: 4px; overflow: hidden; }
      .copia:last-child { border-bottom: none; }
      .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2.5px solid #16a34a; padding-bottom: 5px; margin-bottom: 5px; }
      .empresa-nombre { font-size: 13px; font-weight: 900; color: #111; letter-spacing: 0.5px; }
      .empresa-sub { font-size: 8px; color: #555; margin-top: 1px; }
      .titulo-doc { text-align: right; }
      .doc-titulo { font-size: 11px; font-weight: 800; color: #16a34a; }
      .doc-sub { font-size: 8px; color: #666; }
      .copia-label { font-size: 7.5px; font-weight: 700; color: #fff; background: #16a34a; border-radius: 3px; padding: 1px 6px; display: inline-block; margin-top: 2px; }
      .seccion { margin-bottom: 4px; }
      .seccion-titulo { background: #16a34a; color: #fff; font-weight: 700; font-size: 8px; padding: 2px 6px; border-radius: 3px; margin-bottom: 3px; text-transform: uppercase; letter-spacing: 0.4px; }
      .grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 2px 12px; }
      .grid3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 2px 10px; }
      .campo { margin-bottom: 2px; }
      .lbl { font-size: 7px; color: #666; text-transform: uppercase; font-weight: 700; display: block; }
      .val { font-size: 9px; color: #111; border-bottom: 1px solid #bbb; padding: 1px 0; min-height: 13px; }
      .alerta { background: #fef3c7; border: 1px solid #f59e0b; border-radius: 4px; padding: 3px 7px; margin-top: 3px; font-size: 8px; font-weight: 600; color: #92400e; }
      .terminos { font-size: 7.8px; line-height: 1.45; color: #222; }
      .num { font-weight: 700; color: #16a34a; }
      .firmas { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 6px; }
      .firma-box { text-align: center; }
      .firma-linea { border-top: 1px solid #000; margin-top: 16px; margin-bottom: 2px; }
      .firma-nombre { font-size: 8px; font-weight: 700; }
      .firma-lbl { font-size: 7px; color: #555; }
      @media print { @page { size: A4 portrait; margin: 0; } body { margin: 0; } }
    </style></head><body>
      <div class="pagina">
        ${buildCopia("📋 COPIA EMPRESA")}
        ${buildCopia("📄 COPIA CLIENTE")}
      </div>
    </body></html>`);
    ventana.document.close();
    ventana.focus();
    setTimeout(() => { ventana.print(); ventana.close(); }, 500);
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "#00000077", zIndex: 400, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 700, maxHeight: "95vh", overflowY: "auto", boxShadow: "0 20px 60px #00000033" }}>
        {/* Botones */}
        <div style={{ display: "flex", gap: 8, padding: "14px 16px", borderBottom: "1px solid #e2e8f0", position: "sticky", top: 0, background: "#fff", zIndex: 1 }}>
          <Btn onClick={imprimir} style={{ flex: 1, fontSize: 13 }}>🖨️ Imprimir orden de servicio</Btn>
          <button onClick={onClose} style={{ background: GC.bg3, border: "none", borderRadius: 8, padding: "9px 14px", cursor: "pointer", fontWeight: 700, fontSize: 13, color: GC.ink3 }}>Cerrar</button>
        </div>

        {/* Contenido preview — 2 copias */}
        <div style={{ padding: "16px 28px 28px", fontFamily: "Arial, sans-serif", fontSize: 10, color: "#000" }}>
          {[{ label: "📋 COPIA EMPRESA" }, { label: "📄 COPIA CLIENTE" }].map(({ label }, idx) => (
            <div key={idx} style={{ borderBottom: idx === 0 ? "2px dashed #aaa" : "none", paddingBottom: idx === 0 ? 18 : 0, marginBottom: idx === 0 ? 18 : 0 }}>

              {/* Encabezado */}
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", borderBottom: "2.5px solid #16a34a", paddingBottom: 6, marginBottom: 6 }}>
                <div>
                  <div style={{ fontSize: 14, fontWeight: 900, color: "#111" }}>GC HOGAR NET S.A.S</div>
                  <div style={{ fontSize: 9, color: "#555" }}>Oficina Vijes, Valle del Cauca · Tel.: 318-8255601</div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontSize: 12, fontWeight: 800, color: "#16a34a" }}>ORDEN DE SERVICIO</div>
                  <div style={{ fontSize: 9, color: "#666" }}>N° {String(numeroContrato || "0001").padStart(4,"0")} · {hoy}</div>
                  <span style={{ fontSize: 8, fontWeight: 700, color: "#fff", background: "#16a34a", borderRadius: 3, padding: "1px 7px", display: "inline-block", marginTop: 2 }}>{label}</span>
                </div>
              </div>

              {/* Datos del cliente */}
              <div style={{ marginBottom: 6 }}>
                <div style={{ background: "#16a34a", color: "#fff", fontWeight: 700, fontSize: 8.5, padding: "2px 7px", borderRadius: 3, marginBottom: 4, textTransform: "uppercase" }}>Datos del cliente</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "2px 14px" }}>
                  {[["Nombre completo", cliente.nombre], ["Cédula / NIT", cliente.cedula], ["Dirección", cliente.direccion], ["Teléfono", cliente.telefono], ["Servicio contratado", cliente.servicio || "Internet"], ["Plan", cliente.plan || "—"], ["Valor mensual", cliente.monto ? "$ " + Number(cliente.monto).toLocaleString("es-CO") : "—"], ["Días de pago", diasPago]].map(([l, v]) => (
                    <div key={l} style={{ marginBottom: 3 }}>
                      <div style={{ fontSize: 7.5, color: "#666", textTransform: "uppercase", fontWeight: 700 }}>{l}</div>
                      <div style={{ fontSize: 10, color: "#111", borderBottom: "1px solid #ccc", padding: "1px 0", minHeight: 14 }}>{v || <span style={{ color: "#ccc" }}>___</span>}</div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Equipo */}
              <div style={{ marginBottom: 5 }}>
                <div style={{ background: "#16a34a", color: "#fff", fontWeight: 700, fontSize: 8.5, padding: "2px 7px", borderRadius: 3, marginBottom: 4, textTransform: "uppercase" }}>Equipo entregado en préstamo</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "2px 10px", marginBottom: 4 }}>
                  {["Tipo de equipo", "Marca / Modelo", "Serial / MAC"].map(l => (
                    <div key={l}>
                      <div style={{ fontSize: 7.5, color: "#666", textTransform: "uppercase", fontWeight: 700 }}>{l}</div>
                      <div style={{ fontSize: 10, borderBottom: "1px solid #ccc", minHeight: 14 }} />
                    </div>
                  ))}
                </div>
                <div style={{ background: "#fef3c7", border: "1px solid #f59e0b", borderRadius: 4, padding: "4px 8px", fontSize: 8.5, fontWeight: 600, color: "#92400e" }}>
                  ⚠️ El equipo (ONU/Router) es propiedad de GC HOGAR NET S.A.S — PRÉSTAMO. Pérdida/daño: <strong>$300.000 COP</strong>.
                </div>
              </div>

              {/* Términos condensados */}
              <div style={{ marginBottom: 6 }}>
                <div style={{ background: "#16a34a", color: "#fff", fontWeight: 700, fontSize: 8.5, padding: "2px 7px", borderRadius: 3, marginBottom: 4, textTransform: "uppercase" }}>Términos y condiciones</div>
                <div style={{ fontSize: 8, lineHeight: 1.45, color: "#222" }}>
                  <span style={{ fontWeight: 700, color: "#16a34a" }}>1.</span> Uso exclusivo residencial/empresarial. <span style={{ fontWeight: 700, color: "#16a34a" }}>2.</span> Pago {diasPago}; incumplimiento genera suspensión. <span style={{ fontWeight: 700, color: "#16a34a" }}>3.</span> Reactivación en máx. 24 h hábiles. <span style={{ fontWeight: 700, color: "#16a34a" }}>4.</span> Equipo en préstamo; cliente responsable de su custodia. <span style={{ fontWeight: 700, color: "#16a34a" }}>5.</span> Pérdida/daño del equipo: $300.000 COP. <span style={{ fontWeight: 700, color: "#16a34a" }}>6.</span> Cliente autoriza acceso técnico previo aviso. <span style={{ fontWeight: 700, color: "#16a34a" }}>7.</span> Disponibilidad 95% mensual; fuerza mayor sin descuentos. <span style={{ fontWeight: 700, color: "#16a34a" }}>8.</span> Contrato indefinido; terminación con aviso mínimo 10 días y devolución de equipos. <span style={{ fontWeight: 700, color: "#16a34a" }}>9.</span> Cliente acepta notificaciones por datos suministrados. <span style={{ fontWeight: 700, color: "#16a34a" }}>10.</span> La firma constituye aceptación plena.
                </div>
              </div>

              {/* Firmas */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 30, marginTop: 8 }}>
                <div style={{ textAlign: "center" }}>
                  <div style={{ borderTop: "1px solid #000", marginTop: 18, marginBottom: 3 }} />
                  <div style={{ fontSize: 8.5, fontWeight: 700 }}>{(cliente.nombre || "").toUpperCase()}</div>
                  <div style={{ fontSize: 7.5, color: "#555" }}>Firma del cliente · C.C. {cliente.cedula}</div>
                </div>
                <div style={{ textAlign: "center" }}>
                  <div style={{ borderTop: "1px solid #000", marginTop: 18, marginBottom: 3 }} />
                  <div style={{ fontSize: 8.5, fontWeight: 700 }}>{(secretario || "").toUpperCase()}</div>
                  <div style={{ fontSize: 7.5, color: "#555" }}>Firma GC HOGAR NET S.A.S</div>
                </div>
              </div>

            </div>
          ))}
        </div>
      </div>
    </div>
  );
}



