// MÓDULO FACTURACIÓN — Admin y Secretario
// ══════════════════════════════════════════════════════════════
function SeccionProntoPagoReporte({ facturas, usuarios, zonas }) {
  const [filtroMes,  setFiltroMes]  = useState(new Date().getMonth() + 1);
  const [filtroAnio, setFiltroAnio] = useState(new Date().getFullYear());

  const conDescuento = facturas.filter(f =>
    f.pronto_pago_aplicado &&
    Number(f.descuento_pronto_pago) > 0 &&
    f.mes === filtroMes &&
    f.anio === filtroAnio &&
    f.estado !== "Anulada"
  );

  const totalDescuentos = conDescuento.reduce((s, f) => s + Number(f.descuento_pronto_pago || 0), 0);
  const totalCobrado    = conDescuento.reduce((s, f) => s + (f.monto - Number(f.descuento_pronto_pago || 0)), 0);

  return (
    <div>
      <div style={{ display: "flex", gap: 10, alignItems: "center", marginBottom: 16, flexWrap: "wrap" }}>
        <span style={{ fontWeight: 700, color: "#d97706", fontSize: 16 }}>🏷️ Reporte pronto pago</span>
        <Sel value={filtroMes} onChange={e => setFiltroMes(Number(e.target.value))} style={{ width: 130 }}>
          {MESES.map((m, i) => <option key={i} value={i+1}>{m}</option>)}
        </Sel>
        <Sel value={filtroAnio} onChange={e => setFiltroAnio(Number(e.target.value))} style={{ width: 100 }}>
          {[2024,2025,2026,2027].map(a => <option key={a} value={a}>{a}</option>)}
        </Sel>
      </div>

      {/* Resumen */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 10, marginBottom: 16 }}>
        {[
          { label: "Clientes con descuento", val: conDescuento.length, color: "#d97706" },
          { label: "Total descuentos aplicados", val: formatCOP(totalDescuentos), color: "#ef4444" },
          { label: "Total cobrado (con desc.)", val: formatCOP(totalCobrado), color: "#16a34a" },
        ].map(({ label, val, color }) => (
          <div key={label} style={{ background: "#fff", border: "1px solid #e2e8f0", borderTop: "3px solid " + color, borderRadius: 10, padding: "12px 14px" }}>
            <div style={{ fontSize: 11, color: "#64748b", marginBottom: 4 }}>{label}</div>
            <div style={{ fontWeight: 800, fontSize: 18, color }}>{val}</div>
          </div>
        ))}
      </div>

      {/* Lista */}
      {conDescuento.length === 0 ? (
        <div style={{ textAlign: "center", color: "#94a3b8", padding: 40 }}>
          No hay facturas con descuento de pronto pago en {MESES[filtroMes-1]} {filtroAnio}
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {conDescuento.map(f => {
            const desc = Number(f.descuento_pronto_pago || 0);
            const pagado = f.monto - desc;
            return (
              <div key={f.id} style={{ background: "#fff", border: "1px solid #fcd34d", borderLeft: "4px solid #f59e0b", borderRadius: 10, padding: "12px 16px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
                  <div>
                    <div style={{ fontWeight: 700, color: "#111", fontSize: 14 }}>{f.clienteNombre}</div>
                    <div style={{ fontSize: 12, color: "#64748b" }}>Recibo #{f.numeroRecibo} · {f.concepto}</div>
                    <div style={{ fontSize: 12, color: "#64748b", marginTop: 2 }}>Fecha pago: {f.fechaPago || "—"}</div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: 12, color: "#64748b" }}>Valor factura: {formatCOP(f.monto)}</div>
                    <div style={{ fontSize: 12, color: "#ef4444" }}>Descuento: - {formatCOP(desc)}</div>
                    <div style={{ fontWeight: 700, color: "#16a34a", fontSize: 15 }}>Cobrado: {formatCOP(pagado)}</div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ModuloFacturacion({ usuario, usuarios, setUsuarios, zonas, planes, perfilesPago = [], prontoPagos = [] }) {
  const [facturas, setFacturas] = useState([]);
  const [facturasHistoricas, setFacturasHistoricas] = useState([]); // meses anteriores pendientes
  const [facturasAnuladas, setFacturasAnuladas] = useState([]); // todas las anuladas históricas
  const [cargando, setCargando] = useState(true);
  const [subTab, setSubTab] = useState("emitidas");
  const [filtroMes, setFiltroMes]   = useState(new Date().getMonth() + 1);
  const [filtroAnio, setFiltroAnio] = useState(new Date().getFullYear());
  const [filtroZona, setFiltroZona] = useState("todas");

  // ── estados compartidos ──
  const [modalAbono, setModalAbono] = useState(null);
  const [modalRecibo, setModalRecibo] = useState(null);
  const [abonosModal, setAbonosModal] = useState([]);
  const [nuevoAbono, setNuevoAbono] = useState({ monto: "", metodoPago: "Efectivo", observacion: "", fecha: fechaLocal() });
  const [errAbono, setErrAbono] = useState("");
  const [registrandoPago, setRegistrandoPago] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [confirmAnular, setConfirmAnular] = useState(null);

  // hoyStr disponible en todo el módulo
  const hoyStr = fechaLocal();
  // Ref para notificar a SeccionEmitidas que agregue un abono a su estado local
  const agregarAbonoHoyRef = useRef(null);

  const esSuperusuario = usuario.rol === "superusuario";
  const esAdmin = usuario.rol === "admin" || esSuperusuario;
  const esSecretario = usuario.rol === "secretario";
  const zonaId = usuario.zonaId;
  const zonaUsuario = zonas.find(z => z.id === zonaId);
  const nombreEmpresa = zonaUsuario?.nombreEmpresa || "GC HOGAR.NET SAS";
  const clientesVisibles = usuarios.filter(u => {
    if (u.rol !== "cliente" || !u.activo) return false;
    if (!esAdmin) return u.zonaId === zonaId; // secretario solo ve su zona
    if (filtroZona !== "todas") return u.zonaId === filtroZona; // admin filtra por zona
    return true;
  });
  const COLOR_ESTADO = { "Pendiente": "#f59e0b", "Pagado": "#22c55e", "Abono parcial": "#0ea5e9", "Vencido": "#ef4444", "Anulada": "#94a3b8" };

  const filtrarZona = data => esAdmin ? data : data.filter(f => {
    const c = usuarios.find(u => u.id === f.clienteId);
    return c?.zonaId === zonaId;
  });

  const cargarFacturas = async (mes, anio) => {
    setCargando(true);
    try {
      const data = await db.getFacturasByMesAnio(mes, anio);
      setFacturas(filtrarZona(data));
    } catch(e) { console.error("Error cargando facturas:", e); }
    finally { setCargando(false); }
  };

  // Cargar mes actual al inicio y cuando cambia mes/año
  useEffect(() => { cargarFacturas(filtroMes, filtroAnio); }, [filtroMes, filtroAnio]);

  // Cargar facturas históricas (meses anteriores pendientes) para morosos y validación de deuda
  useEffect(() => {
    db.getFacturasUltimosMeses()
      .then(data => setFacturasHistoricas(filtrarZona(data)))
      .catch(() => {});
    db.getFacturasAnuladas()
      .then(data => setFacturasAnuladas(data)) // sin filtrarZona — las anuladas se muestran sin filtro de zona
      .catch(() => {});
  }, []);

  useEffect(() => {
    const canalFacturas = sb.channel("realtime-facturas")
      .on("postgres_changes", { event: "UPDATE", schema: "public", table: "facturas" }, payload => {
        const updated = mapFactura(payload.new);
        setFacturas(prev => {
          const existe = prev.find(f => f.id === updated.id);
          if (!existe && (updated.mes !== filtroMes || updated.anio !== filtroAnio)) return prev;
          if (!existe) return [updated, ...prev];
          return prev.map(f => f.id === updated.id ? updated : f);
        });
        // También actualizar históricos si aplica
        if (updated.saldoPendiente > 0) {
          setFacturasHistoricas(prev => prev.find(f => f.id === updated.id)
            ? prev.map(f => f.id === updated.id ? updated : f)
            : prev);
        } else {
          setFacturasHistoricas(prev => prev.filter(f => f.id !== updated.id));
        }
      })
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "facturas" }, payload => {
        const nueva = mapFactura(payload.new);
        if (nueva.mes === filtroMes && nueva.anio === filtroAnio)
          setFacturas(prev => prev.find(f => f.id === nueva.id) ? prev : [nueva, ...prev]);
      })
      .on("postgres_changes", { event: "DELETE", schema: "public", table: "facturas" }, payload => {
        setFacturas(prev => prev.filter(f => f.id !== payload.old.id));
        setFacturasHistoricas(prev => prev.filter(f => f.id !== payload.old.id));
      })
      .subscribe();
    const canalAbonos = sb.channel("realtime-abonos")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "abonos" }, () => {
        db.getAbonosByFecha(fechaLocal()).then(data => {
          if (agregarAbonoHoyRef?.current?.recargar) agregarAbonoHoyRef.current.recargar(data);
        }).catch(() => {});
      }).subscribe();
    return () => { sb.removeChannel(canalFacturas); sb.removeChannel(canalAbonos); };
  }, [filtroMes, filtroAnio]);

  // ── registrar abono ──
  const registrarAbono = async () => {
    if (registrandoPago) return; // evitar doble clic / doble pago
    setErrAbono("");
    const monto = Number(nuevoAbono.monto);
    if (!monto || monto <= 0) { setErrAbono("Ingresa un monto válido."); return; }
    if (monto > modalAbono.saldoPendiente) { setErrAbono(`Máximo: ${formatCOP(modalAbono.saldoPendiente)}`); return; }

    // Validar que el ID de factura exista (son IDs de texto corto, no UUIDs)
    if (!modalAbono.id) {
      setErrAbono(`Error interno: factura sin ID. Cierra este modal y recarga la página.`);
      return;
    }

    setRegistrandoPago(true);
    try {
      // Verificar si aplica pronto pago
      const cliente = usuarios.find(u => u.id === modalAbono.clienteId);
      const diaHoy = new Date().getDate();
      let descuentoPP = 0;
      if (cliente) {
        // Buscar descuento específico para el plan del cliente, o el genérico de la zona
        const ppEspecifico = prontoPagos.find(p =>
          p.activo &&
          p.zona_id === cliente.zonaId &&
          diaHoy <= (p.dia_limite || 10) &&
          p.plan_id === cliente.planId
        );
        const ppGenerico = prontoPagos.find(p =>
          p.activo &&
          p.zona_id === cliente.zonaId &&
          diaHoy <= (p.dia_limite || 10) &&
          !p.plan_id
        );
        const pp = ppEspecifico || ppGenerico;
        if (pp) descuentoPP = Number(pp.descuento) || 0;
      }

      const abono = await db.registrarAbono({ ...nuevoAbono, monto, facturaId: modalAbono.id, registradoPor: usuario.id });
      const nuevoSaldo = Math.max(0, modalAbono.saldoPendiente - monto - descuentoPP);
      const nuevoEstado = nuevoSaldo <= 0 ? "Pagado" : "Abono parcial";
      const nuevaFechaPago = nuevoSaldo <= 0 ? nuevoAbono.fecha : null;
      await db.actualizarFactura(modalAbono.id, { saldo_pendiente: nuevoSaldo, estado: nuevoEstado, metodo_pago: nuevoAbono.metodoPago, fecha_pago: nuevaFechaPago, descuento_pronto_pago: descuentoPP, pronto_pago_aplicado: descuentoPP > 0 });
      const facturaActualizada = { saldoPendiente: nuevoSaldo, estado: nuevoEstado, metodoPago: nuevoAbono.metodoPago, fechaPago: nuevaFechaPago, descuento_pronto_pago: descuentoPP, pronto_pago_aplicado: descuentoPP > 0 };
      setFacturas(prev => prev.map(f => f.id === modalAbono.id ? { ...f, ...facturaActualizada } : f));
      setFacturasHistoricas(prev => prev.map(f => f.id === modalAbono.id ? { ...f, ...facturaActualizada } : f));
      // También actualizar resultadosBusqueda si está activo en SeccionEmitidas
      if (agregarAbonoHoyRef.current?.actualizarFactura) {
        agregarAbonoHoyRef.current.actualizarFactura(modalAbono.id, facturaActualizada);
      }
      setAbonosModal(prev => [abono, ...prev]);
      if (abono.fecha === hoyStr && agregarAbonoHoyRef.current?.agregar) {
        agregarAbonoHoyRef.current.agregar(abono);
      }
      setModalAbono(prev => ({ ...prev, saldoPendiente: nuevoSaldo, estado: nuevoEstado, fechaPago: nuevaFechaPago, metodoPago: nuevoAbono.metodoPago }));
      setNuevoAbono({ monto: "", metodoPago: "Efectivo", observacion: "", fecha: fechaLocal() });
      if (descuentoPP > 0 && nuevoSaldo <= 0) {
        alert(`Pago registrado con descuento de pronto pago.\nDescuento aplicado: ${formatCOP(descuentoPP)}`);
      }

      // Reconexion automatica si el cliente estaba en DPP
      if (modalAbono.clienteId) {
        const clienteActual = usuarios.find(u => u.id === modalAbono.clienteId);
        if (clienteActual && clienteActual.estado === "DPP" && clienteActual.wisproUuid) {
          try {
            await db.upsertUsuario({ ...clienteActual, estado: "Al día" });
            if (setUsuarios) setUsuarios(prev => prev.map(u => u.id === clienteActual.id ? { ...u, estado: "Al día" } : u));
            const res = await wispro.reconectarServicio(clienteActual.wisproUuid, clienteActual.zonaId, zonas, clienteActual.ip || null);
            await wispro.logAccion(clienteActual.id, clienteActual.nombre, "RECONEXION_PAGO", res);
            alert(`Pago registrado.\nServicio de ${clienteActual.nombre} reconectado en Wispro.`);
          } catch (err) {
            await wispro.logAccion(modalAbono.clienteId, modalAbono.clienteNombre, "RECONEXION_PAGO", null, err.message);
            alert(`Pago registrado.\nNo se pudo reconectar en Wispro: ${err.message}`);
          }
        }
      }
    } catch (e) { setErrAbono("Error: " + e.message); }
    finally { setRegistrandoPago(false); }
  };

  const abrirDetalle = async (f) => {
    // Verificar deuda anterior: combina facturas del mes actual + históricas
    const todasFacturasCliente = [...facturas, ...facturasHistoricas]
      .filter((x, i, arr) => arr.findIndex(y => y.id === x.id) === i); // dedup
    const mesFactura = f.anio * 12 + f.mes;
    const deudaAnterior = todasFacturasCliente.filter(x =>
      x.clienteId === f.clienteId &&
      x.id !== f.id &&
      x.estado !== "Anulada" &&
      x.saldoPendiente > 0 &&
      (x.anio * 12 + x.mes) < mesFactura
    ).sort((a, b) => (a.anio * 12 + a.mes) - (b.anio * 12 + b.mes));

    if (deudaAnterior.length > 0) {
      const mesesDeuda = deudaAnterior.map(x => `${MESES[(x.mes||1)-1]} ${x.anio}: ${formatCOP(x.saldoPendiente)}`).join("\n");
      const totalDeuda = deudaAnterior.reduce((s, x) => s + x.saldoPendiente, 0);
      alert(`⚠️ ${f.clienteNombre} tiene ${deudaAnterior.length} mes(es) sin pagar anteriores.\n\nDebe pagar primero:\n${mesesDeuda}\n\nDeuda anterior total: ${formatCOP(totalDeuda)}\n\nCobra los meses anteriores antes de cobrar este.`);
      return;
    }

    setModalAbono(f);
    setAbonosModal([]);
    try { const abs = await db.getAbonos(f.id); setAbonosModal(abs); } catch {}
  };

  // ── Botones de acción sobre una factura ──
  const AccionesFact = ({ f }) => (
    <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
      {f.estado !== "Anulada" && f.estado !== "Pagado" && (
        <button onClick={() => abrirDetalle(f)}
          style={{ background: "#eff6ff", color: GC.info, border: "none", borderRadius: 7, padding: "5px 9px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
          💵 Cobrar
        </button>
      )}
      {f.estado === "Pagado" && (
        <button onClick={() => abrirDetalle(f)}
          style={{ background: GC.bg3, color: GC.ink2, border: "none", borderRadius: 7, padding: "5px 9px", cursor: "pointer", fontSize: 12 }}>
          👁️ Ver
        </button>
      )}
      <button onClick={async () => {
        const abs = await db.getAbonos(f.id).catch(() => []);
        setModalRecibo({ factura: f, abonos: abs });
      }} style={{ background: GC.brandLight, color: GC.brand, border: "none", borderRadius: 7, padding: "5px 9px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
        🖨️
      </button>
      {/* Anular: solo admin y superusuario */}
      {f.estado !== "Anulada" && (esSuperusuario || esAdmin) && (
        <button onClick={() => setConfirmAnular({ id: f.id, nombre: f.clienteNombre })}
          style={{ background: "#fffbeb", color: "#d97706", border: "none", borderRadius: 7, padding: "5px 9px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}
          title="Anular factura">🚫</button>
      )}
      {/* Eliminar: admin y superusuario */}
      {esAdmin && (
        <button onClick={() => setConfirmDelete({ id: f.id, nombre: f.clienteNombre })}
          style={{ background: "#fef2f2", color: GC.danger, border: "none", borderRadius: 7, padding: "5px 9px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}
          title="Eliminar permanentemente">🗑️</button>
      )}
    </div>
  );

  const TABS = [
    { key: "emitidas", icon: "🧾", label: "Emitidas" },
    { key: "cierre",   icon: "💼", label: "Cierre de caja" },
    { key: "historial",icon: "🔍", label: "Historial" },
    { key: "prontopago", icon: "🏷️", label: "Pronto pago" },
    { key: "caja",     icon: "💰", label: "Caja" },
  ];

  return (
    <div>
      {/* Banner de zona activa — confirma a dónde se asignan los cobros y facturas nuevas que se creen */}
      {esAdmin && zonas.length > 1 && (() => {
        const zonaActiva = filtroZona !== "todas" ? zonas.find(z => z.id === filtroZona) : null;
        return zonaActiva ? (
          <div style={{ background: zonaActiva.color + "15", border: "1px solid " + zonaActiva.color + "33", borderRadius: 10, padding: "8px 14px", marginBottom: 16, display: "flex", alignItems: "center", gap: 8 }}>
            <span>📍</span>
            <span style={{ color: zonaActiva.color, fontSize: 13, fontWeight: 700 }}>Zona activa: {zonaActiva.nombre}</span>
            <span style={{ color: GC.ink3, fontSize: 12 }}>· Los cobros y facturas nuevas se asignan a esta zona</span>
          </div>
        ) : (
          <div style={{ background: "#f1f5f9", border: "1px solid #e2e8f0", borderRadius: 10, padding: "8px 14px", marginBottom: 16, display: "flex", alignItems: "center", gap: 8 }}>
            <span>🌐</span>
            <span style={{ color: GC.ink2, fontSize: 13, fontWeight: 700 }}>Viendo todas las zonas</span>
            <span style={{ color: GC.ink3, fontSize: 12 }}>· Selecciona una zona arriba antes de cobrar o crear facturas, para no asignarlas a la zona incorrecta</span>
          </div>
        );
      })()}
      {/* ── Mini menú ── */}
      <div style={{ display: "flex", gap: 4, marginBottom: 20, background: GC.bg3, borderRadius: 12, padding: 4 }}>
        {TABS.map(t => (
          <button key={t.key} onClick={() => setSubTab(t.key)}
            style={{ flex: 1, padding: "9px 6px", borderRadius: 9, border: "none", cursor: "pointer",
              background: subTab === t.key ? GC.ink : "transparent",
              color: subTab === t.key ? "#fff" : GC.ink3,
              fontWeight: subTab === t.key ? 700 : 500, fontSize: 13, fontFamily: "inherit",
              display: "flex", alignItems: "center", justifyContent: "center", gap: 5 }}>
            <span>{t.icon}</span><span>{t.label}</span>
          </button>
        ))}
      </div>

      {/* ── Modales globales ── */}
      {confirmDelete && (
        <ModalConfirm titulo="¿Eliminar factura?" icono="🗑️"
          mensaje={`Se eliminará permanentemente la factura de ${confirmDelete.nombre}. Esta acción no se puede deshacer.`}
          onCancel={() => setConfirmDelete(null)}
          onConfirm={async () => {
            try {
              // Eliminar abonos primero para que no queden huérfanos y no sigan sumando
              await db.deleteAbonosByFactura(confirmDelete.id);
              await db.deleteFactura(confirmDelete.id);
              setFacturas(p => p.filter(x => x.id !== confirmDelete.id));
              setFacturasHistoricas(p => p.filter(x => x.id !== confirmDelete.id));
              setFacturasAnuladas(p => p.filter(x => x.id !== confirmDelete.id));
              if (agregarAbonoHoyRef?.current?.limpiarFactura) agregarAbonoHoyRef.current.limpiarFactura(confirmDelete.id);
              if (agregarAbonoHoyRef?.current?.eliminarFactura) agregarAbonoHoyRef.current.eliminarFactura(confirmDelete.id);
            }
            catch(e) { alert("Error: " + e.message); }
            setConfirmDelete(null);
          }} />
      )}
      {confirmAnular && (
        <ModalConfirm titulo="¿Anular factura?" icono="🚫"
          mensaje={`Se anulará la factura de ${confirmAnular.nombre} y se eliminarán sus abonos. El contador "Cobrado hoy" se actualizará automáticamente.`}
          onCancel={() => setConfirmAnular(null)}
          onConfirm={async () => {
            try {
              const facturaReal = facturas.find(f => f.id === confirmAnular.id) ||
                                  facturasHistoricas?.find(f => f.id === confirmAnular.id);
              const montoReal = facturaReal?.monto || 0;
              // 1. Eliminar TODOS los abonos de esta factura en Supabase
              //    para que no sigan sumando en "Cobrado hoy" ni en el historial
              await db.deleteAbonosByFactura(confirmAnular.id);
              // 2. Marcar factura como Anulada con saldo = monto (no suma en totalGlobal)
              await db.actualizarFactura(confirmAnular.id, {
                estado: "Anulada",
                saldo_pendiente: montoReal,
                metodo_pago: null,
                fecha_pago: null,
              });
              setFacturas(p => p.map(f => f.id === confirmAnular.id
                ? { ...f, estado: "Anulada", saldoPendiente: montoReal, metodoPago: null, fechaPago: null }
                : f
              ));
              // 3. Limpiar del estado local de abonosHoy para actualizar contador inmediatamente
              if (agregarAbonoHoyRef?.current?.limpiarFactura) {
                agregarAbonoHoyRef.current.limpiarFactura(confirmAnular.id);
              }
            } catch(e) { alert("Error al anular: " + e.message); }
            setConfirmAnular(null);
          }} />
      )}

      {/* ── Modal registrar abono/cobro ── */}
      {modalAbono && (
        <div style={{ position: "fixed", inset: 0, background: "#00000055", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
          onClick={e => { if (e.target === e.currentTarget) { setModalAbono(null); setErrAbono(""); } }}>
          <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "100%", maxWidth: 460, maxHeight: "92vh", overflowY: "auto", position: "relative" }}>
            <button onClick={() => { setModalAbono(null); setErrAbono(""); }}
              style={{ position: "absolute", top: 14, right: 14, background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            <button onClick={async () => {
              const abs = await db.getAbonos(modalAbono.id).catch(() => []);
              setModalRecibo({ factura: modalAbono, abonos: abs });
            }} style={{ position: "absolute", top: 14, right: 54, background: GC.brandLight, color: GC.brand, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 16 }} title="Imprimir tirilla">🖨️</button>
            <h3 style={{ margin: "0 0 4px", color: GC.ink, fontSize: 16 }}>💵 Pago / Abono</h3>
            <p style={{ margin: "0 0 16px", color: GC.ink3, fontSize: 13 }}>{modalAbono.clienteNombre} · {modalAbono.concepto}</p>
            <div style={{ background: GC.bg2, border: "1px solid " + GC.border, borderRadius: 10, padding: "12px 14px", marginBottom: 16 }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                <span style={{ fontSize: 13, color: GC.ink3 }}>Total factura:</span><strong>{formatCOP(modalAbono.monto)}</strong>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 4 }}>
                <span style={{ fontSize: 13, color: GC.ink3 }}>Total abonado:</span>
                <span style={{ color: GC.brand }}>{formatCOP(modalAbono.monto - modalAbono.saldoPendiente)}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", borderTop: "1px solid #e2e8f0", paddingTop: 6, marginTop: 4 }}>
                <span style={{ fontSize: 14, fontWeight: 700 }}>Saldo pendiente:</span>
                <strong style={{ color: modalAbono.saldoPendiente > 0 ? "#ef4444" : "#22c55e", fontSize: 16 }}>{formatCOP(modalAbono.saldoPendiente)}</strong>
              </div>
            </div>
            {abonosModal.length > 0 && (
              <div style={{ marginBottom: 16 }}>
                <div style={{ fontSize: 11, color: GC.ink3, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 8 }}>Abonos anteriores</div>
                {abonosModal.map((a, i) => (
                  <div key={i} style={{ display: "flex", justifyContent: "space-between", background: GC.brandLight, border: "1px solid #bbf7d0", borderRadius: 8, padding: "8px 12px", marginBottom: 6, fontSize: 13 }}>
                    <div><span style={{ fontWeight: 600, color: GC.brand }}>{formatCOP(a.monto)}</span><span style={{ color: GC.ink3, marginLeft: 8 }}>{a.metodoPago}</span></div>
                    <span style={{ color: GC.ink4, fontSize: 12 }}>{a.fecha}</span>
                  </div>
                ))}
              </div>
            )}
            {modalAbono.saldoPendiente > 0 && (
              <div>
                <div style={{ fontSize: 11, color: GC.ink3, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 10 }}>Registrar pago / abono</div>
                {/* Indicador de pronto pago */}
                {(() => {
                  const cliente = usuarios.find(u => u.id === modalAbono.clienteId);
                  const diaHoy = new Date().getDate();
                  if (!cliente) return null;
                  const ppEspecifico = prontoPagos.find(p =>
                    p.activo && p.zona_id === cliente.zonaId &&
                    diaHoy <= (p.dia_limite || 10) && p.plan_id === cliente.planId
                  );
                  const ppGenerico = prontoPagos.find(p =>
                    p.activo && p.zona_id === cliente.zonaId &&
                    diaHoy <= (p.dia_limite || 10) && !p.plan_id
                  );
                  const pp = ppEspecifico || ppGenerico;
                  if (!pp) return null;
                  const descuento = Number(pp.descuento);
                  const valorConDescuento = Math.max(0, modalAbono.saldoPendiente - descuento);
                  return (
                    <div style={{ background: "#fef3c7", border: "2px solid #f59e0b", borderRadius: 10, padding: "10px 14px", marginBottom: 14 }}>
                      <div style={{ fontWeight: 700, color: "#d97706", fontSize: 13, marginBottom: 4 }}>
                        🏷️ Pronto pago disponible hoy
                      </div>
                      <div style={{ fontSize: 12, color: "#92400e" }}>
                        Si paga hoy (dia {diaHoy}, antes del dia {pp.dia_limite}) aplica descuento de <strong>{formatCOP(descuento)}</strong>
                        {ppEspecifico ? ` (plan ${cliente.plan})` : " (descuento general)"}
                      </div>
                      <div style={{ fontSize: 13, color: "#92400e", marginTop: 4, fontWeight: 700 }}>
                        Valor con descuento: {formatCOP(valorConDescuento)}
                      </div>
                      <button onClick={() => setNuevoAbono({ ...nuevoAbono, monto: String(valorConDescuento) })}
                        style={{ marginTop: 8, background: "#f59e0b", color: "#fff", border: "none", borderRadius: 7, padding: "6px 14px", cursor: "pointer", fontWeight: 700, fontSize: 12 }}>
                        Aplicar descuento
                      </button>
                    </div>
                  );
                })()}
                <Field label="Monto (COP)">
                  <Inp type="number" value={nuevoAbono.monto} onChange={e => setNuevoAbono({ ...nuevoAbono, monto: e.target.value })} placeholder={`Máx: ${formatCOP(modalAbono.saldoPendiente)}`} />
                  <div style={{ display: "flex", gap: 6, marginTop: 6, flexWrap: "wrap" }}>
                    {[modalAbono.saldoPendiente, Math.round(modalAbono.saldoPendiente / 2)].filter(v => v > 0).map(v => (
                      <button key={v} onClick={() => setNuevoAbono({ ...nuevoAbono, monto: String(v) })}
                        style={{ background: "#eff6ff", color: GC.info, border: "1px solid #bfdbfe", borderRadius: 6, padding: "4px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
                        {v === modalAbono.saldoPendiente ? "Pago completo" : "50%"} ({formatCOP(v)})
                      </button>
                    ))}
                  </div>
                </Field>
                <Field label="Método de pago">
                  <Sel value={nuevoAbono.metodoPago} onChange={e => setNuevoAbono({ ...nuevoAbono, metodoPago: e.target.value })}>
                    {METODOS_PAGO.map(m => <option key={m.id} value={m.id}>{m.emoji} {m.label}</option>)}
                  </Sel>
                </Field>
                <Field label="Fecha de pago"><Inp type="date" value={nuevoAbono.fecha} onChange={e => setNuevoAbono({ ...nuevoAbono, fecha: e.target.value })} /></Field>
                <Field label="Observación (opcional)"><Inp value={nuevoAbono.observacion} onChange={e => setNuevoAbono({ ...nuevoAbono, observacion: e.target.value })} /></Field>
                {errAbono && <div style={{ color: GC.danger, fontSize: 13, marginBottom: 10 }}>⚠️ {errAbono}</div>}
                <button
                  onClick={registrarAbono}
                  disabled={registrandoPago}
                  style={{
                    width: "100%", padding: "13px 0", fontSize: 15, fontWeight: 800,
                    background: registrandoPago ? "#94a3b8" : "#16a34a",
                    color: "#ffffff",
                    border: "none", borderRadius: 10,
                    cursor: registrandoPago ? "not-allowed" : "pointer",
                    opacity: registrandoPago ? 0.7 : 1,
                    fontFamily: "inherit",
                    display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                    boxShadow: registrandoPago ? "none" : "0 2px 8px #16a34a44",
                  }}>
                  {registrandoPago ? <><span style={{fontSize:16}}>⏳</span> Registrando...</> : <><span style={{fontSize:16}}>✅</span> Registrar pago</>}
                </button>
              </div>
            )}
            {modalAbono.saldoPendiente <= 0 && (
              <div style={{ background: GC.brandLight, border: "1px solid #bbf7d0", borderRadius: 10, padding: 16, textAlign: "center" }}>
                <div style={{ fontSize: 28, marginBottom: 6 }}>✅</div>
                <div style={{ fontWeight: 700, color: GC.brand, marginBottom: 12 }}>Factura cancelada en su totalidad</div>
                <button onClick={async () => {
                  const abs = await db.getAbonos(modalAbono.id).catch(() => []);
                  setModalRecibo({ factura: modalAbono, abonos: abs });
                }} style={{ background: GC.brand, color: "#fff", border: "none", borderRadius: 8, padding: "10px 24px", cursor: "pointer", fontSize: 14, fontWeight: 700, display: "inline-flex", alignItems: "center", gap: 6 }}>
                  🖨️ Imprimir tirilla
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ── Modal recibo ── */}
      {modalRecibo && (
        <ReciboImprimible factura={modalRecibo.factura} abonos={modalRecibo.abonos}
          nombreEmpresa={nombreEmpresa} telefono="318-8255601" onClose={() => setModalRecibo(null)}
          db={db} usuario={usuario} />
      )}

      {/* ════════════════════════════════════════════════════ */}
      {/* TAB 1 — EMITIDAS                                    */}
      {/* ════════════════════════════════════════════════════ */}
      {subTab === "emitidas" && (
        <SeccionEmitidas
          usuario={usuario} facturas={facturas} setFacturas={setFacturas}
          facturasHistoricas={facturasHistoricas} facturasAnuladas={facturasAnuladas}
          cargando={cargando} usuarios={usuarios} zonas={zonas}
          planes={planes} perfilesPago={perfilesPago}
          clientesVisibles={clientesVisibles} nombreEmpresa={nombreEmpresa}
          esAdmin={esAdmin} esSuperusuario={esSuperusuario}
          COLOR_ESTADO={COLOR_ESTADO} AccionesFact={AccionesFact}
          agregarAbonoHoyRef={agregarAbonoHoyRef}
          prontoPagos={prontoPagos} setUsuarios={setUsuarios}
          filtroMes={filtroMes} setFiltroMes={setFiltroMes}
          filtroAnio={filtroAnio} setFiltroAnio={setFiltroAnio}
          filtroZona={filtroZona} setFiltroZona={setFiltroZona}
        />
      )}

      {/* ════════════════════════════════════════════════════ */}
      {/* TAB 2 — CIERRE DE CAJA                              */}
      {/* ════════════════════════════════════════════════════ */}
      {subTab === "cierre" && (
        <SeccionCierreCaja
          usuario={usuario} facturas={facturas} facturasHistoricas={facturasHistoricas}
          usuarios={usuarios}
          zonas={zonas} esAdmin={esAdmin} esSuperusuario={esSuperusuario}
          nombreEmpresa={nombreEmpresa} COLOR_ESTADO={COLOR_ESTADO}
        />
      )}

      {/* ════════════════════════════════════════════════════ */}
      {/* TAB 3 — HISTORIAL Y AUDITORÍA                       */}
      {/* ════════════════════════════════════════════════════ */}
      {subTab === "historial" && (
        <SeccionHistorial
          usuario={usuario} facturas={facturas} setFacturas={setFacturas}
          facturasHistoricas={facturasHistoricas}
          usuarios={usuarios} zonas={zonas}
          esAdmin={esAdmin} esSuperusuario={esSuperusuario}
          COLOR_ESTADO={COLOR_ESTADO} AccionesFact={AccionesFact}
          nombreEmpresa={nombreEmpresa}
          setConfirmDelete={setConfirmDelete} setConfirmAnular={setConfirmAnular}
          agregarAbonoHoyRef={agregarAbonoHoyRef}
        />
      )}

      {subTab === "prontopago" && (
        <SeccionProntoPagoReporte facturas={[...facturas, ...facturasHistoricas].filter((f,i,arr)=>arr.findIndex(x=>x.id===f.id)===i)} usuarios={usuarios} zonas={zonas} />
      )}

      {/* ════════════════════════════════════════════════════ */}
      {/* TAB CAJA — movimientos + saldo base admin            */}
      {/* ════════════════════════════════════════════════════ */}
      {subTab === "caja" && (
        <ModuloCaja usuario={usuario} esAdmin={esAdmin || esSuperusuario} facturas={facturas} nombreEmpresa={nombreEmpresa} zonas={zonas} />
      )}
    </div>
  );
}

// ── Sección 1: Emitidas ───────────────────────────────────────
function SeccionEmitidas({ usuario, facturas, setFacturas, facturasHistoricas = [], facturasAnuladas = [], cargando, usuarios, zonas, planes, perfilesPago, clientesVisibles, nombreEmpresa, esAdmin, esSuperusuario, COLOR_ESTADO, AccionesFact, agregarAbonoHoyRef, prontoPagos = [], setUsuarios, filtroMes: filtroMesProp, setFiltroMes: setFiltroMesProp, filtroAnio: filtroAnioProp, setFiltroAnio: setFiltroAnioProp, filtroZona: filtroZonaProp, setFiltroZona: setFiltroZonaProp }) {
  // filtroMes/filtroAnio/filtroZona vienen del padre (ModuloFacturacion)
  const filtroMes     = filtroMesProp    ?? new Date().getMonth() + 1;
  const setFiltroMes  = setFiltroMesProp ?? (() => {});
  const filtroAnio    = filtroAnioProp   ?? new Date().getFullYear();
  const setFiltroAnio = setFiltroAnioProp ?? (() => {});
  const filtroZona    = filtroZonaProp   ?? "todas";
  const setFiltroZona = setFiltroZonaProp ?? (() => {});
  const [busq, setBusq] = useState("");
  const [filtroEstado, setFiltroEstado] = useState("todos");
  const [showGenerarMasivo, setShowGenerarMasivo] = useState(false);
  const [generandoMasivo, setGenerandoMasivo] = useState(false);
  const [showFormManual, setShowFormManual] = useState(false);
  const [facturaManual, setFacturaManual] = useState({ clienteId: "", mes: new Date().getMonth() + 1, anio: new Date().getFullYear(), notas: "", items: [] });
  const [guardandoManual, setGuardandoManual] = useState(false);
  const [tirilla, setTirilla] = useState(null);
  const [modalExport, setModalExport] = useState(null);
  const [exportando, setExportando] = useState(false);
  const [movimientosCaja, setMovimientosCaja] = useState([]);
  const [totalCobradoGlobal, setTotalCobradoGlobal] = useState(null);
  const [totalCobradoPorZona, setTotalCobradoPorZona] = useState({});
  const [abonosHoy, setAbonosHoy] = useState([]);
  const [observacionesPorFactura, setObservacionesPorFactura] = useState({});
  const [resultadosBusqueda, setResultadosBusqueda] = useState([]);
  const [buscandoDB, setBuscandoDB] = useState(false);
  const busqTimerRef = useRef(null);

  const hoyStr = fechaLocal();

  // Busqueda con debounce directo en Supabase para encontrar facturas de cualquier mes
  useEffect(() => {
    const q = busq.trim();
    if (q.length < 2) { setResultadosBusqueda([]); setBuscandoDB(false); return; }
    setBuscandoDB(true);
    clearTimeout(busqTimerRef.current);
    busqTimerRef.current = setTimeout(async () => {
      try {
        // Un secretario (no admin) SIEMPRE busca solo en su propia zona — nunca puede ver la otra.
        // Un admin busca en la zona que tenga seleccionada en el filtro, o en todas si eligió "Todas".
        const zonaParaBuscar = !esAdmin ? usuario?.zonaId : (filtroZona !== "todas" ? filtroZona : null);
        const res = await db.buscarFacturasPorNombre(q, zonaParaBuscar);
        setResultadosBusqueda(res);
      } catch { setResultadosBusqueda([]); }
      finally { setBuscandoDB(false); }
    }, 400);
    return () => clearTimeout(busqTimerRef.current);
  }, [busq, esAdmin, filtroZona, usuario?.zonaId]);

  // Exponer funciones para que ModuloFacturacion pueda modificar abonosHoy sin prop drilling
  useEffect(() => {
    if (agregarAbonoHoyRef) {
      agregarAbonoHoyRef.current = {
        // Agregar un abono nuevo al estado local
        agregar: (abono) => {
          setAbonosHoy(prev => [abono, ...prev]);
          // Si el abono trae observación, refrescarla de inmediato en la lista (sin esperar a recargar)
          if (abono?.observacion && abono?.facturaId) {
            setObservacionesPorFactura(prev => ({ ...prev, [abono.facturaId]: abono.observacion }));
          }
        },
        // Quitar todos los abonos de una factura (al eliminar o anular)
        limpiarFactura: (facturaId) => {
          setAbonosHoy(prev => prev.filter(a => a.facturaId !== facturaId));
          setObservacionesPorFactura(prev => {
            const copia = { ...prev };
            delete copia[facturaId];
            return copia;
          });
        },
        // Actualizar estado de factura en resultadosBusqueda (para que el cambio se vea sin recargar)
        actualizarFactura: (facturaId, cambios) => {
          setResultadosBusqueda(prev => prev.map(f => f.id === facturaId ? { ...f, ...cambios } : f));
        },
        // Eliminar factura de todos los estados locales
        eliminarFactura: (facturaId) => {
          setResultadosBusqueda(prev => prev.filter(f => f.id !== facturaId));
        },
      };
    }
    return () => { if (agregarAbonoHoyRef) agregarAbonoHoyRef.current = null; };
  }, [agregarAbonoHoyRef]);

  useEffect(() => {
    // Un secretario solo carga/ve la caja y el total de SU zona. Admin ve todo (sin filtro).
    const zonaPropia = !esAdmin ? usuario?.zonaId : null;
    db.getMovimientosCaja(zonaPropia).then(setMovimientosCaja).catch(() => {});
    // Cargar total global cobrado histórico desde abonos (suma real de todos los pagos)
    db.getTotalCobradoGlobal(zonaPropia).then(setTotalCobradoGlobal).catch(e => console.warn("Error cargando total global:", e?.message));
    // Cargar totales por zona para que el global por zona sea preciso
    db.getTotalCobradoPorZona().then(setTotalCobradoPorZona).catch(() => {});
  }, [esAdmin, usuario?.zonaId]);

  // Cargar abonos de hoy solo al montar — el ref se encarga de actualizaciones en tiempo real
  useEffect(() => {
    db.getAbonosByFecha(hoyStr).then(setAbonosHoy).catch(() => {});
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Solo al montar — hoyStr no cambia dentro de una sesión del día

  const facturasFiltradas = (() => {
    const q = busq.trim();
    // Filtro de zona — doble capa de seguridad:
    // 1. Si el usuario es secretario (no admin), SIEMPRE se restringe a su propia zona, sin excepción.
    // 2. Si es admin, se respeta el filtro visual que haya elegido (o "todas" para ver todo).
    const zonaObligatoria = !esAdmin ? usuario?.zonaId : (filtroZona !== "todas" ? filtroZona : null);
    const matchZona = (f) => {
      if (!zonaObligatoria) return true;
      // Buscar el cliente de la factura para ver su zona (fuente más confiable)
      const cliente = usuarios.find(u => u.id === f.clienteId);
      return cliente ? cliente.zonaId === zonaObligatoria : f.zonaId === zonaObligatoria;
    };
    if (q.length >= 2) {
      const matchEstado = (f) => filtroEstado === "todos" || f.estado === filtroEstado;
      return resultadosBusqueda.filter(f => matchEstado(f) && matchZona(f));
    }
    // Si filtra por Anulada: usar facturasAnuladas que contiene todas las anuladas históricas
    if (filtroEstado === "Anulada") {
      const todasAnuladas = [...facturas.filter(f => f.estado === "Anulada"), ...facturasAnuladas]
        .filter((f, i, arr) => arr.findIndex(x => x.id === f.id) === i);
      return todasAnuladas.filter(f => matchZona(f));
    }
    // Sin busqueda: solo el mes/año seleccionado
    return facturas.filter(f => {
      const matchEstado = filtroEstado === "todos" || f.estado === filtroEstado;
      return matchEstado && matchZona(f) && f.mes === filtroMes && f.anio === filtroAnio;
    });
  })();

  // Clave estable con los IDs de las facturas visibles, para evitar recargas innecesarias
  const idsFacturasVisibles = facturasFiltradas.map(f => f.id).sort().join(",");

  // Cargar observaciones (de cualquier fecha) de las facturas que se están mostrando.
  // Permite ver la novedad de un pago aunque haya sido hace semanas o meses (útil ante una queja/reclamo).
  useEffect(() => {
    const ids = facturasFiltradas.map(f => f.id);
    if (!ids.length) { setObservacionesPorFactura({}); return; }
    db.getAbonosConObservacionPorFacturas(ids).then(abs => {
      const mapa = {};
      for (const a of abs) {
        // Como vienen ordenados por created_at desc, el primero que llega por factura es el más reciente
        if (!mapa[a.factura_id]) mapa[a.factura_id] = a.observacion;
      }
      setObservacionesPorFactura(mapa);
    }).catch(() => setObservacionesPorFactura({}));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idsFacturasVisibles]);

  // ── Totales ────────────────────────────────────────────────────
  const hoy = new Date();
  const mesActual = hoy.getMonth() + 1;
  const anioActual = hoy.getFullYear();

  // Facturas activas del mes (excluye Anuladas)
  const facturasActivasMes = facturasFiltradas.filter(f => f.estado !== "Anulada");

  // 📅 COBRADO HOY: suma de TODOS los abonos registrados hoy (pagos totales + parciales, no anuladas)
  // Usamos la tabla de abonos porque fechaPago solo existe en facturas totalmente pagadas
  // Zona obligatoria: secretario SIEMPRE se restringe a su propia zona; admin respeta el filtro visual (o ninguno si es "todas")
  const zonaObligatoriaHoy = !esAdmin ? usuario?.zonaId : (filtroZona !== "todas" ? filtroZona : null);
  // Helper: verificar si una factura/abono pertenece a la zona filtrada
  const facturaEnZona = (facturaId) => {
    if (!zonaObligatoriaHoy) return true;
    // Buscar en facturas del mes actual
    const factura = facturas.find(f => f.id === facturaId) || facturasHistoricas.find(f => f.id === facturaId);
    if (!factura) return true;
    const cliente = usuarios.find(u => u.id === factura.clienteId);
    return cliente ? cliente.zonaId === zonaObligatoriaHoy : true;
  };

  const cobradoHoyFacturas = abonosHoy
    .filter(a => {
      const factura = facturas.find(f => f.id === a.facturaId) || facturasHistoricas.find(f => f.id === a.facturaId);
      if (factura?.estado === "Anulada") return false;
      if (!zonaObligatoriaHoy) return true;
      // Filtrar por zona: usar clienteId del abono o de la factura encontrada
      const cid = a.clienteId || factura?.clienteId;
      if (!cid) {
        // Sin cliente_id: es un abono de factura manual o sin zona asignada
        // En vista por zona específica, NO incluir (evita que aparezca en Tuluá)
        return false;
      }
      const cliente = usuarios.find(u => u.id === cid);
      return cliente ? cliente.zonaId === zonaObligatoriaHoy : false;
    })
    .reduce((s, a) => s + a.monto, 0);
  const totalDia = cobradoHoyFacturas;

  // Helper: verificar si un cliente pertenece a la zona filtrada
  const clienteEnZona = (clienteId) => {
    if (!filtroZona || filtroZona === "todas") return true;
    const cliente = usuarios.find(u => u.id === clienteId);
    return cliente ? cliente.zonaId === filtroZona : true;
  };

  // Movimientos de caja de HOY — ya vienen filtrados por zona desde el servidor (ver db.getMovimientosCaja)
  const ingresosHoy = movimientosCaja
    .filter(m => m.tipo === "Ingreso" && m.fecha === hoyStr)
    .reduce((s, m) => s + m.monto, 0);
  const egresosHoy = movimientosCaja
    .filter(m => m.tipo === "Egreso" && m.fecha === hoyStr)
    .reduce((s, m) => s + m.monto, 0);

  // 🏦 TOTAL EN CAJA (del día): cobrado hoy en facturas + ingresos caja hoy - egresos caja hoy
  const esTodasZonas = !filtroZona || filtroZona === "todas";
  const totalCaja = cobradoHoyFacturas + ingresosHoy - egresosHoy;

  // 🌐 TOTAL GLOBAL (acumulado histórico)
  const totalEgresosCaja = movimientosCaja.filter(m => m.tipo === "Egreso").reduce((s, m) => s + m.monto, 0);
  const totalIngresosCaja = movimientosCaja.filter(m => m.tipo === "Ingreso").reduce((s, m) => s + m.monto, 0);
  // Saldo base se guarda localmente (igual que en la pestaña Caja) — es el dinero con que se inicia la caja.
  const saldoBaseGlobal = (() => { try { return Number(localStorage.getItem("caja_saldo_base") || 0); } catch { return 0; } })();
  const ingresosCajaGlobal = movimientosCaja.filter(m => m.tipo === "Ingreso").reduce((s,m) => s + m.monto, 0);
  const egresosCajaGlobal = movimientosCaja.filter(m => m.tipo === "Egreso").reduce((s,m) => s + m.monto, 0);
  const totalGlobal = (() => {
    // Total global = PLATA REAL DISPONIBLE para retirar: saldo base + todo lo cobrado históricamente
    // en facturas + ingresos de caja − egresos de caja. Si se registra un egreso, este número baja de inmediato.
    if (esTodasZonas) {
      const cobradoFacturas = totalCobradoGlobal !== null ? totalCobradoGlobal : (() => {
        const todas = [...facturas, ...facturasHistoricas].filter((f,i,arr) => arr.findIndex(x=>x.id===f.id)===i);
        return todas.filter(f => f.estado !== "Anulada").reduce((s,f) => s + Math.max(0, f.monto - f.saldoPendiente - (f.descuento_pronto_pago||0)), 0);
      })();
      return saldoBaseGlobal + cobradoFacturas + ingresosCajaGlobal - egresosCajaGlobal;
    }
    // Vista por zona: total abonos de esa zona (no se mezcla con saldo base/ingresos/egresos, que son globales de la oficina)
    if (Object.keys(totalCobradoPorZona).length > 0) {
      return totalCobradoPorZona[filtroZona] || 0;
    }
    // Fallback mientras carga
    const facturasZona = [...facturas, ...facturasHistoricas]
      .filter((f,i,arr) => arr.findIndex(x=>x.id===f.id)===i)
      .filter(f => clienteEnZona(f.clienteId));
    return facturasZona
      .filter(f => f.estado !== "Anulada")
      .reduce((s,f) => s + Math.max(0, f.monto - f.saldoPendiente - (f.descuento_pronto_pago||0)), 0);
  })();

  // ⏳ PENDIENTES: facturas del mes filtradas por zona
  const totalPendiente = facturasActivasMes
    .filter(f => f.estado !== "Pagado")
    .reduce((s, f) => s + f.saldoPendiente, 0);

  // 🔴 MOROSOS: clientes con 2+ meses pendientes — filtrado por zona
  const _todasPendMorosos = [...facturas, ...facturasHistoricas]
    .filter((f,i,arr) => arr.findIndex(x=>x.id===f.id)===i)
    .filter(f =>
      f.estado !== "Anulada" && f.estado !== "Pagado" && f.saldoPendiente > 0 &&
      (f.anio < anioActual || (f.anio === anioActual && f.mes <= mesActual)) &&
      clienteEnZona(f.clienteId)
    );
  const _mesesPorCliente = {};
  _todasPendMorosos.forEach(f => {
    if (!_mesesPorCliente[f.clienteId]) _mesesPorCliente[f.clienteId] = new Set();
    _mesesPorCliente[f.clienteId].add(`${f.anio}-${f.mes}`);
  });
  const morosos = Object.values(_mesesPorCliente).filter(s => s.size >= 2).length;

  const WHATSAPP_EDGE_URL = "https://fwimnbieduydfsjwljjv.supabase.co/functions/v1/whatsapp-facturas";

  const enviarWhatsAppFacturas = async (clientesConFactura) => {
    const conTelefono = clientesConFactura.filter(c => c.telefono?.trim());
    if (!conTelefono.length) { alert("⚠️ Ningún cliente tiene número de teléfono registrado."); return; }

    const payload = conTelefono.map(c => {
      const perfil = perfilesPago.find(p => p.id === c.perfilPagoId);
      const diasPago = perfil ? `entre el día ${perfil.diaInicio} y ${perfil.diaFin} de cada mes` : "según tu perfil de pago";
      return { id: c.id, nombre: c.nombre, telefono: c.telefono, monto: c.monto, mes: filtroMes, anio: filtroAnio, diasPago };
    });

    try {
      const res = await fetch(WHATSAPP_EDGE_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": "Bearer " + SUPABASE_ANON },
        body: JSON.stringify({ clientes: payload }),
      });
      const data = await res.json();
      if (data.ok) {
        alert(`📱 WhatsApp enviado:\n✅ ${data.enviados} mensajes enviados\n❌ ${data.errores} errores (sin teléfono registrado)`);
      } else {
        alert(`⚠️ Error al enviar WhatsApp: ${data.error}`);
      }
    } catch (e) { alert("Error de conexión con WhatsApp: " + e.message); }
  };

  const generarFacturasMasivas = async (perfilFiltro = null) => {
    setGenerandoMasivo(true);
    let creadas = 0;
    const clientesCreados = [];
    try {
      // Base de clientes según zona seleccionada (admin puede filtrar por zona)
      const clientesBase = (esAdmin && zonas.length > 1 && filtroZona !== "todas")
        ? usuarios.filter(u => u.rol === "cliente" && u.activo && u.zonaId === filtroZona)
        : clientesVisibles;
      const clientesTarget = clientesBase.filter(c => {
        if (!c.monto) return false;
        // DPP, DPS y Cortesía NO generan factura
        if (ESTADOS_SIN_FACTURA.has(c.estado)) return false;
        // Respetar fechaPrimeraFactura si existe
        if (c.fechaPrimeraFactura) {
          const [anioInicio, mesInicio] = c.fechaPrimeraFactura.split("-").map(Number);
          if (filtroAnio < anioInicio || (filtroAnio === anioInicio && filtroMes < mesInicio)) return false;
        }
        // Verificar tanto en estado local como en las recién creadas en esta misma ejecución
        const yaExiste = facturas.some(f => f.clienteId === c.id && f.mes === filtroMes && f.anio === filtroAnio)
                      || clientesCreados.some(x => x.id === c.id);
        if (yaExiste) return false;
        if (perfilFiltro === null) return true;
        if (perfilFiltro === "sin_perfil") return !c.perfilPagoId;
        return c.perfilPagoId === perfilFiltro;
      });
      for (const c of clientesTarget) {
        const mesNombre = MESES[filtroMes - 1];
        let fechaVencimiento = null;
        if (c.perfilPagoId) {
          const perfil = perfilesPago.find(p => p.id === c.perfilPagoId);
          if (perfil) fechaVencimiento = `${filtroAnio}-${String(filtroMes).padStart(2,"0")}-${String(perfil.diaFin).padStart(2,"0")}`;
        }
        const servicios = (c.servicio || "Internet").split("+").map(s => s.trim()).filter(Boolean);
        const montoPorSrv = servicios.length > 1 ? Math.round(c.monto / servicios.length) : c.monto;
        const items = servicios.map(s => ({ concepto: `${s} ${mesNombre} ${filtroAnio}`, monto: montoPorSrv }));
        const sumaItems = items.reduce((s, i) => s + i.monto, 0);
        if (sumaItems !== c.monto && items.length > 0) items[items.length - 1].monto += (c.monto - sumaItems);
        const nueva = await db.crearFacturaAtomica({
          clienteId: c.id, clienteNombre: c.nombre, clienteCedula: c.cedula, clienteDireccion: c.direccion,
          zonaId: c.zonaId, mes: filtroMes, anio: filtroAnio,
          concepto: `${c.servicio || "Internet"} ${mesNombre} ${filtroAnio}`,
          items, monto: c.monto, fechaEmision: hoyStr,
          creadoPor: usuario.id,
          notas: fechaVencimiento ? `Vence: ${fechaVencimiento}` : "",
        });
        setFacturas(prev => [nueva, ...prev]);
        clientesCreados.push(c);
        creadas++;
      }
      if (creadas > 0) {
        setShowGenerarMasivo(false);
        // Preguntar si quiere enviar WhatsApp
        const conTelefono = clientesCreados.filter(c => c.telefono?.trim()).length;
        const sinTelefono = clientesCreados.length - conTelefono;
        const enviar = confirm(
          `✅ Se generaron ${creadas} facturas para ${MESES[filtroMes - 1]} ${filtroAnio}.\n\n` +
          `📱 ¿Deseas enviar recordatorio por WhatsApp?\n` +
          `• ${conTelefono} clientes con teléfono registrado\n` +
          (sinTelefono > 0 ? `• ${sinTelefono} clientes sin teléfono (se omitirán)\n` : "") +
          `\n⚠️ Requiere Twilio configurado (disponible desde mayo)`
        );
        if (enviar) await enviarWhatsAppFacturas(clientesCreados);
      } else {
        alert(`✅ Se generaron ${creadas} facturas para ${MESES[filtroMes - 1]} ${filtroAnio}.`);
      }
    } catch (e) { alert("Error: " + e.message); }
    finally { setGenerandoMasivo(false); }
  };

  const crearFacturaManual = async () => {
    if (guardandoManual) return; // evitar doble clic
    const cliente = usuarios.find(u => u.id === facturaManual.clienteId);
    if (!cliente) { alert("Selecciona un cliente."); return; }
    if (!facturaManual.items || facturaManual.items.length === 0) { alert("Agrega al menos un servicio."); return; }
    const montoTotal = facturaManual.items.reduce((s, i) => s + (Number(i.monto) || 0), 0);
    if (montoTotal <= 0) { alert("El monto debe ser mayor a 0."); return; }
    setGuardandoManual(true);
    try {
      const nueva = await db.crearFacturaAtomica({
        clienteId: cliente.id, clienteNombre: cliente.nombre, clienteCedula: cliente.cedula,
        clienteDireccion: cliente.direccion, zonaId: cliente.zonaId,
        mes: facturaManual.mes, anio: facturaManual.anio,
        concepto: facturaManual.items.map(i => i.concepto).join(" + "),
        items: facturaManual.items, monto: montoTotal,
        fechaEmision: hoyStr, creadoPor: usuario.id,
        notas: facturaManual.notas,
      });
      setFacturas(prev => [nueva, ...prev]);
      setShowFormManual(false);
      setFacturaManual({ clienteId: "", mes: new Date().getMonth() + 1, anio: new Date().getFullYear(), notas: "", items: [] });
    } catch (e) { alert("Error: " + e.message); }
    setGuardandoManual(false);
  };

  const exportarCSV = async (porMes) => {
    setExportando(true);
    try {
      const lista = porMes
        ? facturas.filter(f => f.mes === filtroMes && f.anio === filtroAnio)
        : facturas.filter(f => f.anio === filtroAnio);
      const zonaMap = Object.fromEntries(zonas.map(z => [z.id, z.nombre]));

      const headers = ["Recibo","Fecha","Cliente","Cédula","Período","Total ($)","Saldo ($)","Estado","Zona"];
      const rows = lista.map(f => [
        f.numeroRecibo || "",
        f.fechaEmision || "",
        f.clienteNombre || "",
        f.clienteCedula || "",
        `${MESES[(f.mes||1)-1]} ${f.anio}`,
        Number(f.monto) || 0,
        Number(f.saldoPendiente) || 0,
        f.estado || "",
        zonaMap[f.zonaId] || "",
      ]);

      // Generar XML para .xlsx sin dependencias externas
      const esc = v => String(v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
      const cellRef = (r, c) => String.fromCharCode(65 + c) + (r + 1);
      const toXmlCell = (val, r, c) => {
        const ref = cellRef(r, c);
        if (typeof val === "number") return `<c r="${ref}" t="n"><v>${val}</v></c>`;
        return `<c r="${ref}" t="inlineStr"><is><t>${esc(val)}</t></is></c>`;
      };

      const allRows = [headers, ...rows];
      const sheetData = allRows.map((row, r) =>
        `<row r="${r+1}">${row.map((v, c) => toXmlCell(v, r, c)).join("")}</row>`
      ).join("");

      const colWidths = [10,12,28,14,14,12,12,14,18].map(w => `<col min="${0}" max="${0}" width="${w}" customWidth="1"/>`).join("");

      const sheetXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<sheetData>${sheetData}</sheetData>
</worksheet>`;

      const wbXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"
  xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheets><sheet name="Facturas" sheetId="1" r:id="rId1"/></sheets>
</workbook>`;

      const relsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
</Relationships>`;

      const contentTypesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
</Types>`;

      const pkgRelsXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>`;

      // Ensamblar ZIP usando la API nativa (CompressionStream)
      const enc = new TextEncoder();
      const files = {
        "[Content_Types].xml": enc.encode(contentTypesXml),
        "_rels/.rels": enc.encode(pkgRelsXml),
        "xl/workbook.xml": enc.encode(wbXml),
        "xl/_rels/workbook.xml.rels": enc.encode(relsXml),
        "xl/worksheets/sheet1.xml": enc.encode(sheetXml),
      };

      // ZIP manual (store, sin compresión) — funciona en todos los navegadores modernos
      const u32 = n => { const b = new Uint8Array(4); new DataView(b.buffer).setUint32(0, n, true); return b; };
      const u16 = n => { const b = new Uint8Array(2); new DataView(b.buffer).setUint16(0, n, true); return b; };
      const crc32 = data => {
        let c = 0xFFFFFFFF;
        const t = new Uint32Array(256).map((_, i) => { let v = i; for (let j=0;j<8;j++) v = v&1 ? 0xEDB88320^(v>>>1) : v>>>1; return v; });
        for (const b of data) c = t[(c^b)&0xFF] ^ (c>>>8);
        return (c^0xFFFFFFFF)>>>0;
      };
      const parts = []; const centralDir = []; let offset = 0;
      const now = new Date(); const dosDate = ((now.getFullYear()-1980)<<9|(now.getMonth()+1)<<5|now.getDate())>>>0;
      const dosTime = (now.getHours()<<11|now.getMinutes()<<5|(now.getSeconds()>>1))>>>0;
      for (const [name, data] of Object.entries(files)) {
        const nameBytes = enc.encode(name); const crc = crc32(data);
        const local = new Uint8Array([0x50,0x4B,0x03,0x04,20,0,...u16(0),...u16(0),...u16(dosTime),...u16(dosDate),...u32(crc),...u32(data.length),...u32(data.length),...u16(nameBytes.length),...u16(0),...nameBytes,...data]);
        const central = new Uint8Array([0x50,0x4B,0x01,0x02,20,0,20,0,...u16(0),...u16(0),...u16(dosTime),...u16(dosDate),...u32(crc),...u32(data.length),...u32(data.length),...u16(nameBytes.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...nameBytes]);
        parts.push(local); centralDir.push(central); offset += local.length;
      }
      const cdSize = centralDir.reduce((s,c)=>s+c.length,0);
      const eocd = new Uint8Array([0x50,0x4B,0x05,0x06,...u16(0),...u16(0),...u16(centralDir.length),...u16(centralDir.length),...u32(cdSize),...u32(offset),...u16(0)]);
      const zip = new Uint8Array([...parts.flatMap(p=>[...p]),...centralDir.flatMap(c=>[...c]),...eocd]);

      const blob = new Blob([zip], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = porMes ? `facturas_${MESES[filtroMes-1]}_${filtroAnio}.xlsx` : `facturas_${filtroAnio}.xlsx`;
      a.click();
      URL.revokeObjectURL(a.href);
    } catch(e) { alert("Error al exportar: " + e.message); }
    setExportando(false);
  };

  // Tarjetas resumen clicables con tirilla
  const tarjetas = [
    // 📅 COBRADO HOY — se reinicia cada día automáticamente
    { label: "📅 Cobrado hoy", val: formatCOP(totalDia), color: GC.purple,
      tooltip: "Suma de todos los abonos registrados hoy (pagos totales y parciales). Se reinicia automáticamente cada día.",
      getTirilla: () => {
        const filasAbonos = abonosHoy
          .filter(a => { const f = facturas.find(x => x.id === a.facturaId); return !f || f.estado !== "Anulada"; })
          .map(a => {
            const f = facturas.find(x => x.id === a.facturaId);
            return { nombre: f?.clienteNombre || a.clienteNombre || "—", detalle: `${a.metodoPago} · ${f?.concepto || a.concepto || ""}`, estado: "Cobrado", monto: a.monto };
          });
        return { titulo: `📅 Cobrado hoy — ${hoyStr}`, subtitulo: "Abonos registrados hoy (totales y parciales)",
          total: totalDia, labelTotal: "Total cobrado hoy", colorTotal: GC.purple,
          filas: filasAbonos };
      }},

    // 🏦 TOTAL EN CAJA del día — cobrado hoy en facturas + ingresos caja hoy - egresos caja hoy
    { label: "🏦 Total en caja", val: formatCOP(totalCaja), color: GC.brand,
      tooltip: "Abonos de hoy (totales + parciales) + ingresos de caja hoy − egresos de caja hoy. Se reinicia cada día.",
      getTirilla: () => {
        const movHoy = movimientosCaja.filter(m => m.fecha === hoyStr);
        const filasAbonos = abonosHoy
          .filter(a => { const f = facturas.find(x => x.id === a.facturaId); return !f || f.estado !== "Anulada"; })
          .map(a => {
            const f = facturas.find(x => x.id === a.facturaId);
            return { nombre: f?.clienteNombre || a.clienteNombre || "—", detalle: `Cobro factura · ${a.metodoPago}`, estado: "Cobrado", monto: a.monto };
          });
        const filasIngresos = movHoy.filter(m => m.tipo === "Ingreso").map(m => ({ nombre: m.concepto, detalle: "Ingreso caja", estado: "Ingreso", monto: m.monto }));
        const filasEgresos = movHoy.filter(m => m.tipo === "Egreso").map(m => ({ nombre: m.concepto, detalle: "Egreso caja", estado: "Egreso", monto: -m.monto }));
        return { titulo: `🏦 Total en caja — ${hoyStr}`, subtitulo: "Cobros hoy + ingresos caja − egresos caja (del día)",
          total: totalCaja, labelTotal: "Total caja hoy", colorTotal: GC.brand,
          filas: [...filasAbonos, ...filasIngresos, ...filasEgresos] };
      }},

    // 🌐 TOTAL GLOBAL — acumulado histórico, nunca vuelve a cero
    { label: "🌐 Total global", val: formatCOP(totalGlobal), color: "#0891b2",
      tooltip: "Plata real disponible para retirar: saldo base + todo lo cobrado históricamente en facturas + ingresos de caja − egresos de caja. Si se registra un egreso, baja de inmediato.",
      getTirilla: () => {
        const fPagadas = facturas.filter(f => f.estado !== "Anulada" && (f.monto - f.saldoPendiente - (f.descuento_pronto_pago || 0)) > 0);
        return { titulo: "🌐 Total global — Plata disponible", subtitulo: "Saldo base + cobrado en facturas + ingresos caja − egresos caja",
          total: totalGlobal, labelTotal: "Disponible para retirar", colorTotal: "#0891b2",
          filas: fPagadas.map(f => ({ nombre: f.clienteNombre, detalle: `${MESES[(f.mes||1)-1]} ${f.anio}`, estado: f.estado, monto: (f.monto - f.saldoPendiente - (f.descuento_pronto_pago || 0)) })) };
      }},

    // ⏳ PENDIENTE del mes
    { label: "⏳ Pendiente", val: formatCOP(totalPendiente), color: GC.warning,
      tooltip: "Facturas del mes seleccionado que aún no han sido pagadas (excluye anuladas).",
      getTirilla: () => ({
        titulo: `⏳ Pendiente — ${MESES[filtroMes-1]} ${filtroAnio}`, subtitulo: "Facturas del mes sin pagar (excluye anuladas)",
        total: totalPendiente, labelTotal: "Total pendiente", colorTotal: GC.warning,
        filas: facturasActivasMes.filter(f => f.estado !== "Pagado")
          .map(f => ({ nombre: f.clienteNombre, detalle: f.concepto, estado: f.estado, monto: f.saldoPendiente }))
      })},

    // 🔴 MOROSOS — deben 2 o más meses
    { label: "🔴 Morosos", val: morosos + " clientes", color: GC.danger,
      tooltip: "Clientes que deben 2 o más meses (incluye mes actual). Clic para ver detalle o exportar Excel.",
      getTirilla: () => {
        const todas = [...facturasHistoricas, ...facturas].filter((f,i,arr) => arr.findIndex(x=>x.id===f.id)===i);
        const pendientes = todas.filter(f =>
          f.estado !== "Anulada" && f.estado !== "Pagado" && f.saldoPendiente > 0 &&
          (f.anio < anioActual || (f.anio === anioActual && f.mes <= mesActual)) &&
          clienteEnZona(f.clienteId)
        );
        const mesesPorCliente = {};
        pendientes.forEach(f => {
          if (!mesesPorCliente[f.clienteId]) mesesPorCliente[f.clienteId] = new Set();
          mesesPorCliente[f.clienteId].add(`${f.anio}-${f.mes}`);
        });
        const morososFact = pendientes
          .filter(f => mesesPorCliente[f.clienteId]?.size >= 2)
          .sort((a,b) => (a.anio*12+a.mes) - (b.anio*12+b.mes));
        return {
          titulo: "🔴 Morosos — 2+ meses sin pagar", subtitulo: "Clientes que deben 2 o más meses (incluye mes actual)",
          total: morososFact.reduce((s,f)=>s+f.saldoPendiente,0), labelTotal: "Deuda morosa", colorTotal: GC.danger,
          filas: morososFact.map(f=>({ nombre: f.clienteNombre, detalle: `${MESES[(f.mes||1)-1]} ${f.anio} · #${f.numeroRecibo||"—"}`, estado: f.estado, monto: f.saldoPendiente })),
          esMorosos: true,
        };
      }},
  ];

  return (
    <div>
      {/* Controles top */}
      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        <Sel value={filtroMes} onChange={e => setFiltroMes(Number(e.target.value))} style={{ width: "auto", minWidth: 120 }}>
          {MESES.map((m, i) => <option key={i} value={i+1}>{m}</option>)}
        </Sel>
        <Sel value={filtroAnio} onChange={e => setFiltroAnio(Number(e.target.value))} style={{ width: "auto", minWidth: 80 }}>
          {[2024,2025,2026,2027].map(a => <option key={a} value={a}>{a}</option>)}
        </Sel>
        {esAdmin && zonas.length > 1 && (
          <Sel value={filtroZona} onChange={e => setFiltroZona(e.target.value)} style={{ width: "auto", minWidth: 120 }}>
            <option value="todas">🌐 Todas</option>
            {zonas.map(z => <option key={z.id} value={z.id}>📍 {z.nombre}</option>)}
          </Sel>
        )}
        <div style={{ flex: 1 }} />
        {esAdmin && <>
          <button onClick={() => setModalExport("mes")} style={{ padding: "7px 11px", borderRadius: 8, border: "1px solid #22c55e", background: GC.brandLight, color: GC.brand, cursor: "pointer", fontSize: 12, fontWeight: 700 }}>📊 Excel mes</button>
          <button onClick={() => setModalExport("anio")} style={{ padding: "7px 11px", borderRadius: 8, border: "1px solid #0ea5e9", background: "#eff6ff", color: GC.info, cursor: "pointer", fontSize: 12, fontWeight: 700 }}>📊 Excel año</button>
        </>}
        <button onClick={() => setShowFormManual(true)} style={{ padding: "7px 12px", borderRadius: 8, border: "1px solid #8b5cf6", background: "#f5f3ff", color: "#7c3aed", cursor: "pointer", fontSize: 13, fontWeight: 700 }}>+ Manual</button>
        <Btn onClick={() => setShowGenerarMasivo(true)} style={{ fontSize: 13 }}>⚡ Generar</Btn>
      </div>

      {/* Tarjetas */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(130px,1fr))", gap: 8, marginBottom: 16 }}>
        {tarjetas.map(({ label, val, color, tooltip, getTirilla }) => (
          <div key={label} onClick={() => setTirilla(getTirilla())}
            title={tooltip || ""}
            style={{ background: "#fff", border: "1px solid " + color + "33", borderTop: "3px solid " + color, borderRadius: 10, padding: "12px 14px", cursor: "pointer", position: "relative" }}
            onMouseEnter={e => e.currentTarget.style.boxShadow = "0 4px 16px " + color + "33"}
            onMouseLeave={e => e.currentTarget.style.boxShadow = "none"}>
            <div style={{ fontSize: 10, color: GC.ink3, marginBottom: 3 }}>{label}</div>
            <div style={{ fontWeight: 800, color, fontSize: 14 }}>{val}</div>
            {label === "🌐 Total global" && (
              <div style={{ fontSize: 8, color: color, marginTop: 2, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.5 }}>acumulado histórico</div>
            )}
            {label === "🏦 Total en caja" && (
              <div style={{ fontSize: 8, color: GC.ink4, marginTop: 2 }}>se reinicia cada día</div>
            )}
            <div style={{ fontSize: 9, color: GC.ink4, marginTop: 3 }}>{label === "🔴 Morosos" ? "Ver detalle · 📊 Excel" : "Ver detalle"}</div>
          </div>
        ))}
      </div>

      {/* Botón rápido exportar morosos */}
      {morosos > 0 && (
        <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 10 }}>
          <button onClick={() => {
            const n = exportarMorosos(facturasHistoricas, facturas, usuarios, zonas, new Date().getFullYear(), new Date().getMonth() + 1);
            if (n) alert(`✅ Excel generado con ${n} clientes morosos.`);
          }} style={{ background: "#fef2f2", color: GC.danger, border: "1px solid #fecaca", borderRadius: 9, padding: "8px 16px", cursor: "pointer", fontWeight: 700, fontSize: 13, fontFamily: "inherit", display: "flex", alignItems: "center", gap: 6 }}>
            📊 Exportar {morosos} morosos a Excel
          </button>
        </div>
      )}

      {/* Filtros lista */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <Inp placeholder="🔍 Cliente, cédula, N° recibo..." value={busq} onChange={e => setBusq(e.target.value)} style={{ flex: 1, minWidth: 200 }} />
        <Sel value={filtroEstado} onChange={e => setFiltroEstado(e.target.value)} style={{ width: "auto", minWidth: 130 }}>
          <option value="todos">Todos los estados</option>
          <option value="Pendiente">Pendiente</option>
          <option value="Abono parcial">Abono parcial</option>
          <option value="Pagado">Pagado</option>
          <option value="Vencido">Vencido</option>
          <option value="Anulada">Anulada</option>
        </Sel>
      </div>

      {/* Lista facturas */}
      {busq.trim().length >= 2 && (
        <div style={{ background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 9, padding: "8px 14px", marginBottom: 10, fontSize: 12, color: "#1e40af", display: "flex", alignItems: "center", gap: 8 }}>
          {buscandoDB ? "⏳ Buscando..." : <>🔍 Resultados para <strong>"{busq.trim()}"</strong> en <strong>todos los meses</strong></>}
          <button onClick={() => { setBusq(""); setResultadosBusqueda([]); }} style={{ marginLeft: "auto", background: "none", border: "none", color: GC.info, cursor: "pointer", fontSize: 12, fontWeight: 700, padding: 0 }}>✕ Limpiar</button>
        </div>
      )}
      {(cargando || buscandoDB) ? (
        <div style={{ textAlign: "center", color: GC.ink4, padding: 40 }}>{buscandoDB ? "🔍 Buscando en todas las facturas..." : "Cargando..."}</div>
      ) : facturasFiltradas.length === 0 ? (
        <div style={{ textAlign: "center", padding: 40 }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>🧾</div>
          <div style={{ color: GC.ink3 }}>{busq.trim() ? `Sin facturas para "${busq.trim()}"` : `Sin facturas para ${MESES[filtroMes-1]} ${filtroAnio}`}</div>
          <div style={{ color: GC.ink4, fontSize: 13, marginTop: 4 }}>{busq.trim() ? "Verifica el nombre o cédula del cliente" : 'Usa "⚡ Generar" para crear las facturas del mes'}</div>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {facturasFiltradas.map(f => {
            // Observación del pago más reciente de esta factura (de cualquier fecha, no solo hoy)
            const observacionFactura = observacionesPorFactura[f.id] || "";
            return (
            <div key={f.id} style={{ background: f.estado === "Anulada" ? "#f8fafc" : "#fff", border: "1px solid " + GC.border, borderLeft: "4px solid " + (COLOR_ESTADO[f.estado] || "#e2e8f0"), borderRadius: 12, padding: "12px 16px", opacity: f.estado === "Anulada" ? 0.6 : 1 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                <div style={{ flex: 1, minWidth: 160 }}>
                  <div style={{ fontWeight: 700, color: GC.ink, fontSize: 14 }}>
                    {f.clienteNombre}
                    {f.numeroRecibo && <span style={{ fontSize: 11, color: GC.ink4, marginLeft: 8 }}>#{f.numeroRecibo}</span>}
                  </div>
                  <div style={{ fontSize: 12, color: GC.ink3 }}>{f.concepto}</div>
                  {busq.trim() && <div style={{ fontSize: 11, color: GC.purple, fontWeight: 700, marginTop: 2 }}>📅 {MESES[(f.mes||1)-1]} {f.anio}</div>}
                  {f.clienteDireccion && <div style={{ fontSize: 11, color: GC.ink4 }}>📍 {f.clienteDireccion}</div>}
                </div>
                {observacionFactura && (
                  <div style={{ flex: 1, minWidth: 140, maxWidth: 240 }}>
                    <div style={{ background: "#fff7ed", border: "1px solid #fed7aa", borderRadius: 8, padding: "4px 8px", fontSize: 11, color: "#9a3412" }}>
                      📝 {observacionFactura}
                    </div>
                  </div>
                )}
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontWeight: 800, color: GC.ink, fontSize: 15 }}>{formatCOP(f.monto)}</div>
                  {f.saldoPendiente > 0 && f.saldoPendiente < f.monto && <div style={{ fontSize: 12, color: GC.warning }}>Saldo: {formatCOP(f.saldoPendiente)}</div>}
                </div>
                <span style={{ background: (COLOR_ESTADO[f.estado]||"#94a3b8") + "22", color: COLOR_ESTADO[f.estado]||"#64748b", border: "1px solid " + (COLOR_ESTADO[f.estado]||"#94a3b8") + "55", borderRadius: 20, padding: "2px 10px", fontSize: 11, fontWeight: 700 }}>{f.estado}</span>
                <AccionesFact f={f} />
              </div>
            </div>
            );
          })}
        </div>
      )}

      {/* Modal tirilla */}
      {tirilla && (
        <div onClick={e => e.target === e.currentTarget && setTirilla(null)}
          style={{ position: "fixed", inset: 0, background: "#00000066", zIndex: 9500, display: "flex", alignItems: "center", justifyContent: "center", padding: "20px 16px" }}>
          <div style={{ background: "#fff", borderRadius: 20, width: "100%", maxWidth: 540, maxHeight: "80vh", display: "flex", flexDirection: "column", boxShadow: "0 20px 60px #00000044" }}>
            <div style={{ padding: "18px 20px 12px", borderBottom: "1px solid #f1f5f9", flexShrink: 0 }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 2 }}>
                <div style={{ fontWeight: 800, fontSize: 16, color: GC.ink }}>{tirilla.titulo}</div>
                <div style={{ display: "flex", gap: 6 }}>
                  {tirilla.esMorosos && (
                    <button onClick={() => {
                      const n = exportarMorosos(facturasHistoricas, facturas, usuarios, zonas, new Date().getFullYear(), new Date().getMonth() + 1);
                      if (n) alert(`✅ Excel generado con ${n} clientes morosos.`);
                    }} style={{ background: "#f0fdf4", color: "#16a34a", border: "1px solid #bbf7d0", borderRadius: 9, padding: "0 14px", height: 32, cursor: "pointer", fontWeight: 700, fontSize: 13, fontFamily: "inherit", display: "flex", alignItems: "center", gap: 6 }}>
                      📊 Excel morosos
                    </button>
                  )}
                  <button onClick={async () => {
                    const fecha = new Date().toLocaleDateString("es-CO", { day: "2-digit", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" });
                    const cop = v => v.toLocaleString("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 });
                    // La tirilla impresa muestra EXACTAMENTE lo mismo que el modal en pantalla
                    // tirilla.filas ya contiene todos los datos correctos (cobros + ingresos + egresos)
                    // tirilla.total es el total calculado igual que en pantalla
                    const filasTirilla = tirilla.filas.map(f => {
                      const esEgreso = f.monto < 0;
                      const colorBg = f.estado === "Cobrado" ? "#dcfce7" : f.estado === "Ingreso" ? "#dbeafe" : f.estado === "Egreso" ? "#fee2e2" : {"Pagado":"#dcfce7","Pendiente":"#fef9c3","Abono parcial":"#dbeafe","Vencido":"#fee2e2","Anulada":"#f1f5f9"}[f.estado]||"#f1f5f9";
                      const colorTxt = f.estado === "Cobrado" ? "#16a34a" : f.estado === "Ingreso" ? "#0369a1" : f.estado === "Egreso" ? "#b91c1c" : {"Pagado":"#16a34a","Pendiente":"#92400e","Abono parcial":"#0369a1","Vencido":"#b91c1c","Anulada":"#64748b"}[f.estado]||"#555";
                      return `<tr><td class="td-nombre">${f.nombre}</td><td class="td-concepto">${f.detalle}</td><td class="td-estado"><span style="background:${colorBg};color:${colorTxt}">${f.estado}</span></td><td class="td-monto">${esEgreso ? cop(f.monto) : cop(f.monto)}</td></tr>`;
                    }).join("");
                    // Total es exactamente el mismo valor que muestra el modal
                    const totalFinal = tirilla.total;
                    const filasCaja = []; // ya incluido en tirilla.filas
                    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Tirilla</title>
                    <style>
                      @page { size: 76mm auto; margin: 8mm 6mm; }
                      * { box-sizing: border-box; margin: 0; padding: 0; }
                      body { font-family: "Courier New", Courier, monospace; font-size: 9pt; color: #000; width: 64mm; background: #fff; padding: 4mm; line-height: 1.4; }
                      .center { text-align: center; } .bold { font-weight: bold; }
                      .empresa { font-size: 10.5pt; font-weight: 900; text-transform: uppercase; }
                      .sep { border: none; border-top: 1px dashed #555; margin: 6px 0; }
                      .sep-solid { border: none; border-top: 1px solid #000; margin: 5px 0; }
                      .info { font-size: 8pt; margin: 3px 0; }
                      table { width: 100%; border-collapse: collapse; margin: 4px 0; }
                      th { font-size: 7.5pt; text-transform: uppercase; border-bottom: 1px solid #000; padding: 3px; text-align: left; }
                      th.r { text-align: right; }
                      .td-nombre { font-size: 8pt; font-weight: bold; padding: 4px 3px 2px; width: 35%; word-break: break-word; }
                      .td-concepto { font-size: 7pt; color: #222; padding: 4px 3px 2px; width: 29%; word-break: break-word; }
                      .td-estado span { font-size: 6.5pt; padding: 1px 3px; border-radius: 2px; font-weight: bold; }
                      .td-estado { padding: 4px 3px 2px; width: 18%; }
                      .td-monto { text-align: right; font-weight: bold; font-size: 8pt; padding: 4px 0 2px 3px; width: 18%; }
                      tr { border-bottom: 1px dotted #aaa; }
                      .subtotal-row td { font-size: 8pt; padding: 5px 3px; border-top: 1px dashed #555; border-bottom: none; }
                      .total-row td { font-size: 10.5pt; font-weight: 900; padding: 6px 3px; border-top: 2px solid #000; }
                      .footer { font-size: 7.5pt; text-align: center; margin-top: 8px; color: #222; }
                      .btn-print { display: block; margin: 14px auto; padding: 9px 28px; background: #1d4ed8; color: #fff; border: none; border-radius: 6px; font-size: 13px; font-weight: 700; cursor: pointer; }
                      @media print { .no-print { display: none !important; } body { width: 64mm; padding: 0; } }
                    </style></head><body>
                    <div class="center"><div class="empresa">${nombreEmpresa}</div><div class="info">Tel: 318-8255601</div><div class="info">Fecha: ${fecha}</div></div>
                    <hr class="sep"/>
                    <div class="center bold" style="font-size:9pt;margin:3px 0">${tirilla.titulo}</div>
                    <div class="center" style="font-size:7.5pt;color:#444;margin-bottom:3px">${tirilla.subtitulo}</div>
                    <hr class="sep"/>
                    <table><thead><tr><th>Cliente / Concepto</th><th>Detalle</th><th>Estado</th><th class="r">Valor</th></tr></thead>
                    <tbody>${filasTirilla}</tbody>
                    <tr class="subtotal-row"><td colspan="3" class="bold">${tirilla.filas.length} registro${tirilla.filas.length !== 1 ? "s" : ""}</td><td style="text-align:right;font-weight:900">${cop(totalFinal)}</td></tr></table>
                    <hr class="sep-solid"/>
                    <table><tbody><tr class="total-row"><td colspan="3">${tirilla.labelTotal || "TOTAL"}</td><td style="text-align:right">${cop(totalFinal)}</td></tr></tbody></table>
                    <hr class="sep"/><div class="footer">Firma: ______________________</div>
                    <div class="footer" style="margin-top:8px">Gracias por su pago</div>
                    <br/><button class="btn-print no-print" onclick="window.print()">🖨️ Imprimir tirilla</button>
                    </body></html>`;
                    const w = window.open("", "_blank", "width=340,height=700");
                    w.document.write(html); w.document.close();
                  }} style={{ background: GC.brandLight, color: GC.brand, border: "none", borderRadius: 8, padding: "0 12px", height: 32, cursor: "pointer", fontSize: 13, fontWeight: 700 }}>🖨️ Imprimir</button>
                  <button onClick={() => setTirilla(null)} style={{ background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
                </div>
              </div>
              <div style={{ fontSize: 12, color: GC.ink3 }}>{tirilla.subtitulo}</div>
            </div>
            <div style={{ overflowY: "auto", flex: 1, padding: "12px 20px" }}>
              {tirilla.filas.length === 0 ? (
                <div style={{ textAlign: "center", color: GC.ink4, padding: 30, fontSize: 13 }}>Sin registros</div>
              ) : tirilla.filas.map((fila, i) => {
                const c = fila.estado === "Cobrado" ? GC.brand : fila.estado === "Ingreso" ? GC.info : fila.estado === "Egreso" ? GC.danger : (COLOR_ESTADO[fila.estado] || "#94a3b8");
                return (
                  <div key={i} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "9px 0", borderBottom: "1px solid #f8fafc", gap: 10 }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontWeight: 700, fontSize: 13, color: GC.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{fila.nombre}</div>
                      <div style={{ fontSize: 11, color: GC.ink3, marginTop: 1 }}>{fila.detalle}</div>
                      <span style={{ fontSize: 10, background: c + "22", color: c, borderRadius: 6, padding: "1px 6px", fontWeight: 700, display: "inline-block", marginTop: 2 }}>{fila.estado}</span>
                    </div>
                    <div style={{ fontWeight: 800, color: fila.monto < 0 ? GC.danger : tirilla.colorTotal, fontSize: 14, whiteSpace: "nowrap" }}>{fila.monto < 0 ? "-" + formatCOP(Math.abs(fila.monto)) : formatCOP(fila.monto)}</div>
                  </div>
                );
              })}
            </div>
            <div style={{ padding: "14px 20px", borderTop: "2px solid #f1f5f9", background: GC.bg2, borderRadius: "0 0 20px 20px", flexShrink: 0 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <div style={{ fontSize: 11, color: GC.ink3, fontWeight: 600 }}>{tirilla.labelTotal}</div>
                  <div style={{ fontSize: 10, color: GC.ink4 }}>{tirilla.filas.length} registro{tirilla.filas.length !== 1 ? "s" : ""}</div>
                </div>
                <div style={{ fontWeight: 900, fontSize: 22, color: tirilla.colorTotal }}>{formatCOP(tirilla.total)}</div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal generar masivo */}
      {showGenerarMasivo && (() => {
        const hoy = new Date(); const diaHoy = hoy.getDate();
        // Clientes filtrados por zona dentro del modal (si admin seleccionó zona)
        const clientesParaGenerar = esAdmin && zonas.length > 1
          ? (filtroZona === "todas"
              ? usuarios.filter(u => u.rol === "cliente" && u.activo)
              : usuarios.filter(u => u.rol === "cliente" && u.activo && u.zonaId === filtroZona))
          : clientesVisibles;
        const sinFactura = clientesParaGenerar.filter(c => {
          if (!c.monto) return false;
          // DPP, DPS y Cortesía no generan factura
          if (ESTADOS_SIN_FACTURA.has(c.estado)) return false;
          if (c.fechaPrimeraFactura) {
            const [anioI, mesI] = c.fechaPrimeraFactura.split("-").map(Number);
            if (filtroAnio < anioI || (filtroAnio === anioI && filtroMes < mesI)) return false;
          }
          return !facturas.some(f => f.clienteId === c.id && f.mes === filtroMes && f.anio === filtroAnio);
        });
        const conFactura = clientesParaGenerar.filter(c =>
          c.monto && !ESTADOS_SIN_FACTURA.has(c.estado) &&
          facturas.some(f => f.clienteId === c.id && f.mes === filtroMes && f.anio === filtroAnio)
        );
        const yaGenerado = conFactura.length > 0;
        const porPerfil = perfilesPago.map(pf => ({ perfil: pf, clientes: sinFactura.filter(c => c.perfilPagoId === pf.id), venceHoy: diaHoy >= pf.diaInicio && diaHoy <= pf.diaFin })).filter(g => g.clientes.length > 0);
        const sinPerfil = sinFactura.filter(c => !c.perfilPagoId);
        return (
          <div style={{ position: "fixed", inset: 0, background: "#00000055", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setShowGenerarMasivo(false)}>
            <div style={{ background: "#fff", borderRadius: 16, maxWidth: 500, width: "100%", maxHeight: "90vh", overflowY: "auto", position: "relative" }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "18px 24px", borderBottom: "1px solid #e2e8f0", position: "sticky", top: 0, background: "#fff", zIndex: 1 }}>
                <div style={{ flex: 1 }}>
                  <h3 style={{ margin: 0, fontSize: 16, fontWeight: 800, color: GC.ink }}>⚡ Generar facturas</h3>
                  <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>{MESES[filtroMes-1]} {filtroAnio} · {sinFactura.length} clientes pendientes</div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
                  {esAdmin && zonas.length > 1 && (
                    <Sel value={filtroZona} onChange={e => setFiltroZona(e.target.value)}
                      style={{ fontSize: 12, padding: "5px 8px", borderRadius: 8, border: "1px solid #e2e8f0", background: "#f8fafc", minWidth: 110 }}>
                      <option value="todas">🌐 Todas</option>
                      {zonas.map(z => <option key={z.id} value={z.id}>📍 {z.nombre}</option>)}
                    </Sel>
                  )}
                  <button onClick={() => setShowGenerarMasivo(false)} style={{ background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
                </div>
              </div>
              <div style={{ padding: "16px 24px 24px" }}>

                {/* ── Aviso si el mes ya fue generado parcial o totalmente ── */}
                {yaGenerado && sinFactura.length === 0 && (
                  <div style={{ background: "#fef9c3", border: "2px solid #fbbf24", borderRadius: 12, padding: "14px 16px", marginBottom: 16, display: "flex", gap: 12, alignItems: "flex-start" }}>
                    <span style={{ fontSize: 24 }}>⚠️</span>
                    <div>
                      <div style={{ fontWeight: 800, color: "#92400e", fontSize: 14 }}>Facturas ya generadas</div>
                      <div style={{ fontSize: 13, color: "#b45309", marginTop: 3 }}>
                        {MESES[filtroMes-1]} {filtroAnio} ya tiene <strong>{conFactura.length} clientes</strong> con factura generada. No hay nuevos clientes pendientes.
                      </div>
                      <div style={{ fontSize: 12, color: "#92400e", marginTop: 6, fontStyle: "italic" }}>Si necesitas agregar un cliente específico usa el botón <strong>+ Manual</strong>.</div>
                    </div>
                  </div>
                )}
                {yaGenerado && sinFactura.length > 0 && (
                  <div style={{ background: "#fff7ed", border: "2px solid #fed7aa", borderRadius: 12, padding: "12px 16px", marginBottom: 16, display: "flex", gap: 10, alignItems: "flex-start" }}>
                    <span style={{ fontSize: 20 }}>ℹ️</span>
                    <div style={{ fontSize: 13, color: "#9a3412" }}>
                      <strong>{conFactura.length} clientes</strong> ya tienen factura de {MESES[filtroMes-1]}. Solo se generarán los <strong>{sinFactura.length} restantes</strong>.
                    </div>
                  </div>
                )}

                <div style={{ background: sinFactura.length === 0 ? "#f8fafc" : "#eff6ff", border: "2px solid " + (sinFactura.length === 0 ? "#e2e8f0" : "#bfdbfe"), borderRadius: 12, padding: "14px 16px", marginBottom: 10 }}>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
                    <div>
                      <div style={{ fontWeight: 700, color: sinFactura.length === 0 ? GC.ink3 : "#1e40af", fontSize: 14 }}>🌐 Todos los clientes</div>
                      <div style={{ fontSize: 12, color: sinFactura.length === 0 ? GC.ink4 : "#3b82f6", marginTop: 2 }}>
                        {sinFactura.length === 0 ? "Todos ya tienen factura este mes" : `${sinFactura.length} sin factura en ${MESES[filtroMes-1]}`}
                      </div>
                    </div>
                    <Btn disabled={generandoMasivo || sinFactura.length === 0} onClick={() => generarFacturasMasivas(null)} style={{ fontSize: 13 }}>
                      {generandoMasivo ? "Generando..." : sinFactura.length === 0 ? "✓ Ya generado" : "⚡ Generar todos"}
                    </Btn>
                  </div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "14px 0 10px" }}>
                  <div style={{ flex: 1, height: 1, background: GC.bg3 }} />
                  <span style={{ fontSize: 11, color: GC.ink4, fontWeight: 700, textTransform: "uppercase" }}>O por perfil de pago</span>
                  <div style={{ flex: 1, height: 1, background: GC.bg3 }} />
                </div>
                {porPerfil.map(({ perfil: pf, clientes: lista, venceHoy }) => (
                  <div key={pf.id} style={{ background: venceHoy ? "#f0fdf4" : "#f8fafc", border: "1px solid " + (venceHoy ? "#86efac" : "#e2e8f0"), borderLeft: "4px solid " + (venceHoy ? "#22c55e" : "#0ea5e9"), borderRadius: 12, padding: "12px 16px", marginBottom: 8 }}>
                    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
                      <div style={{ flex: 1 }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                          <span style={{ fontWeight: 700, color: GC.ink, fontSize: 14 }}>📅 {pf.nombre}</span>
                          {venceHoy && <span style={{ background: GC.brand, color: "#fff", borderRadius: 20, padding: "2px 8px", fontSize: 10, fontWeight: 800 }}>🟢 VENCE ESTE MES</span>}
                        </div>
                        <div style={{ fontSize: 12, color: GC.ink3, marginTop: 3 }}>👥 {lista.length} cliente{lista.length !== 1 ? "s" : ""} sin factura</div>
                        <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginTop: 5 }}>
                          {lista.slice(0, 4).map(c => <span key={c.id} style={{ background: "#fff", border: "1px solid " + GC.border, borderRadius: 6, padding: "2px 8px", fontSize: 11, color: GC.ink2 }}>{c.nombre.split(" ")[0]}</span>)}
                          {lista.length > 4 && <span style={{ fontSize: 11, color: GC.ink4 }}>+{lista.length - 4} más</span>}
                        </div>
                      </div>
                      <Btn disabled={generandoMasivo} variant={venceHoy ? "success" : "primary"} onClick={() => generarFacturasMasivas(pf.id)} style={{ fontSize: 13 }}>
                        {generandoMasivo ? "..." : `⚡ Generar (${lista.length})`}
                      </Btn>
                    </div>
                  </div>
                ))}
                {sinPerfil.length > 0 && (
                  <div style={{ background: "#fffbeb", border: "1px solid #fde68a", borderLeft: "4px solid #f59e0b", borderRadius: 12, padding: "12px 16px" }}>
                    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontWeight: 700, color: "#92400e", fontSize: 14 }}>⚠️ Sin perfil asignado</div>
                        <div style={{ fontSize: 12, color: "#b45309", marginTop: 2 }}>{sinPerfil.length} cliente{sinPerfil.length !== 1 ? "s" : ""}</div>
                      </div>
                      <Btn disabled={generandoMasivo} onClick={() => generarFacturasMasivas("sin_perfil")} style={{ fontSize: 13, background: GC.warning }}>
                        {generandoMasivo ? "..." : `⚡ Generar (${sinPerfil.length})`}
                      </Btn>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })()}

      {/* Modal factura manual */}
      {showFormManual && (
        <div style={{ position: "fixed", inset: 0, background: "#00000055", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setShowFormManual(false)}>
          <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "100%", maxWidth: 480, maxHeight: "92vh", overflowY: "auto", position: "relative" }}>
            <button onClick={() => setShowFormManual(false)} style={{ position: "absolute", top: 14, right: 14, background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            <h3 style={{ margin: "0 0 16px", color: GC.ink }}>🧾 Nueva factura manual</h3>
            <Field label="Buscar cliente">
              <Inp placeholder="🔍 Nombre o cédula..." value={facturaManual.busqCliente || ""} onChange={e => setFacturaManual({ ...facturaManual, busqCliente: e.target.value, clienteId: "" })} />
              {facturaManual.busqCliente && facturaManual.busqCliente.length >= 2 && !facturaManual.clienteId && (() => {
                const q = facturaManual.busqCliente.toLowerCase();
                const res = clientesVisibles.filter(c => norm(c.nombre).includes(norm(q)) || norm(c.cedula).includes(norm(q))).slice(0,8);
                return res.length > 0 ? (
                  <div style={{ border: "1px solid " + GC.border, borderRadius: 8, marginTop: 4, overflow: "hidden" }}>
                    {res.map(c => (
                      <button key={c.id} onClick={() => {
                        const mn = MESES[facturaManual.mes - 1];
                        const srvs = (c.servicio || "Internet").split("+").map(s => s.trim()).filter(Boolean);
                        const mpp = srvs.length > 1 ? Math.round((c.monto||0) / srvs.length) : (c.monto||0);
                        const items = srvs.map(s => ({ concepto: `${s} ${mn} ${facturaManual.anio}`, monto: mpp }));
                        setFacturaManual({ ...facturaManual, clienteId: c.id, busqCliente: c.nombre, items });
                      }} style={{ width: "100%", display: "block", padding: "10px 14px", border: "none", borderBottom: "1px solid #f1f5f9", background: "#fff", cursor: "pointer", textAlign: "left", fontSize: 13 }}>
                        <strong>{c.nombre}</strong> <span style={{ color: GC.ink3 }}>· {c.cedula}</span>
                      </button>
                    ))}
                  </div>
                ) : <div style={{ fontSize: 12, color: GC.ink4, marginTop: 4 }}>Sin resultados</div>;
              })()}
              {facturaManual.clienteId && (
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 4 }}>
                  <div style={{ fontSize: 12, color: GC.brand }}>✅ Cliente seleccionado</div>
                  <button onClick={() => setFacturaManual({ ...facturaManual, clienteId: "", busqCliente: "" })}
                    style={{ fontSize: 11, color: GC.ink3, background: "none", border: "none", cursor: "pointer", textDecoration: "underline" }}>Cambiar</button>
                </div>
              )}
            </Field>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 12px" }}>
              <Field label="Mes"><Sel value={facturaManual.mes} onChange={e => setFacturaManual({ ...facturaManual, mes: Number(e.target.value) })}>{MESES.map((m, i) => <option key={i} value={i+1}>{m}</option>)}</Sel></Field>
              <Field label="Año"><Sel value={facturaManual.anio} onChange={e => setFacturaManual({ ...facturaManual, anio: Number(e.target.value) })}>{[2024,2025,2026,2027].map(a => <option key={a} value={a}>{a}</option>)}</Sel></Field>
            </div>
            <div style={{ marginBottom: 14 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <label style={{ fontSize: 11, color: GC.ink4, textTransform: "uppercase", letterSpacing: 0.8, fontWeight: 700 }}>Servicios</label>
                <button onClick={() => setFacturaManual({ ...facturaManual, items: [...facturaManual.items, { concepto: "", monto: 0 }] })}
                  style={{ background: "#eff6ff", color: GC.info, border: "1px solid #bfdbfe", borderRadius: 8, padding: "4px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>+ Línea</button>
              </div>
              {facturaManual.items.map((item, idx) => (
                <div key={idx} style={{ display: "flex", gap: 8, marginBottom: 8, alignItems: "flex-start" }}>
                  <Inp value={item.concepto} onChange={e => { const n = [...facturaManual.items]; n[idx] = { ...n[idx], concepto: e.target.value }; setFacturaManual({ ...facturaManual, items: n }); }} placeholder="Ej: Internet Abril 2026" style={{ flex: 2 }} />
                  <Inp type="number" value={item.monto||""} onChange={e => { const n = [...facturaManual.items]; n[idx] = { ...n[idx], monto: Number(e.target.value) }; setFacturaManual({ ...facturaManual, items: n }); }} placeholder="Valor" style={{ flex: 1 }} />
                  <button onClick={() => { const n = facturaManual.items.filter((_,i) => i !== idx); setFacturaManual({ ...facturaManual, items: n }); }} style={{ background: "#fee2e2", color: "#dc2626", border: "none", borderRadius: 8, padding: "9px 10px", cursor: "pointer" }}>✕</button>
                </div>
              ))}
              {facturaManual.items.length > 0 && (
                <div style={{ textAlign: "right", fontWeight: 800, color: GC.ink, fontSize: 15 }}>
                  Total: {formatCOP(facturaManual.items.reduce((s,i) => s + (Number(i.monto)||0), 0))}
                </div>
              )}
            </div>
            <Field label="Notas"><Inp value={facturaManual.notas||""} onChange={e => setFacturaManual({ ...facturaManual, notas: e.target.value })} /></Field>
            <div style={{ display: "flex", gap: 8 }}>
              <Btn onClick={crearFacturaManual} disabled={!facturaManual.clienteId || facturaManual.items.length === 0 || guardandoManual} style={{ flex: 1 }}>
                {guardandoManual ? "⏳ Creando..." : "Crear factura"}
              </Btn>
              <Btn variant="ghost" onClick={() => setShowFormManual(false)}>Cancelar</Btn>
            </div>
          </div>
        </div>
      )}

      {/* Modal exportar */}
      {modalExport && (
        <div style={{ position: "fixed", inset: 0, background: "#00000066", zIndex: 9000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setModalExport(null)}>
          <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 360, boxShadow: "0 20px 60px #00000033" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "16px 20px", borderBottom: "1px solid #e2e8f0" }}>
              <h3 style={{ margin: 0, fontSize: 16, fontWeight: 800 }}>{modalExport === "mes" ? "📊 Excel por mes" : "📊 Excel por año"}</h3>
              <button onClick={() => setModalExport(null)} style={{ background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            </div>
            <div style={{ padding: 20 }}>
              {modalExport === "mes" && (
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 16 }}>
                  <div><label style={{ fontSize: 11, color: GC.ink3, textTransform: "uppercase", letterSpacing: 0.8, fontWeight: 700, display: "block", marginBottom: 6 }}>Mes</label><Sel value={filtroMes} onChange={e => setFiltroMes(Number(e.target.value))}>{MESES.map((m, i) => <option key={i} value={i+1}>{m}</option>)}</Sel></div>
                  <div><label style={{ fontSize: 11, color: GC.ink3, textTransform: "uppercase", letterSpacing: 0.8, fontWeight: 700, display: "block", marginBottom: 6 }}>Año</label><Sel value={filtroAnio} onChange={e => setFiltroAnio(Number(e.target.value))}>{[2024,2025,2026,2027].map(a => <option key={a} value={a}>{a}</option>)}</Sel></div>
                </div>
              )}
              {modalExport === "anio" && (
                <div style={{ marginBottom: 16 }}><label style={{ fontSize: 11, color: GC.ink3, textTransform: "uppercase", letterSpacing: 0.8, fontWeight: 700, display: "block", marginBottom: 6 }}>Año</label><Sel value={filtroAnio} onChange={e => setFiltroAnio(Number(e.target.value))}>{[2024,2025,2026,2027].map(a => <option key={a} value={a}>{a}</option>)}</Sel></div>
              )}
              <div style={{ display: "flex", gap: 8 }}>
                <button onClick={async () => { await exportarCSV(modalExport === "mes"); setModalExport(null); }} style={{ flex: 1, padding: "10px 0", borderRadius: 9, border: "none", background: modalExport === "mes" ? "#22c55e" : "#0ea5e9", color: "#fff", fontWeight: 800, fontSize: 14, cursor: "pointer" }}>
                  {exportando ? "Exportando..." : "⬇️ Descargar Excel"}
                </button>
                <button onClick={() => setModalExport(null)} style={{ padding: "10px 16px", borderRadius: 9, border: "1px solid " + GC.border, background: GC.bg2, color: GC.ink3, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>Cancelar</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ── Sección 2: Cierre de Caja ─────────────────────────────────
function SeccionCierreCaja({ usuario, facturas, facturasHistoricas = [], usuarios, zonas, esAdmin, esSuperusuario, nombreEmpresa, COLOR_ESTADO }) {
  const hoy=fechaLocal(),primerDiaMes=fechaLocal().slice(0,8)+"01";
  const [fechaInicio,setFechaInicio]=useState(primerDiaMes);
  const [fechaFin,setFechaFin]=useState(hoy);
  const [secretarioFiltro,setSecretarioFiltro]=useState(esAdmin?"todos":usuario.id);
  const [movimientosCaja,setMovimientosCaja]=useState([]);
  const [abonosCierre,setAbonosCierre]=useState([]);
  const [facturasFaltantes,setFacturasFaltantes]=useState([]); // facturas de abonos que no están en facturas/facturasHistoricas
  const [cargandoCierre,setCargandoCierre]=useState(false);
  const secretarios=usuarios.filter(u=>(u.rol==="secretario"||u.rol==="admin")&&u.activo);
  // Combina facturas del mes actual + históricas de meses anteriores, para poder encontrar
  // cualquier factura sin importar a qué mes pertenezca (evita los "—" en la tabla de cobros)
  const todasLasFacturas=[...facturas,...facturasHistoricas,...facturasFaltantes].filter((f,i,arr)=>arr.findIndex(x=>x.id===f.id)===i);
  useEffect(()=>{db.getMovimientosCaja(esAdmin?null:usuario?.zonaId).then(setMovimientosCaja).catch(()=>{});}, [esAdmin, usuario?.zonaId]);
  useEffect(()=>{
    if(!fechaInicio||!fechaFin)return;
    setCargandoCierre(true);
    const cargar=async()=>{
      try{const dias=[];let cur=new Date(fechaInicio+"T12:00:00");const fin=new Date(fechaFin+"T12:00:00");
        while(cur<=fin){dias.push(cur.toISOString().split("T")[0]);cur.setDate(cur.getDate()+1);}
        const results=await Promise.all(dias.map(d=>db.getAbonosByFecha(d).catch(()=>[])));
        setAbonosCierre(results.flat());
      }catch{setAbonosCierre([]);}finally{setCargandoCierre(false);}
    };cargar();
  },[fechaInicio,fechaFin]);
  // Si algún abono del período pertenece a una factura que no está en facturas/facturasHistoricas
  // (típicamente facturas de meses anteriores que ya quedaron "Pagado"), las trae puntualmente por ID.
  useEffect(()=>{
    if(!abonosCierre.length)return;
    const idsConocidos=new Set([...facturas,...facturasHistoricas].map(f=>f.id));
    const idsFaltantes=[...new Set(abonosCierre.map(a=>a.facturaId).filter(id=>id&&!idsConocidos.has(id)))];
    if(!idsFaltantes.length){setFacturasFaltantes([]);return;}
    db.getFacturasPorIds(idsFaltantes).then(setFacturasFaltantes).catch(()=>setFacturasFaltantes([]));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[abonosCierre]);
  const facturasCierre=todasLasFacturas.filter(f=>{
    const fecha=f.fechaPago||f.fechaEmision||"";
    if(!fecha||fecha<fechaInicio||fecha>fechaFin)return false;
    if(secretarioFiltro!=="todos"){const secId=f.creadoPor||usuarios.find(u=>u.id===f.clienteId)?.secretarioId;if(secId!==secretarioFiltro)return false;}
    return f.estado!=="Anulada";
  });
  const totalFacturado=facturasCierre.reduce((s,f)=>s+f.monto,0);
  const totalCobrado=facturasCierre.reduce((s,f)=>s+(f.monto-f.saldoPendiente-(f.descuento_pronto_pago||0)),0);
  const totalPendiente=facturasCierre.reduce((s,f)=>s+f.saldoPendiente,0);
  const cantPagadas=facturasCierre.filter(f=>f.estado==="Pagado").length;
  const cantParcial=facturasCierre.filter(f=>f.estado==="Abono parcial").length;
  const cantPendiente=facturasCierre.filter(f=>f.estado==="Pendiente"||f.estado==="Vencido").length;
  // Lista de abonos (pagos completos y parciales) con los datos de su factura, para la tabla del cierre.
  const abonosConFactura=abonosCierre
    .map(a=>{
      const f=todasLasFacturas.find(x=>x.id===a.facturaId); // ahora incluye históricas, así no quedan "—" por facturas de meses anteriores
      if(secretarioFiltro!=="todos"){const secId=f?.creadoPor||usuarios.find(u=>u.id===f?.clienteId)?.secretarioId;if(secId!==secretarioFiltro)return null;}
      if(f&&f.estado==="Anulada")return null;
      return{
        id:a.id,
        facturaId:a.facturaId,
        numeroRecibo:a.numeroRecibo||f?.numeroRecibo,
        clienteNombre:a.clienteNombre||f?.clienteNombre||"(factura no encontrada)",
        concepto:a.concepto||f?.concepto||"",
        mes:f?.mes,anio:f?.anio,
        fecha:a.fecha,
        estadoFacturaActual:f?.estado||"—",
        metodoPago:a.metodoPago,
        monto:a.monto,
        observacion:a.observacion||"",
      };
    })
    .filter(Boolean)
    .sort((a,b)=>(b.fecha||"").localeCompare(a.fecha||""));
  // cobradoPeriodo SIEMPRE se calcula desde la misma lista que se muestra en la tabla — así nunca puede haber descuadre
  const cobradoPeriodo=abonosConFactura.reduce((s,a)=>s+a.monto,0);
  const ingresosPeriodo=movimientosCaja.filter(m=>m.tipo==="Ingreso"&&m.fecha>=fechaInicio&&m.fecha<=fechaFin).reduce((s,m)=>s+m.monto,0);
  const egresosPeriodo=movimientosCaja.filter(m=>m.tipo==="Egreso"&&m.fecha>=fechaInicio&&m.fecha<=fechaFin).reduce((s,m)=>s+m.monto,0);
  const egresosCierre=movimientosCaja.filter(m=>m.tipo==="Egreso"&&m.fecha>=fechaInicio&&m.fecha<=fechaFin).sort((a,b)=>(b.fecha||"").localeCompare(a.fecha||""));
  const totalCajaPeriodo=cobradoPeriodo+ingresosPeriodo-egresosPeriodo;
  const esUnDia=fechaInicio===fechaFin;
  const imprimir=()=>{
    const cop=v=>v.toLocaleString("es-CO",{style:"currency",currency:"COP",minimumFractionDigits:0});
    const nombreSec=secretarioFiltro==="todos"?"Todos":(usuarios.find(u=>u.id===secretarioFiltro)?.nombre||"—");
    const filas=abonosConFactura.map(a=>{
      const colorBg={"Pagado":"#dcfce7","Pendiente":"#fef9c3","Abono parcial":"#dbeafe","Vencido":"#fee2e2"}[a.estadoFacturaActual]||"#f1f5f9";
      const colorTxt={"Pagado":"#16a34a","Pendiente":"#92400e","Abono parcial":"#0369a1","Vencido":"#b91c1c"}[a.estadoFacturaActual]||"#555";
      const mp=getMetodoEmoji(a.metodoPago);
      return `<tr><td>#${a.numeroRecibo||"—"}</td><td>${a.clienteNombre}</td><td>${a.fecha||""}</td><td><span style="background:${colorBg};color:${colorTxt};padding:1px 5px;border-radius:3px;font-weight:bold">${a.estadoFacturaActual}</span></td><td>${a.metodoPago?mp+" "+a.metodoPago:"—"}</td><td>${a.observacion||"—"}</td><td style="text-align:right;color:#16a34a">${cop(a.monto)}</td></tr>`;
    }).join("");
    const filasEgresos=egresosCierre.map(m=>{
      const nombreReg=usuarios.find(u=>u.id===m.registradoPor)?.nombre||"—";
      return `<tr><td>${m.fecha}</td><td>${m.concepto}</td><td>${nombreReg}</td><td>${m.observacion||"—"}</td><td style="text-align:right;color:#dc2626">−${cop(m.monto)}</td></tr>`;
    }).join("");
    const tablaEgresos=egresosCierre.length?`<table style="margin-top:18px"><thead><tr><th>Fecha</th><th>Concepto</th><th>Registrado por</th><th>Observación</th><th style="text-align:right">Monto</th></tr></thead><tbody>${filasEgresos}</tbody><tr class="total-row"><td colspan="4">TOTAL EGRESOS</td><td style="text-align:right;color:#dc2626">−${cop(egresosPeriodo)}</td></tr></table>`:"";
    const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Cierre</title><style>@page{size:A4;margin:15mm}body{font-family:Arial,sans-serif;font-size:10pt}h1{font-size:16pt;margin:0 0 4px}h2{font-size:12pt;margin:0 0 12px;color:#555}.header{text-align:center;margin-bottom:16px;border-bottom:2px solid #000;padding-bottom:10px}.resumen{display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap}.card{border:1px solid #e2e8f0;border-radius:6px;padding:10px 14px;flex:1;min-width:120px}.card-label{font-size:8pt;color:#64748b;text-transform:uppercase}.card-val{font-size:13pt;font-weight:900;margin-top:2px}table{width:100%;border-collapse:collapse;font-size:9pt}th{background:#f1f5f9;padding:6px 8px;text-align:left;border-bottom:2px solid #e2e8f0}td{padding:5px 8px;border-bottom:1px solid #f1f5f9}.total-row{font-weight:900;font-size:11pt;border-top:2px solid #000}.footer{margin-top:20px;border-top:1px dashed #aaa;padding-top:12px;font-size:9pt}.btn-print{display:block;margin:16px auto;padding:10px 28px;background:#1d4ed8;color:#fff;border:none;border-radius:6px;font-size:14px;font-weight:700;cursor:pointer}@media print{.btn-print{display:none}}</style></head><body><div class="header"><h1>${nombreEmpresa}</h1><h2>CIERRE DE CAJA</h2><div>Período: <strong>${fechaInicio}${fechaInicio!==fechaFin?" → "+fechaFin:""}</strong></div><div>Secretario: <strong>${nombreSec}</strong> · ${new Date().toLocaleString("es-CO")}</div></div><div class="resumen"><div class="card"><div class="card-label">📅 Cobrado</div><div class="card-val" style="color:#7c3aed">${cop(cobradoPeriodo)}</div></div><div class="card"><div class="card-label">🏦 Caja</div><div class="card-val" style="color:#16a34a">${cop(totalCajaPeriodo)}</div></div><div class="card"><div class="card-label">📤 Egresos</div><div class="card-val" style="color:#dc2626">${cop(egresosPeriodo)}</div></div><div class="card"><div class="card-label">💰 Facturado</div><div class="card-val" style="color:#0ea5e9">${cop(totalFacturado)}</div></div><div class="card"><div class="card-label">✅ Cobrado</div><div class="card-val" style="color:#16a34a">${cop(totalCobrado)}</div></div><div class="card"><div class="card-label">⏳ Pendiente</div><div class="card-val" style="color:#ef4444">${cop(totalPendiente)}</div></div></div><table><thead><tr><th>#Recibo</th><th>Cliente</th><th>Fecha cobro</th><th>Estado factura</th><th>Método</th><th>Observación</th><th style="text-align:right">Monto cobrado</th></tr></thead><tbody>${filas}</tbody><tr class="total-row"><td colspan="6">TOTAL COBRADO</td><td style="text-align:right;color:#16a34a">${cop(cobradoPeriodo)}</td></tr></table>${tablaEgresos}<div class="footer"><div>Firma: _______________________________</div></div><button class="btn-print" onclick="window.print()">🖨️ Imprimir</button></body></html>`;
    const w=window.open("","_blank","width=900,height=700");w.document.write(html);w.document.close();
  };
  return(<div>
    <div style={{background:GC.bg3,border:"1px solid "+GC.border,borderRadius:12,padding:"14px 18px",marginBottom:18}}>
      <div style={{fontWeight:700,color:GC.ink,marginBottom:12,fontSize:14}}>⚙️ Configurar cierre</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit, minmax(150px,1fr))",gap:"0 14px"}}>
        <Field label="Fecha inicio"><Inp type="date" value={fechaInicio} onChange={e=>setFechaInicio(e.target.value)} /></Field>
        <Field label="Fecha fin"><Inp type="date" value={fechaFin} onChange={e=>setFechaFin(e.target.value)} /></Field>
        {esAdmin&&<Field label="Secretario"><Sel value={secretarioFiltro} onChange={e=>setSecretarioFiltro(e.target.value)}><option value="todos">Todos</option>{secretarios.map(s=><option key={s.id} value={s.id}>{s.nombre}</option>)}</Sel></Field>}
      </div>
    </div>
    <div style={{fontSize:11,fontWeight:700,color:GC.ink3,textTransform:"uppercase",letterSpacing:0.8,marginBottom:10}}>
      {esUnDia?`📅 ${new Date(fechaInicio+"T12:00:00").toLocaleDateString("es-CO",{weekday:"long",day:"numeric",month:"long",year:"numeric"})}`:`📋 Período: ${fechaInicio} → ${fechaFin}`}
    </div>
    {cargandoCierre?<div style={{fontSize:13,color:GC.ink3,padding:"10px 0",marginBottom:14}}>Cargando...</div>:(
      <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:16}}>
        <div style={{background:"#faf5ff",border:"2px solid #a78bfa",borderRadius:10,padding:"10px 14px",minWidth:140,flex:1}}>
          <div style={{fontSize:10,color:"#7c3aed",textTransform:"uppercase",letterSpacing:0.7,fontWeight:700}}>{esUnDia?"📅 Cobrado ese día":"📅 Cobrado período"}</div>
          <div style={{fontWeight:900,color:"#7c3aed",fontSize:18,marginTop:2}}>{formatCOP(cobradoPeriodo)}</div>
          <div style={{fontSize:10,color:GC.ink3,marginTop:1}}>{abonosConFactura.length} cobros · {cantPagadas} pagadas</div>
        </div>
        <div style={{background:GC.brandLight,border:"2px solid #22c55e",borderRadius:10,padding:"10px 14px",minWidth:140,flex:1}}>
          <div style={{fontSize:10,color:GC.brand,textTransform:"uppercase",letterSpacing:0.7,fontWeight:700}}>{esUnDia?"🏦 Total en caja ese día":"🏦 Total en caja"}</div>
          <div style={{fontWeight:900,color:GC.brand,fontSize:18,marginTop:2}}>{formatCOP(totalCajaPeriodo)}</div>
          <div style={{fontSize:10,color:GC.ink3,marginTop:1}}>{ingresosPeriodo>0?`+${formatCOP(ingresosPeriodo)} ing. · `:""}{ egresosPeriodo>0?`−${formatCOP(egresosPeriodo)} egr.`:"sin egresos"}</div>
        </div>
        <div style={{background:"#fef2f2",border:"1px solid #ef444433",borderRadius:10,padding:"10px 14px",minWidth:120,flex:1}}>
          <div style={{fontSize:10,color:GC.ink3,textTransform:"uppercase",letterSpacing:0.7}}>📤 Egresos</div>
          <div style={{fontWeight:800,color:"#dc2626",fontSize:16,marginTop:2}}>{formatCOP(egresosPeriodo)}</div>
          <div style={{fontSize:10,color:GC.ink3,marginTop:1}}>{movimientosCaja.filter(m=>m.tipo==="Egreso"&&m.fecha>=fechaInicio&&m.fecha<=fechaFin).length} movimientos</div>
        </div>
      </div>
    )}
    {abonosConFactura.length===0?(
      <div style={{textAlign:"center",color:GC.ink4,padding:40}}><div style={{fontSize:32,marginBottom:8}}>💼</div><div>Sin cobros en el período</div></div>
    ):(
      <>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10,flexWrap:"wrap",gap:8}}>
          <span style={{fontWeight:700,color:GC.ink,fontSize:13}}>{abonosConFactura.length} cobros en el período (incluye abonos parciales)</span>
          <Btn onClick={imprimir} style={{fontSize:13}}>🖨️ Imprimir cierre</Btn>
        </div>
        <div style={{overflowX:"auto"}}>
          <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
            <thead><tr style={{background:GC.bg2,borderBottom:"2px solid #e2e8f0"}}>
              {["#Recibo","Cliente","Fecha cobro","Mes factura","Estado factura","Método","Observación","Monto cobrado"].map(h=>(
                <th key={h} style={{padding:"8px 10px",textAlign:"left",color:GC.ink3,fontWeight:700,whiteSpace:"nowrap"}}>{h}</th>
              ))}
            </tr></thead>
            <tbody>
              {abonosConFactura.map(a=>{
                const mp=getMetodoEmoji(a.metodoPago);
                return(<tr key={a.id} style={{borderBottom:"1px solid #f1f5f9"}}>
                  <td style={{padding:"8px 10px",color:GC.info,fontWeight:700}}>#{a.numeroRecibo||a.facturaId?.slice(-6)}</td>
                  <td style={{padding:"8px 10px",fontWeight:600}}>{a.clienteNombre}</td>
                  <td style={{padding:"8px 10px",color:GC.ink2}}>{a.fecha}</td>
                  <td style={{padding:"8px 10px",color:GC.ink2}}>{a.mes?`${MESES[(a.mes||1)-1]} ${a.anio}`:"—"}</td>
                  <td style={{padding:"8px 10px"}}><span style={{background:(COLOR_ESTADO[a.estadoFacturaActual]||"#94a3b8")+"22",color:COLOR_ESTADO[a.estadoFacturaActual]||"#64748b",borderRadius:6,padding:"2px 7px",fontWeight:700,fontSize:11}}>{a.estadoFacturaActual}</span></td>
                  <td style={{padding:"8px 10px"}}>{a.metodoPago?<span style={{background:GC.infoBg,color:GC.info,borderRadius:6,padding:"2px 7px",fontSize:11,fontWeight:700}}>{mp} {a.metodoPago}</span>:<span style={{color:GC.ink4,fontSize:11}}>—</span>}</td>
                  <td style={{padding:"8px 10px",color:"#9a3412",fontSize:11,maxWidth:160}}>{a.observacion?`📝 ${a.observacion}`:<span style={{color:GC.ink4}}>—</span>}</td>
                  <td style={{padding:"8px 10px",fontWeight:800,color:GC.brand}}>{formatCOP(a.monto)}</td>
                </tr>);
              })}
              <tr style={{borderTop:"2px solid #0f172a",background:GC.bg2}}>
                <td colSpan={7} style={{padding:"10px",fontWeight:800,fontSize:13}}>TOTAL COBRADO</td>
                <td style={{padding:"10px",fontWeight:800,fontSize:13,color:GC.brand}}>{formatCOP(cobradoPeriodo)}</td>
              </tr>
            </tbody>
          </table>
        </div>

        {/* ── Egresos del período ── */}
        {egresosCierre.length > 0 && (
          <div style={{marginTop:24}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10,flexWrap:"wrap",gap:8}}>
              <span style={{fontWeight:700,color:GC.ink,fontSize:13}}>📤 {egresosCierre.length} egresos en el período</span>
            </div>
            <div style={{overflowX:"auto"}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}>
                <thead><tr style={{background:GC.bg2,borderBottom:"2px solid #e2e8f0"}}>
                  {["Fecha","Concepto","Registrado por","Observación","Monto"].map(h=>(
                    <th key={h} style={{padding:"8px 10px",textAlign:"left",color:GC.ink3,fontWeight:700,whiteSpace:"nowrap"}}>{h}</th>
                  ))}
                </tr></thead>
                <tbody>
                  {egresosCierre.map(m=>{
                    const nombreReg=usuarios.find(u=>u.id===m.registradoPor)?.nombre||"—";
                    return(<tr key={m.id} style={{borderBottom:"1px solid #f1f5f9"}}>
                      <td style={{padding:"8px 10px",color:GC.ink2}}>{m.fecha}</td>
                      <td style={{padding:"8px 10px",fontWeight:600}}>{m.concepto}</td>
                      <td style={{padding:"8px 10px",color:GC.ink2}}>{nombreReg}</td>
                      <td style={{padding:"8px 10px",color:GC.ink3,fontSize:11}}>{m.observacion||"—"}</td>
                      <td style={{padding:"8px 10px",fontWeight:800,color:"#dc2626"}}>−{formatCOP(m.monto)}</td>
                    </tr>);
                  })}
                  <tr style={{borderTop:"2px solid #0f172a",background:GC.bg2}}>
                    <td colSpan={4} style={{padding:"10px",fontWeight:800,fontSize:13}}>TOTAL EGRESOS</td>
                    <td style={{padding:"10px",fontWeight:800,fontSize:13,color:"#dc2626"}}>−{formatCOP(egresosPeriodo)}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        )}
      </>
    )}
  </div>);
}

// ── Sección 3: Historial y Auditoría ─────────────────────────
function PanelAbonoMasivo({ clienteBuscado, facturasCliente, deudaTotal, usuario, setFacturas, hoyStr, dbObj, agregarAbonoHoyRef }) {
  const [montoAbono, setMontoAbono] = useState("");
  const [metodoPago, setMetodoPago] = useState("Efectivo");
  const [procesando, setProcesando] = useState(false);
  const [simulacion, setSimulacion] = useState([]);
  const mesesNombres = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];

  useEffect(() => {
    const monto = Number(montoAbono) || 0;
    if (monto <= 0) { setSimulacion([]); return; }
    let restante = monto;
    const sim = [];
    for (const f of (facturasCliente || [])) {
      if (restante <= 0) break;
      const pagar = Math.min(restante, f.saldoPendiente);
      sim.push({ facturaId: f.id, concepto: f.concepto, mes: f.mes, anio: f.anio, saldoActual: f.saldoPendiente, pagar, nuevaSaldo: f.saldoPendiente - pagar });
      restante -= pagar;
    }
    setSimulacion(sim);
  }, [montoAbono]);

  const sobrante = Math.max(0, (Number(montoAbono) || 0) - deudaTotal);

  const aplicarAbono = async () => {
    const monto = Number(montoAbono);
    if (!monto || monto <= 0) { alert("Ingresa un monto válido."); return; }
    if (!simulacion.length) return;
    setProcesando(true);
    try {
      for (const s of simulacion) {
        if (s.pagar <= 0) continue;
        const nuevoEstado = s.nuevaSaldo <= 0 ? "Pagado" : "Abono parcial";
        const nuevaFecha  = s.nuevaSaldo <= 0 ? hoyStr : null;
        const abono = await dbObj.registrarAbono({ facturaId: s.facturaId, monto: s.pagar, metodoPago, observacion: "Abono masivo", fecha: hoyStr, registradoPor: usuario?.id || null });
        await dbObj.actualizarFactura(s.facturaId, { saldo_pendiente: s.nuevaSaldo, estado: nuevoEstado, metodo_pago: metodoPago, fecha_pago: nuevaFecha });
        setFacturas(prev => prev.map(f => f.id === s.facturaId ? { ...f, saldoPendiente: s.nuevaSaldo, estado: nuevoEstado, metodoPago, fechaPago: nuevaFecha } : f));
        // Sumar este abono al contador "Cobrado hoy" de Facturación y Caja
        if (abono && abono.fecha === hoyStr && agregarAbonoHoyRef?.current?.agregar) {
          agregarAbonoHoyRef.current.agregar(abono);
        }
      }
      const pagadas = simulacion.filter(s => s.nuevaSaldo <= 0).length;
      const parciales = simulacion.filter(s => s.nuevaSaldo > 0).length;
      alert("Abono aplicado.\n" + (pagadas ? pagadas + " factura(s) pagada(s)." : "") + (parciales ? "\n" + parciales + " factura(s) con abono parcial." : "") + (sobrante > 0 ? "\nSobrante: " + formatCOP(sobrante) : ""));
      setMontoAbono("");
      setSimulacion([]);
    } catch(e) { alert("Error: " + e.message); }
    setProcesando(false);
  };

  return (
    <div style={{ background: "#fff", border: "2px solid #22c55e", borderRadius: 14, padding: 20, marginBottom: 16 }}>
      <div style={{ fontWeight: 800, fontSize: 15, color: "#16a34a", marginBottom: 4 }}>💰 Abono masivo — {clienteBuscado.nombre}</div>
      <div style={{ fontSize: 12, color: GC.ink3, marginBottom: 16 }}>El abono se distribuye automáticamente desde la factura más antigua a la más reciente</div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px", marginBottom: 12 }}>
        <Field label="Monto a abonar ($)">
          <Inp type="number" value={montoAbono} onChange={e => setMontoAbono(e.target.value)} placeholder={`Deuda total: ${formatCOP(deudaTotal)}`} />
          <div style={{ display: "flex", gap: 6, marginTop: 6, flexWrap: "wrap" }}>
            <button onClick={() => setMontoAbono(String(deudaTotal))}
              style={{ background: "#f0fdf4", color: "#16a34a", border: "1px solid #bbf7d0", borderRadius: 6, padding: "4px 10px", cursor: "pointer", fontSize: 11, fontWeight: 700 }}>
              Todo ({formatCOP(deudaTotal)})
            </button>
            {[50000, 100000, 150000, 200000].filter(v => v < deudaTotal).map(v => (
              <button key={v} onClick={() => setMontoAbono(String(v))}
                style={{ background: "#eff6ff", color: "#1d4ed8", border: "1px solid #bfdbfe", borderRadius: 6, padding: "4px 10px", cursor: "pointer", fontSize: 11, fontWeight: 700 }}>
                {formatCOP(v)}
              </button>
            ))}
          </div>
        </Field>
        <Field label="Método de pago">
          <Sel value={metodoPago} onChange={e => setMetodoPago(e.target.value)}>
            {METODOS_PAGO.map(m => <option key={m.id} value={m.id}>{m.emoji} {m.label}</option>)}
          </Sel>
        </Field>
      </div>

      {/* Simulación de distribución */}
      {simulacion.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: GC.ink2, marginBottom: 8, textTransform: "uppercase", letterSpacing: 0.5 }}>Distribución del abono:</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            {simulacion.map((s, i) => (
              <div key={s.facturaId} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: s.nuevaSaldo <= 0 ? "#f0fdf4" : "#fffbeb", border: "1px solid " + (s.nuevaSaldo <= 0 ? "#bbf7d0" : "#fde047"), borderRadius: 8, padding: "8px 12px" }}>
                <div style={{ fontSize: 13 }}>
                  <strong>{mesesNombres[(s.mes||1)-1]} {s.anio}</strong>
                  <span style={{ color: GC.ink3, marginLeft: 8, fontSize: 12 }}>Saldo: {formatCOP(s.saldoActual)}</span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  <span style={{ color: "#16a34a", fontWeight: 700, fontSize: 13 }}>- {formatCOP(s.pagar)}</span>
                  <span style={{ fontSize: 12, color: s.nuevaSaldo <= 0 ? "#16a34a" : "#d97706", fontWeight: 700 }}>
                    {s.nuevaSaldo <= 0 ? "PAGADO" : "Saldo: " + formatCOP(s.nuevaSaldo)}
                  </span>
                </div>
              </div>
            ))}
          </div>
          {sobrante > 0 && (
            <div style={{ background: "#fef3c7", border: "1px solid #fde047", borderRadius: 8, padding: "8px 12px", marginTop: 6, fontSize: 12, color: "#92400e" }}>
              ⚠️ Sobrante de <strong>{formatCOP(sobrante)}</strong> — cubre toda la deuda y sobra dinero
            </div>
          )}
        </div>
      )}

      <Btn onClick={aplicarAbono} disabled={procesando || simulacion.length === 0}
        style={{ width: "100%", background: "#16a34a", fontSize: 14 }}>
        {procesando ? "⏳ Aplicando abono..." : `✅ Aplicar abono de ${montoAbono ? formatCOP(Number(montoAbono)) : "$0"} en ${simulacion.length} factura(s)`}
      </Btn>
    </div>
  );
}

function SeccionHistorial({ usuario, facturas, setFacturas, facturasHistoricas = [], usuarios, zonas, esAdmin, esSuperusuario, COLOR_ESTADO, AccionesFact, nombreEmpresa, setConfirmDelete, setConfirmAnular, agregarAbonoHoyRef }) {
  const [busq, setBusq] = useState("");
  const [filtroAnio, setFiltroAnio] = useState(new Date().getFullYear());
  const [filtroMes, setFiltroMes] = useState(0);
  const [filtroDia, setFiltroDia] = useState("");
  const [clienteDetalle, setClienteDetalle] = useState(null);
  const [abonosDetalle, setAbonosDetalle] = useState({});
  const [modalEditFact, setModalEditFact] = useState(null); // factura a editar
  const [editFactData, setEditFactData] = useState({});
  const [guardandoEdit, setGuardandoEdit] = useState(false);
  const [abonosDia, setAbonosDia] = useState([]);
  const [cargandoDia, setCargandoDia] = useState(false);
  const [movimientosCaja, setMovimientosCaja] = useState([]);
  useEffect(()=>{db.getMovimientosCaja(esAdmin?null:usuario?.zonaId).then(setMovimientosCaja).catch(()=>{});}, [esAdmin, usuario?.zonaId]);
  useEffect(()=>{
    if (!filtroDia){setAbonosDia([]);return;}
    setCargandoDia(true);
    db.getAbonosByFecha(filtroDia).then(d=>setAbonosDia(d||[])).catch(()=>setAbonosDia([])).finally(()=>setCargandoDia(false));
  },[filtroDia]);
  const cobradoDia   = filtroDia?abonosDia.filter(a=>{const f=facturas.find(x=>x.id===a.facturaId);return !f||f.estado!=="Anulada";}).reduce((s,a)=>s+a.monto,0):0;
  const ingresosDia  = filtroDia?movimientosCaja.filter(m=>m.tipo==="Ingreso"&&m.fecha===filtroDia).reduce((s,m)=>s+m.monto,0):0;
  const egresosDia   = filtroDia?movimientosCaja.filter(m=>m.tipo==="Egreso" &&m.fecha===filtroDia).reduce((s,m)=>s+m.monto,0):0;
  const totalCajaDia = cobradoDia+ingresosDia-egresosDia;

  // Búsqueda directa en Supabase — igual que en Emitidas, trae TODAS las facturas sin límite
  const [resultadosHistorial, setResultadosHistorial] = useState([]);
  const [buscandoHistorial, setBuscandoHistorial] = useState(false);
  const busqTimerHistorial = useRef(null);

  const busqActiva = busq.trim().length >= 2;

  useEffect(() => {
    const q = busq.trim();
    if (q.length < 2) { setResultadosHistorial([]); setBuscandoHistorial(false); return; }
    setBuscandoHistorial(true);
    clearTimeout(busqTimerHistorial.current);
    busqTimerHistorial.current = setTimeout(async () => {
      try {
        // Un secretario (no admin) SIEMPRE busca solo en su propia zona — nunca puede ver la otra.
        const zonaParaBuscar = !esAdmin ? usuario?.zonaId : null;
        const res = await db.buscarFacturasPorNombre(q, zonaParaBuscar);
        setResultadosHistorial(res);
      } catch { setResultadosHistorial([]); }
      finally { setBuscandoHistorial(false); }
    }, 400);
    return () => clearTimeout(busqTimerHistorial.current);
  }, [busq, esAdmin, usuario?.zonaId]);

  // Cuando hay búsqueda activa usar resultados de Supabase (completos, sin límite de meses)
  // Cuando hay filtroDia combinar facturas locales + históricas
  const todasParaBusqueda = filtroDia
    ? [...facturas, ...facturasHistoricas].filter((f, i, arr) => arr.findIndex(x => x.id === f.id) === i)
    : facturas;

  const facturasAudit = (busqActiva ? resultadosHistorial : todasParaBusqueda).filter(f => {
    if (busqActiva) return true; // ya vienen filtradas de Supabase
    // Sin búsqueda: filtros normales por fecha
    if (!filtroDia) {
      if (f.anio !== filtroAnio) return false;
      if (filtroMes > 0 && f.mes !== filtroMes) return false;
    }
    if (filtroDia) {
      const pagadaEseDia = f.fechaPago === filtroDia;
      const emitidaEseDia = f.fechaEmision === filtroDia;
      if (!pagadaEseDia && !emitidaEseDia) return false;
    }
    return true;
  }).sort((a, b) => {
    if (busqActiva) {
      const nc = (a.clienteNombre||"").localeCompare(b.clienteNombre||"");
      if (nc !== 0) return nc;
      return (b.anio*12+b.mes) - (a.anio*12+a.mes);
    }
    return (b.fechaEmision||"").localeCompare(a.fechaEmision||"");
  });

  // Agrupar por cliente cuando hay búsqueda
  const clienteBuscado = busqActiva && facturasAudit.length > 0 ? (() => {
    const ids = [...new Set(facturasAudit.map(f => f.clienteId))];
    if (ids.length === 1) return { id: ids[0], nombre: facturasAudit[0].clienteNombre };
    return null;
  })() : null;

  // Resumen de deuda cuando se busca un cliente específico
  const resumenCliente = clienteBuscado ? (() => {
    const fact = facturasAudit.filter(f => f.clienteId === clienteBuscado.id && f.estado !== "Anulada");
    const deudaTotal = fact.reduce((s, f) => s + f.saldoPendiente, 0);
    const mesesDeuda = fact.filter(f => f.saldoPendiente > 0).length;
    return { deudaTotal, mesesDeuda, total: fact.length };
  })() : null;

  const totalFact    = facturasAudit.reduce((s, f) => s + f.monto, 0);
  const totalCobrado = facturasAudit.reduce((s, f) => s + ((f.monto - f.saldoPendiente - (f.descuento_pronto_pago || 0))), 0);
  const totalPend    = facturasAudit.reduce((s, f) => s + f.saldoPendiente, 0);

  // Guardar edición de factura
  const guardarEdicion = async () => {
    setGuardandoEdit(true);
    try {
      const nuevo = {
        concepto:   editFactData.concepto,
        monto:      Number(editFactData.monto),
        notas:      editFactData.notas || null,
        fecha_pago: editFactData.fechaPago || null,
        estado:     editFactData.estado,
        saldo_pendiente: editFactData.estado === "Pagado" ? 0 : Number(editFactData.saldoPendiente),
      };
      await db.actualizarFactura(modalEditFact.id, nuevo);
      setFacturas(prev => prev.map(f => f.id === modalEditFact.id
        ? { ...f, concepto: nuevo.concepto, monto: nuevo.monto, notas: nuevo.notas, fechaPago: nuevo.fecha_pago, estado: nuevo.estado, saldoPendiente: nuevo.saldo_pendiente }
        : f
      ));
      setModalEditFact(null);
    } catch(e) { alert("Error al guardar: " + e.message); }
    setGuardandoEdit(false);
  };

  const imprimirTirilla = (cliente, listaFact) => {
    const cop = v => v.toLocaleString("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 });
    const totalCli = listaFact.reduce((s,f) => s + f.monto, 0);
    const cobradoCli = listaFact.reduce((s,f) => s + ((f.monto - f.saldoPendiente - (f.descuento_pronto_pago || 0))), 0);
    const pagadas = listaFact.filter(f => f.estado === "Pagado").length;
    const filas = listaFact.map(f => {
      const colorBg = {"Pagado":"#dcfce7","Pendiente":"#fef9c3","Abono parcial":"#dbeafe","Vencido":"#fee2e2","Anulada":"#f1f5f9"}[f.estado]||"#f1f5f9";
      const colorTxt = {"Pagado":"#16a34a","Pendiente":"#92400e","Abono parcial":"#0369a1","Vencido":"#b91c1c","Anulada":"#64748b"}[f.estado]||"#555";
      return `<tr><td>${f.numeroRecibo||"—"}</td><td>${MESES[(f.mes||1)-1]} ${f.anio}</td><td><span style="background:${colorBg};color:${colorTxt};padding:1px 5px;border-radius:3px;font-weight:bold">${f.estado}</span></td><td style="text-align:right">${cop(f.monto)}</td><td style="text-align:right;color:${f.saldoPendiente>0?"#dc2626":"#16a34a"}">${cop(f.monto-f.saldoPendiente)}</td></tr>`;
    }).join("");
    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Historial</title>
    <style>
      @page { size: 76mm auto; margin: 8mm 6mm; }
      body { font-family: "Courier New", Courier, monospace; font-size: 9pt; color: #000; width: 64mm; padding: 4mm; line-height: 1.4; }
      .center { text-align: center; } .bold { font-weight: bold; }
      .sep { border: none; border-top: 1px dashed #555; margin: 6px 0; }
      .sep-solid { border: none; border-top: 1px solid #000; margin: 5px 0; }
      table { width: 100%; border-collapse: collapse; font-size: 7.5pt; }
      th { border-bottom: 1px solid #000; padding: 3px 2px; text-align: left; font-size: 7pt; }
      td { padding: 3px 2px; border-bottom: 1px dotted #ccc; }
      .total-row td { font-weight: 900; border-top: 2px solid #000; font-size: 9pt; padding: 5px 2px; }
      .btn-print { display: block; margin: 12px auto; padding: 8px 20px; background: #1d4ed8; color: #fff; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; font-weight: 700; }
      @media print { .btn-print { display: none; } body { width: 64mm; padding: 0; } }
    </style></head><body>
    <div class="center"><div class="bold" style="font-size:10.5pt;text-transform:uppercase">${nombreEmpresa}</div><div style="font-size:8pt">Tel: 318-8255601</div></div>
    <hr class="sep"/>
    <div class="center bold" style="font-size:9pt">HISTORIAL DE PAGOS</div>
    <div class="center" style="font-size:7.5pt;margin:2px 0">${new Date().toLocaleDateString("es-CO")}</div>
    <hr class="sep"/>
    <div class="bold" style="font-size:9pt">${cliente.nombre}</div>
    <div style="font-size:7.5pt">CC: ${listaFact[0]?.clienteCedula||"—"}</div>
    <div style="font-size:7.5pt">${listaFact[0]?.clienteDireccion||""}</div>
    <hr class="sep"/>
    <table><thead><tr><th>#</th><th>Mes</th><th>Estado</th><th style="text-align:right">Total</th><th style="text-align:right">Cobrado</th></tr></thead>
    <tbody>${filas}</tbody>
    <tr class="total-row"><td colspan="3">TOTALES (${listaFact.length} fact.)</td><td style="text-align:right">${cop(totalCli)}</td><td style="text-align:right;color:#16a34a">${cop(cobradoCli)}</td></tr>
    </table>
    <hr class="sep"/>
    <div style="font-size:7.5pt;text-align:center">Facturas pagadas: ${pagadas} / ${listaFact.length}</div>
    <hr class="sep"/>
    <div style="font-size:7.5pt;text-align:center">Gracias por su pago</div>
    <br/><button class="btn-print" onclick="window.print()">🖨️ Imprimir</button>
    </body></html>`;
    const w = window.open("", "_blank", "width=340,height=700");
    w.document.write(html); w.document.close();
  };

  return (
    <div>
      {/* Filtros */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap", alignItems: "center" }}>
        <Inp placeholder="🔍 Nombre, cédula o N° recibo..." value={busq} onChange={e => setBusq(e.target.value)} style={{ flex: 1, minWidth: 200 }} />
        {/* Solo mostrar filtros de fecha si NO hay búsqueda activa */}
        {!busqActiva && <>
          <Sel value={filtroAnio} onChange={e => setFiltroAnio(Number(e.target.value))} style={{ width: "auto", minWidth: 80 }}>
            {[2024,2025,2026,2027].map(a => <option key={a} value={a}>{a}</option>)}
          </Sel>
          <Sel value={filtroMes} onChange={e => setFiltroMes(Number(e.target.value))} style={{ width: "auto", minWidth: 110 }}>
            <option value={0}>Todos los meses</option>
            {MESES.map((m, i) => <option key={i} value={i+1}>{m}</option>)}
          </Sel>
          <Inp type="date" value={filtroDia} onChange={e => setFiltroDia(e.target.value)} style={{ width: "auto" }} title="Filtrar por día exacto" />
        </>}
        {(busq || filtroMes > 0 || filtroDia) && (
          <button onClick={() => { setBusq(""); setFiltroMes(0); setFiltroDia(""); }}
            style={{ background: GC.bg3, border: "none", borderRadius: 8, padding: "7px 12px", cursor: "pointer", fontSize: 13, color: GC.ink2 }}>✕ Limpiar</button>
        )}
        <span style={{ fontSize: 12, color: GC.ink3 }}>{facturasAudit.length} registros {busqActiva ? "(todas las fechas)" : ""}</span>
      </div>

      {/* Banner búsqueda por nombre activa */}
      {busqActiva && (
        <div style={{ background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 10, padding: "10px 14px", marginBottom: 12, fontSize: 13, color: "#1e40af", display: "flex", alignItems: "center", gap: 8 }}>
          {buscandoHistorial
            ? <><span>⏳</span> Buscando en todas las facturas...</>
            : <><span>🔍</span> Resultados para <strong>"{busq.trim()}"</strong> en <strong>todos los meses</strong> · {facturasAudit.length} facturas</>
          }
        </div>
      )}

      {/* Resumen de deuda cuando se encuentra un cliente específico */}
      {resumenCliente && resumenCliente.deudaTotal > 0 && (
        <div style={{ background: "#fef2f2", border: "2px solid #fecaca", borderRadius: 12, padding: "12px 16px", marginBottom: 14 }}>
          <div style={{ fontWeight: 800, color: "#dc2626", fontSize: 15, marginBottom: 4 }}>
            ⚠️ {clienteBuscado.nombre} tiene deuda pendiente
          </div>
          <div style={{ display: "flex", gap: 20, flexWrap: "wrap", fontSize: 13 }}>
            <span>Meses sin pagar: <strong style={{ color: "#dc2626" }}>{resumenCliente.mesesDeuda}</strong></span>
            <span>Deuda total: <strong style={{ color: "#dc2626", fontSize: 16 }}>{formatCOP(resumenCliente.deudaTotal)}</strong></span>
            <span>Total facturas: <strong>{resumenCliente.total}</strong></span>
          </div>
        </div>
      )}

      {/* ── PANEL ABONO MASIVO ── */}
      {clienteBuscado && resumenCliente && resumenCliente.deudaTotal > 0 && (
        <PanelAbonoMasivo
          clienteBuscado={clienteBuscado}
          facturasCliente={facturasAudit.filter(f => f.clienteId === clienteBuscado.id && f.saldoPendiente > 0 && f.estado !== "Anulada").sort((a,b) => (a.anio*12+a.mes) - (b.anio*12+b.mes))}
          deudaTotal={resumenCliente.deudaTotal}
          usuario={usuario}
          setFacturas={setFacturas}
          hoyStr={new Date().toISOString().split("T")[0]}
          dbObj={db}
          agregarAbonoHoyRef={agregarAbonoHoyRef}
        />
      )}

      {/* Modal editar factura — solo admin y superusuario */}
      {modalEditFact && (esAdmin || esSuperusuario) && (
        <div style={{ position: "fixed", inset: 0, background: "#00000066", zIndex: 9000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
          onClick={e => e.target === e.currentTarget && setModalEditFact(null)}>
          <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 460, padding: 24, boxShadow: "0 20px 60px #00000033" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
              <div>
                <div style={{ fontWeight: 800, fontSize: 16 }}>✏️ Editar factura</div>
                <div style={{ fontSize: 12, color: GC.ink3 }}>{modalEditFact.clienteNombre} · #{modalEditFact.numeroRecibo}</div>
              </div>
              <button onClick={() => setModalEditFact(null)} style={{ background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            </div>
            <Field label="Concepto">
              <Inp value={editFactData.concepto || ""} onChange={e => setEditFactData(p => ({ ...p, concepto: e.target.value }))} />
            </Field>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 12px" }}>
              <Field label="Monto total ($)">
                <Inp type="number" value={editFactData.monto || ""} onChange={e => setEditFactData(p => ({ ...p, monto: e.target.value }))} />
              </Field>
              <Field label="Saldo pendiente ($)">
                <Inp type="number" value={editFactData.saldoPendiente || ""} onChange={e => setEditFactData(p => ({ ...p, saldoPendiente: e.target.value }))} />
              </Field>
              <Field label="Estado">
                <Sel value={editFactData.estado || "Pendiente"} onChange={e => setEditFactData(p => ({ ...p, estado: e.target.value }))}>
                  <option>Pendiente</option>
                  <option>Pagado</option>
                  <option>Abono parcial</option>
                  <option>Vencido</option>
                </Sel>
              </Field>
              <Field label="Fecha de pago">
                <Inp type="date" value={editFactData.fechaPago || ""} onChange={e => setEditFactData(p => ({ ...p, fechaPago: e.target.value }))} />
              </Field>
            </div>
            <Field label="Notas (opcional)">
              <Inp value={editFactData.notas || ""} onChange={e => setEditFactData(p => ({ ...p, notas: e.target.value }))} placeholder="Observaciones sobre esta factura..." />
            </Field>
            <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
              <Btn onClick={guardarEdicion} disabled={guardandoEdit} style={{ flex: 1 }}>
                {guardandoEdit ? "Guardando..." : "💾 Guardar cambios"}
              </Btn>
              <button onClick={() => setModalEditFact(null)} style={{ padding: "9px 16px", background: GC.bg3, border: "none", borderRadius: 9, cursor: "pointer", fontSize: 13, fontFamily: "inherit" }}>Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {facturasAudit.length > 0 && (
        <div style={{ marginBottom: 14 }}>
          {filtroDia && <div style={{ fontSize:11,fontWeight:700,color:GC.ink3,textTransform:"uppercase",letterSpacing:0.8,marginBottom:8 }}>📅 {new Date(filtroDia+"T12:00:00").toLocaleDateString("es-CO",{weekday:"long",day:"numeric",month:"long",year:"numeric"})}</div>}
          <div style={{ display:"flex",gap:8,flexWrap:"wrap" }}>
            {filtroDia&&!cargandoDia&&(<>
              <div style={{ background:"#faf5ff",border:"2px solid #a78bfa",borderRadius:10,padding:"10px 14px",minWidth:150,flex:1 }}>
                <div style={{ fontSize:10,color:"#7c3aed",textTransform:"uppercase",letterSpacing:0.7,fontWeight:700 }}>📅 Cobrado ese día</div>
                <div style={{ fontWeight:900,color:"#7c3aed",fontSize:16,marginTop:2 }}>{formatCOP(cobradoDia)}</div>
                <div style={{ fontSize:10,color:GC.ink3,marginTop:1 }}>{abonosDia.filter(a=>{const f=facturas.find(x=>x.id===a.facturaId);return !f||f.estado!=="Anulada";}).length} cobros{ingresosDia>0?` · +${formatCOP(ingresosDia)} ing.`:""}{ egresosDia>0?` · −${formatCOP(egresosDia)} egr.`:""}</div>
              </div>
              <div style={{ background:GC.brandLight,border:"2px solid #22c55e",borderRadius:10,padding:"10px 14px",minWidth:150,flex:1 }}>
                <div style={{ fontSize:10,color:GC.brand,textTransform:"uppercase",letterSpacing:0.7,fontWeight:700 }}>🏦 Total en caja ese día</div>
                <div style={{ fontWeight:900,color:GC.brand,fontSize:16,marginTop:2 }}>{formatCOP(totalCajaDia)}</div>
                <div style={{ fontSize:10,color:GC.ink3,marginTop:1 }}>cobros + ingresos − egresos</div>
              </div>
            </>)}
            {filtroDia&&cargandoDia&&<div style={{ background:"#faf5ff",border:"2px solid #a78bfa",borderRadius:10,padding:"10px 14px",flex:1,color:GC.ink3,fontSize:13 }}>Cargando...</div>}
            {[["💰 Total facturado",formatCOP(totalFact),"#0ea5e9"],["✅ Total cobrado",formatCOP(totalCobrado),"#22c55e"],["⏳ Saldo pendiente",formatCOP(totalPend),"#ef4444"]].map(([label,val,color])=>(
              <div key={label} style={{ background:"#fff",border:"1px solid "+color+"33",borderRadius:10,padding:"10px 14px",flex:1,minWidth:120 }}>
                <div style={{ fontSize:10,color:GC.ink3,textTransform:"uppercase",letterSpacing:0.7 }}>{label}</div>
                <div style={{ fontWeight:800,color,fontSize:15,marginTop:2 }}>{val}</div>
              </div>
            ))}
            {clienteBuscado&&(
              <button onClick={()=>imprimirTirilla(clienteBuscado,facturasAudit)}
                style={{ background:GC.brandLight,color:GC.brand,border:"1px solid #bbf7d0",borderRadius:10,padding:"10px 14px",cursor:"pointer",fontWeight:700,fontSize:13,alignSelf:"stretch" }}>
                🖨️ Tirilla del cliente
              </button>
            )}
          </div>
        </div>
      )}

      {/* Resumen anual del cliente si es búsqueda específica */}
      {clienteBuscado && (() => {
        const todas = facturas.filter(f => f.clienteId === clienteBuscado.id);
        const pagadasAnio = todas.filter(f => f.anio === filtroAnio && f.estado === "Pagado").length;
        const totalAnio = todas.filter(f => f.anio === filtroAnio).length;
        return (
          <div style={{ background: GC.brandLight, border: "1px solid #bbf7d0", borderLeft: "4px solid " + GC.brand, borderRadius: 12, padding: "12px 16px", marginBottom: 14 }}>
            <div style={{ fontWeight: 700, color: GC.brand, marginBottom: 4 }}>📊 Resumen anual {filtroAnio} — {clienteBuscado.nombre}</div>
            <div style={{ display: "flex", gap: 20, flexWrap: "wrap", fontSize: 13, color: GC.ink2 }}>
              <span>✅ Facturas pagadas: <strong>{pagadasAnio} / {totalAnio}</strong></span>
              <span>💰 Total cobrado en {filtroAnio}: <strong>{formatCOP(todas.filter(f=>f.anio===filtroAnio).reduce((s,f)=>s+(f.monto-f.saldoPendiente),0))}</strong></span>
              <span>⏳ Pendiente: <strong>{formatCOP(todas.filter(f=>f.anio===filtroAnio).reduce((s,f)=>s+f.saldoPendiente,0))}</strong></span>
            </div>
          </div>
        );
      })()}

      {/* Tabla de auditoría */}
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
          <thead>
            <tr style={{ background: GC.bg2, borderBottom: "2px solid #e2e8f0" }}>
              {["#Recibo", "Fecha", "Cliente", "Cédula", "Mes", "Total", "Saldo", "Método", "Estado", "Acciones"].map(h => (
                <th key={h} style={{ padding: "8px 12px", textAlign: "left", color: GC.ink3, fontWeight: 700, whiteSpace: "nowrap" }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {facturasAudit.length === 0 ? (
              <tr><td colSpan={9} style={{ padding: 30, textAlign: "center", color: GC.ink4 }}>{buscandoHistorial ? "⏳ Buscando..." : busq.trim() ? `Sin facturas para "${busq.trim()}"` : "Sin registros para el filtro seleccionado"}</td></tr>
            ) : facturasAudit.map(f => {
              const verFact = () => {
                const w = window.open("", "_blank", "width=380,height=640");
                const its = Array.isArray(f.items) ? f.items : [];
                const cop = v => Number(v).toLocaleString("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 });
                const mp = getMetodoEmoji(f.metodoPago);
                w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Factura #${f.numeroRecibo}</title><style>@page{size:76mm auto;margin:8mm 6mm}body{font-family:'Courier New',monospace;font-size:9pt;width:64mm;padding:4mm;line-height:1.5}.c{text-align:center}.b{font-weight:bold}.sep{border:none;border-top:1px dashed #555;margin:6px 0}table{width:100%;border-collapse:collapse;font-size:8pt}td,th{padding:3px 2px}th{border-bottom:1px solid #000;font-size:7.5pt}.tr td{font-weight:900;border-top:2px solid #000;padding:5px 2px}@media print{.btn{display:none}body{width:64mm;padding:0}}</style></head><body><div class="c b" style="font-size:11pt;text-transform:uppercase">FACTURA #${f.numeroRecibo||"—"}</div><div class="c" style="font-size:8pt">Fecha: ${f.fechaPago||f.fechaEmision||"—"}</div><hr class="sep"/><div class="b">${f.clienteNombre}</div><div style="font-size:8pt">CC: ${f.clienteCedula||"—"}</div><div style="font-size:8pt">${f.clienteDireccion||""}</div><hr class="sep"/><table><thead><tr><th>Concepto</th><th style="text-align:right">Valor</th></tr></thead><tbody>${its.map(i=>`<tr><td>${i.concepto||""}</td><td style="text-align:right">${cop(i.monto||0)}</td></tr>`).join("")}</tbody><tr class="tr"><td>TOTAL</td><td style="text-align:right">${cop(f.monto)}</td></tr></table><hr class="sep"/><div style="font-size:8pt">Estado: <b>${f.estado}</b></div><div style="font-size:8pt">Método de pago: <b>${mp} ${f.metodoPago||"—"}</b></div>${f.saldoPendiente>0?`<div style="font-size:8pt;color:#dc2626">Saldo pendiente: <b>${cop(f.saldoPendiente)}</b></div>`:`<div style="font-size:8pt;color:#16a34a">✅ Pagado completo</div>`}<hr class="sep"/><div class="c" style="font-size:7.5pt">Gracias por su pago</div><br/><button class="btn" onclick="window.print()" style="display:block;margin:10px auto;padding:8px 20px;background:#1d4ed8;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:13px">🖨️ Imprimir</button></body></html>`);
                w.document.close();
              };
              return (
              <tr key={f.id} style={{ borderBottom: "1px solid #f1f5f9", opacity: f.estado === "Anulada" ? 0.5 : 1 }}>
                <td style={{ padding: "8px 12px", color: GC.info, fontWeight: 700 }}>#{f.numeroRecibo || f.id?.slice(-6)}</td>
                <td style={{ padding: "8px 12px", color: GC.ink2 }}>{f.fechaPago || f.fechaEmision}</td>
                <td style={{ padding: "8px 12px", fontWeight: 600 }}>{f.clienteNombre}</td>
                <td style={{ padding: "8px 12px", color: GC.ink2 }}>{f.clienteCedula}</td>
                <td style={{ padding: "8px 12px", color: GC.ink2 }}>{MESES[(f.mes||1)-1]} {f.anio}</td>
                <td style={{ padding: "8px 12px", fontWeight: 700 }}>{formatCOP(f.monto)}</td>
                <td style={{ padding: "8px 12px", color: f.saldoPendiente > 0 ? "#ef4444" : "#22c55e", fontWeight: 700 }}>{formatCOP(f.saldoPendiente)}</td>
                <td style={{ padding: "8px 12px" }}>
                  {f.metodoPago ? (
                    <span style={{ background: GC.infoBg, color: GC.info, borderRadius: 6, padding: "2px 8px", fontSize: 11, fontWeight: 700 }}>
                      {getMetodoEmoji(f.metodoPago)} {f.metodoPago}
                    </span>
                  ) : <span style={{ color: GC.ink4, fontSize: 11 }}>—</span>}
                </td>
                <td style={{ padding: "8px 12px" }}><span style={{ background: (COLOR_ESTADO[f.estado]||"#94a3b8") + "22", color: COLOR_ESTADO[f.estado]||"#64748b", borderRadius: 6, padding: "2px 8px", fontWeight: 700, fontSize: 11 }}>{f.estado}</span></td>
                <td style={{ padding: "8px 6px" }}>
                  <div style={{ display: "flex", gap: 4 }}>
                    <button onClick={verFact} style={{ background: GC.infoBg, color: GC.info, border: "none", borderRadius: 6, padding: "4px 7px", cursor: "pointer", fontSize: 12 }} title="Ver factura">🧾</button>
                    {(esAdmin || esSuperusuario) && f.estado !== "Anulada" && (
                      <button onClick={() => {
                        setEditFactData({ concepto: f.concepto, monto: f.monto, saldoPendiente: f.saldoPendiente, estado: f.estado, fechaPago: f.fechaPago || "", notas: f.notas || "" });
                        setModalEditFact(f);
                      }} style={{ background: "#eff6ff", color: "#1d4ed8", border: "none", borderRadius: 6, padding: "4px 7px", cursor: "pointer", fontSize: 12 }} title="Editar factura">✏️</button>
                    )}
                    {f.estado !== "Anulada" && (esAdmin || esSuperusuario) && (
                      <button onClick={() => setConfirmAnular({ id: f.id, nombre: f.clienteNombre })}
                        style={{ background: "#fffbeb", color: "#d97706", border: "none", borderRadius: 6, padding: "4px 7px", cursor: "pointer", fontSize: 12 }} title="Anular">🚫</button>
                    )}
                    {esSuperusuario && (
                      <button onClick={() => setConfirmDelete({ id: f.id, nombre: f.clienteNombre })}
                        style={{ background: "#fef2f2", color: "#dc2626", border: "none", borderRadius: 6, padding: "4px 7px", cursor: "pointer", fontSize: 12 }} title="Eliminar permanente">🗑️</button>
                    )}
                  </div>
                </td>
              </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}


// ── Vista facturación para el CLIENTE ─────────────────────────
function FacturacionCliente({ usuario }) {
  const [facturas, setFacturas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const COLOR_ESTADO = { "Pendiente": "#f59e0b", "Pagado": "#22c55e", "Abono parcial": "#0ea5e9", "Vencido": "#ef4444" };

  useEffect(() => {
    db.getFacturasByCliente(usuario.id).then(setFacturas).catch(console.error).finally(() => setCargando(false));
  }, []);

  const totalPendiente = facturas.filter(f => f.estado !== "Pagado").reduce((s, f) => s + f.saldoPendiente, 0);

  return (
    <div>
      {totalPendiente > 0 && (
        <div style={{ background: "#fef2f2", border: "1px solid #fecaca", borderLeft: "4px solid #ef4444", borderRadius: 10, padding: "12px 16px", marginBottom: 16 }}>
          <div style={{ fontWeight: 700, color: "#dc2626", fontSize: 14 }}>⚠️ Tienes saldo pendiente</div>
          <div style={{ fontSize: 22, fontWeight: 800, color: "#dc2626" }}>{formatCOP(totalPendiente)}</div>
          <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>Acércate a la oficina o llama para regularizar tu pago.</div>
        </div>
      )}
      {cargando ? <div style={{ textAlign: "center", color: GC.ink4, padding: 40 }}>Cargando...</div> :
        facturas.length === 0 ? <div style={{ textAlign: "center", color: GC.ink4, padding: 40 }}>Sin facturas registradas aún.</div> :
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {facturas.map(f => (
            <div key={f.id} style={{ background: "#fff", border: "1px solid " + GC.border, borderLeft: "4px solid " + (COLOR_ESTADO[f.estado] || "#e2e8f0"), borderRadius: 12, padding: "12px 16px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
                <div>
                  <div style={{ fontWeight: 700, color: GC.ink }}>{f.concepto}</div>
                  <div style={{ fontSize: 12, color: GC.ink3 }}>Emitida: {f.fechaEmision} {f.numeroRecibo ? `· Recibo #${f.numeroRecibo}` : ""}</div>
                  {f.saldoPendiente > 0 && f.saldoPendiente < f.monto && (
                    <div style={{ fontSize: 12, color: GC.warning, marginTop: 2 }}>Abonado: {formatCOP((f.monto - f.saldoPendiente - (f.descuento_pronto_pago || 0)))} · Saldo: {formatCOP(f.saldoPendiente)}</div>
                  )}
                </div>
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontWeight: 800, fontSize: 16, color: GC.ink }}>{formatCOP(f.monto)}</div>
                  <Badge text={f.estado} color={COLOR_ESTADO[f.estado] || "#64748b"} />
                </div>
              </div>
            </div>
          ))}
        </div>
      }
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// SECCIÓN EQUIPO DE TRABAJO
// ══════════════════════════════════════════════════════════════
function SeccionEquipoTrabajo({ usuarios, zonas, zonaId }) {
  const ROL_BG = { admin: GC.brand, secretario: GC.purple, tecnico: GC.warning };
  const ROL_ICON = { admin: "🛡️", secretario: "🗂️", tecnico: "🔧" };
  const miembros = usuarios.filter(u =>
    ["admin","secretario","tecnico"].includes(u.rol) && u.activo &&
    (!zonaId || u.rol === "admin" || u.zonaId === zonaId)
  ).sort((a,b) => {
    const orden = { admin:0, secretario:1, tecnico:2 };
    return (orden[a.rol]||3) - (orden[b.rol]||3);
  });

  return (
    <div>
      <div style={{ fontSize: 13, color: GC.ink3, marginBottom: 16 }}>
        {miembros.length} miembros en el equipo
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px,1fr))", gap: 14 }}>
        {miembros.map(u => {
          const zona = zonas.find(z => z.id === u.zonaId);
          const bg = ROL_BG[u.rol] || "#64748b";
          return (
            <div key={u.id} style={{ background: "#fff", border: "1px solid " + GC.border, borderRadius: 14, overflow: "hidden", boxShadow: "0 2px 8px #00000008" }}>
              {/* Header color */}
              <div style={{ background: bg, padding: "14px 16px", display: "flex", alignItems: "center", gap: 10 }}>
                <div style={{ width: 40, height: 40, borderRadius: "50%", background: "rgba(255,255,255,0.25)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20 }}>
                  {ROL_ICON[u.rol] || "👤"}
                </div>
                <div>
                  <div style={{ fontWeight: 700, color: "#fff", fontSize: 13 }}>{u.nombre}</div>
                  <div style={{ fontSize: 11, color: "rgba(255,255,255,0.8)" }}>
                    {u.rol === "admin" ? "Administrador" : u.rol === "secretario" ? "Secretario/a" : "Técnico"}
                  </div>
                </div>
              </div>
              {/* Info */}
              <div style={{ padding: "12px 16px", display: "flex", flexDirection: "column", gap: 6 }}>
                {u.telefono && (
                  <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13 }}>
                    <span>📞</span>
                    <a href={`tel:${u.telefono}`} style={{ color: GC.info, fontWeight: 600, textDecoration: "none" }}>{u.telefono}</a>
                  </div>
                )}
                {zona && (
                  <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
                    <span style={{ color: zona.color }}>📍</span>
                    <span style={{ color: GC.ink3 }}>Zona {zona.nombre}</span>
                  </div>
                )}
                {!u.telefono && <div style={{ fontSize: 12, color: GC.ink4, fontStyle: "italic" }}>Sin teléfono registrado</div>}
              </div>
            </div>
          );
        })}
      </div>
      {miembros.length === 0 && (
        <div style={{ textAlign: "center", color: GC.ink4, padding: 50 }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>👷</div>
          No hay miembros del equipo en esta zona.
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// SECCIÓN EQUIPOS MOROSOS
// ══════════════════════════════════════════════════════════════
function SeccionEquiposMorosos({ usuarios, ordenes, setOrdenes, tecnicos, secretarioId, zonaId }) {
  const [modalRecogida, setModalRecogida] = React.useState(null);
  const [recogidas, setRecogidas] = React.useState(() => {
    try { return JSON.parse(localStorage.getItem("gc_recogidas") || "[]"); } catch { return []; }
  });
  const [formRecogida, setFormRecogida] = React.useState({ tecnicoId: "", descripcionEquipo: "", fecha: fechaLocal(), observacion: "" });
  const [showActa, setShowActa] = React.useState(null);

  const morosos = usuarios.filter(u =>
    u.rol === "cliente" && u.activo && u.estado === "Vencido" &&
    (!zonaId || u.zonaId === zonaId)
  );

  const guardarRecogida = () => {
    if (!formRecogida.tecnicoId || !formRecogida.descripcionEquipo.trim()) {
      alert("Debes asignar un técnico y describir el equipo."); return;
    }
    const tecnico = tecnicos.find(t => t.id === formRecogida.tecnicoId);
    const nuevaRecogida = {
      id: Date.now().toString(),
      clienteId: modalRecogida.id,
      clienteNombre: modalRecogida.nombre,
      clienteCedula: modalRecogida.cedula,
      clienteDireccion: modalRecogida.direccion,
      clienteTelefono: modalRecogida.telefono,
      tecnicoId: formRecogida.tecnicoId,
      tecnicoNombre: tecnico?.nombre || "Sin asignar",
      descripcionEquipo: formRecogida.descripcionEquipo,
      fecha: formRecogida.fecha,
      observacion: formRecogida.observacion,
      secretarioId,
      estado: "Asignada",
      creadoEn: new Date().toISOString(),
    };
    const nuevas = [nuevaRecogida, ...recogidas];
    setRecogidas(nuevas);
    try { localStorage.setItem("gc_recogidas", JSON.stringify(nuevas)); } catch {}
    setModalRecogida(null);
    setFormRecogida({ tecnicoId: "", descripcionEquipo: "", fecha: fechaLocal(), observacion: "" });
    alert(`✅ Recogida asignada a ${tecnico?.nombre}. Fecha: ${formRecogida.fecha}`);
  };

  const recogidaSemana = recogidas.filter(r => {
    const hace7 = fechaLocal(new Date(Date.now() - 7*86400000));
    return r.fecha >= hace7;
  });

  return (
    <div>
      {/* Resumen */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(140px,1fr))", gap: 10, marginBottom: 20 }}>
        {[
          ["🔴 Clientes morosos", morosos.length, "#ef4444"],
          ["📦 Recogidas esta semana", recogidaSemana.length, "#f59e0b"],
          ["✅ Total recogidas", recogidas.length, "#22c55e"],
        ].map(([label, val, color]) => (
          <div key={label} style={{ background: "#fff", border: "1px solid " + color + "33", borderTop: "3px solid " + color, borderRadius: 12, padding: "14px 16px", textAlign: "center" }}>
            <div style={{ fontWeight: 800, fontSize: 22, color }}>{val}</div>
            <div style={{ fontSize: 11, color: GC.ink3, marginTop: 4 }}>{label}</div>
          </div>
        ))}
      </div>

      {/* Lista de morosos */}
      <div style={{ fontSize: 12, color: GC.ink3, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 10 }}>
        Clientes con estado Vencido — pendiente recoger equipo
      </div>
      {morosos.length === 0 ? (
        <div style={{ textAlign: "center", color: GC.ink4, padding: 40 }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>✅</div>
          No hay clientes morosos en esta zona.
        </div>
      ) : morosos.map(c => {
        const yaAsignada = recogidas.some(r => r.clienteId === c.id && r.estado === "Asignada");
        return (
          <div key={c.id} style={{ background: "#fff", border: "1px solid " + (yaAsignada ? "#bbf7d0" : "#fecaca"), borderLeft: "4px solid " + (yaAsignada ? "#22c55e" : "#ef4444"), borderRadius: 12, padding: "12px 16px", marginBottom: 10, display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
            <div style={{ flex: 1, minWidth: 160 }}>
              <div style={{ fontWeight: 700, color: GC.ink, fontSize: 14 }}>{c.nombre}</div>
              <div style={{ fontSize: 12, color: GC.ink3 }}>CC: {c.cedula}</div>
              {c.telefono && <div style={{ fontSize: 12, color: GC.info }}>📞 {c.telefono}</div>}
              {c.direccion && <div style={{ fontSize: 12, color: GC.ink3 }}>📍 {c.direccion}</div>}
            </div>
            <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
              {yaAsignada && <span style={{ fontSize: 11, color: GC.brand, fontWeight: 700, background: GC.brandLight, border: "1px solid #bbf7d0", borderRadius: 8, padding: "4px 10px" }}>✅ Asignada</span>}
              <Btn onClick={() => setModalRecogida(c)} style={{ fontSize: 12, padding: "7px 12px", background: yaAsignada ? "#64748b" : "#ef4444" }}>
                📦 {yaAsignada ? "Ver / reasignar" : "Asignar recogida"}
              </Btn>
            </div>
          </div>
        );
      })}

      {/* Historial recogidas */}
      {recogidas.length > 0 && (
        <div style={{ marginTop: 28 }}>
          <div style={{ fontSize: 12, color: GC.ink3, fontWeight: 700, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 10 }}>Historial de recogidas asignadas</div>
          {recogidas.map(r => (
            <div key={r.id} style={{ background: GC.bg2, border: "1px solid " + GC.border, borderRadius: 10, padding: "10px 14px", marginBottom: 8, display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
              <div>
                <div style={{ fontWeight: 700, fontSize: 13, color: GC.ink }}>{r.clienteNombre}</div>
                <div style={{ fontSize: 12, color: GC.ink3 }}>🔧 {r.tecnicoNombre} · 📅 {r.fecha}</div>
                <div style={{ fontSize: 12, color: GC.ink2 }}>📦 {r.descripcionEquipo}</div>
              </div>
              <button onClick={() => setShowActa(r)} style={{ background: "#eff6ff", color: GC.info, border: "1px solid #bfdbfe", borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
                🖨️ Acta
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Modal asignar recogida */}
      {modalRecogida && (
        <div style={{ position: "fixed", inset: 0, background: "#00000055", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setModalRecogida(null)}>
          <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "100%", maxWidth: 440, position: "relative" }}>
            <button onClick={() => setModalRecogida(null)} style={{ position: "absolute", top: 14, right: 14, background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            <h3 style={{ margin: "0 0 4px", color: GC.ink }}>📦 Asignar recogida de equipo</h3>
            <p style={{ margin: "0 0 16px", color: GC.ink3, fontSize: 13 }}>{modalRecogida.nombre} · {modalRecogida.direccion}</p>
            <Field label="Técnico asignado">
              <Sel value={formRecogida.tecnicoId} onChange={e => setFormRecogida({ ...formRecogida, tecnicoId: e.target.value })}>
                <option value="">— Seleccionar técnico —</option>
                {tecnicos.map(t => <option key={t.id} value={t.id}>{t.nombre}</option>)}
              </Sel>
            </Field>
            <Field label="Descripción del equipo a recoger">
              <Inp value={formRecogida.descripcionEquipo} onChange={e => setFormRecogida({ ...formRecogida, descripcionEquipo: e.target.value })} placeholder="Ej: Router marca TP-Link, caja decodificadora" />
            </Field>
            <Field label="Fecha de recogida">
              <Inp type="date" value={formRecogida.fecha} onChange={e => setFormRecogida({ ...formRecogida, fecha: e.target.value })} />
            </Field>
            <Field label="Observaciones (opcional)">
              <Inp value={formRecogida.observacion} onChange={e => setFormRecogida({ ...formRecogida, observacion: e.target.value })} placeholder="Ej: Cliente ausente en las mañanas" />
            </Field>
            <Btn onClick={guardarRecogida} style={{ width: "100%", padding: "12px 0", fontSize: 14 }}>✅ Asignar al técnico</Btn>
          </div>
        </div>
      )}

      {/* Modal acta de recogida */}
      {showActa && (
        <div style={{ position: "fixed", inset: 0, background: "#00000077", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setShowActa(null)}>
          <div style={{ background: "#fff", borderRadius: 16, maxWidth: 420, width: "100%", overflow: "hidden", boxShadow: "0 20px 60px #00000033" }}>
            <div style={{ display: "flex", gap: 8, padding: "14px 16px", borderBottom: "1px solid #e2e8f0" }}>
              <Btn onClick={() => window.print()} style={{ flex: 1, fontSize: 13 }}>🖨️ Imprimir</Btn>
              <button onClick={() => setShowActa(null)} style={{ background: GC.bg3, border: "none", borderRadius: 8, padding: "9px 14px", cursor: "pointer", fontWeight: 700, fontSize: 13, color: GC.ink3 }}>Cerrar</button>
            </div>
            <div id="acta-print" style={{ padding: "24px 28px", fontFamily: "monospace", fontSize: 13 }}>
              <div style={{ textAlign: "center", marginBottom: 16 }}>
                <div style={{ fontWeight: 800, fontSize: 15 }}>GC HOGAR.NET S.A.S</div>
                <div style={{ fontSize: 12 }}>ACTA DE RECOGIDA DE EQUIPO</div>
                <div style={{ fontSize: 12 }}>Fecha: {showActa.fecha}</div>
              </div>
              <div style={{ borderTop: "1px dashed #94a3b8", borderBottom: "1px dashed #94a3b8", padding: "10px 0", marginBottom: 12 }}>
                <div><strong>Cliente:</strong> {showActa.clienteNombre}</div>
                <div><strong>Cédula:</strong> {showActa.clienteCedula}</div>
                <div><strong>Dirección:</strong> {showActa.clienteDireccion}</div>
                {showActa.clienteTelefono && <div><strong>Teléfono:</strong> {showActa.clienteTelefono}</div>}
              </div>
              <div style={{ marginBottom: 12 }}>
                <div><strong>Técnico:</strong> {showActa.tecnicoNombre}</div>
                <div><strong>Equipo recogido:</strong> {showActa.descripcionEquipo}</div>
                {showActa.observacion && <div><strong>Observaciones:</strong> {showActa.observacion}</div>}
              </div>
              <div style={{ borderTop: "1px dashed #94a3b8", paddingTop: 12, fontSize: 12 }}>
                <div style={{ marginBottom: 20 }}>El cliente autoriza la recogida del equipo mencionado por incumplimiento de pago.</div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20, marginTop: 20 }}>
                  <div style={{ textAlign: "center" }}>
                    <div style={{ borderTop: "1px solid #0f172a", paddingTop: 6 }}>Firma cliente</div>
                  </div>
                  <div style={{ textAlign: "center" }}>
                    <div style={{ borderTop: "1px solid #0f172a", paddingTop: 6 }}>Firma técnico</div>
                  </div>
                </div>
              </div>
            </div>
            <style>{`@media print { body * { visibility: hidden; } #acta-print, #acta-print * { visibility: visible; } #acta-print { position: fixed; inset: 0; padding: 24px; } }`}</style>
          </div>
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// MÓDULO CAJA — Ingresos y Egresos
// ══════════════════════════════════════════════════════════════
function ModuloCaja({ usuario, esAdmin = false, facturas = [], nombreEmpresa = "GC HOGAR.NET SAS", zonas = [] }) {
  // Un secretario SIEMPRE queda fijo a su zona. Un admin sin zona ve todas combinadas.
  const zonaUsuario = usuario?.zonaId || null;
  const [movimientos, setMovimientos] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [errorCarga, setErrorCarga] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [nuevoMov, setNuevoMov] = useState({ tipo: "Ingreso", concepto: "", monto: "", fecha: fechaLocal(), observacion: "" });
  const [errMsg, setErrMsg] = useState("");
  const [filtroTipo, setFiltroTipo] = useState("todos");
  const [confirmDel, setConfirmDel] = useState(null);
  // Saldo base: ahora vive en la BD, por zona (tabla zonas.saldo_base) — ya no en localStorage,
  // que era compartido entre cualquier zona/computador y no reflejaba la caja real de cada oficina.
  const saldoBase = zonaUsuario
    ? (zonas.find(z => z.id === zonaUsuario)?.saldoBase || 0)
    : zonas.reduce((s, z) => s + (z.saldoBase || 0), 0); // admin sin zona: suma de todas
  const [editandoSaldoBase, setEditandoSaldoBase] = useState(false);
  const [saldoBaseInput, setSaldoBaseInput] = useState("");
  const [fechaInforme, setFechaInforme] = useState(fechaLocal());

  const guardarSaldoBase = async () => {
    const v = Number(saldoBaseInput);
    if (isNaN(v) || v < 0) return;
    try {
      if (zonaUsuario) {
        await db.actualizarSaldoBaseZona(zonaUsuario, v);
      } else if (zonas.length === 1) {
        await db.actualizarSaldoBaseZona(zonas[0].id, v);
      } else {
        // Admin viendo todas las zonas combinadas: no hay una sola zona a la que editar.
        setErrMsg("Selecciona una zona específica para editar su saldo base.");
        return;
      }
      setEditandoSaldoBase(false);
      window.location.reload(); // recarga simple para reflejar el nuevo saldo_base de zonas
    } catch (e) { setErrMsg("Error guardando saldo base: " + e.message); }
  };

  const generarInformeDiario = async () => {
    const cop = v => Number(v).toLocaleString("es-CO", { style: "currency", currency: "COP", minimumFractionDigits: 0 });
    const fechaLabel = new Date(fechaInforme + "T12:00:00").toLocaleDateString("es-CO", { day: "2-digit", month: "long", year: "numeric" });
    const ahora = new Date().toLocaleDateString("es-CO", { day: "2-digit", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" });

    // Ingresos del día = abonos de facturas del día (no anuladas) + movimientos ingreso del día
    let abonosDia = [];
    try { abonosDia = await db.getAbonosByFecha(fechaInforme); } catch {}
    const abonosDiaValidos = abonosDia.filter(a => {
      const f = facturas.find(x => x.id === a.facturaId);
      return !f || f.estado !== "Anulada";
    });
    const totalAbonosDia = abonosDiaValidos.reduce((s, a) => s + a.monto, 0);
    const movsDia = movimientos.filter(m => m.fecha === fechaInforme);
    const ingresosCajaDia = movsDia.filter(m => m.tipo === "Ingreso").reduce((s, m) => s + m.monto, 0);
    const egresosCajaDia = movsDia.filter(m => m.tipo === "Egreso").reduce((s, m) => s + m.monto, 0);
    const totalIngresosDia = totalAbonosDia + ingresosCajaDia;

    // Saldo anterior = todo lo acumulado ANTES de la fecha del informe
    const cobradoAntes = facturas
      .filter(f => f.estado !== "Anulada" && f.fechaPago && f.fechaPago < fechaInforme)
      .reduce((s, f) => s + ((f.monto - f.saldoPendiente - (f.descuento_pronto_pago || 0))), 0);
    const ingresosAntes = movimientos.filter(m => m.tipo === "Ingreso" && m.fecha < fechaInforme).reduce((s, m) => s + m.monto, 0);
    const egresosAntes = movimientos.filter(m => m.tipo === "Egreso" && m.fecha < fechaInforme).reduce((s, m) => s + m.monto, 0);
    const saldoAnterior = saldoBase + cobradoAntes + ingresosAntes - egresosAntes;
    const nuevoSaldo = saldoAnterior + totalIngresosDia - egresosCajaDia;

    const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Informe Diario</title>
    <style>
      @page { size: A4; margin: 25mm 20mm; }
      * { box-sizing: border-box; margin: 0; padding: 0; }
      body { font-family: Arial, sans-serif; font-size: 11pt; color: #111; background: #fff; }
      .header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 28px; border-bottom: 3px solid #111; padding-bottom: 14px; }
      .header h1 { font-size: 16pt; font-weight: 900; letter-spacing: 1px; text-align: right; }
      .empresa-name { font-size: 12pt; font-weight: 700; }
      .empresa-nit { font-size: 9pt; color: #555; margin-top: 3px; }
      .params { border: 1px solid #ccc; border-radius: 6px; padding: 12px 16px; margin-bottom: 24px; display: flex; gap: 40px; flex-wrap: wrap; font-size: 10pt; }
      .params span { color: #555; }
      .params strong { color: #111; }
      .main-box { border: 1.5px solid #bbb; border-radius: 8px; padding: 0; margin-bottom: 24px; overflow: hidden; }
      .main-box-title { background: #f3f4f6; padding: 10px 18px; font-weight: 700; font-size: 10.5pt; text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1.5px solid #bbb; }
      .main-box-body { padding: 18px 20px; }
      .row { display: flex; justify-content: space-between; align-items: center; padding: 8px 0; font-size: 11pt; border-bottom: 1px solid #f0f0f0; }
      .row:last-child { border-bottom: none; }
      .row .label { color: #333; }
      .row .val { font-weight: 700; }
      .row.ing .val { color: #16a34a; }
      .row.egr .val { color: #dc2626; }
      .row.ant { background: #f8fafc; margin: 0 -20px; padding: 10px 20px; }
      .divider { border: none; border-top: 2px solid #111; margin: 8px 0; }
      .row.total { padding: 12px 0 4px; }
      .row.total .label { font-size: 13pt; font-weight: 900; }
      .row.total .val { font-size: 18pt; font-weight: 900; color: #15803d; }
      .footer { margin-top: 40px; display: flex; justify-content: space-between; font-size: 9pt; color: #777; border-top: 1px solid #ddd; padding-top: 10px; }
      .firma { margin-top: 50px; display: flex; justify-content: space-around; }
      .firma-linea { text-align: center; }
      .firma-linea div:first-child { border-top: 1px solid #111; width: 180px; padding-top: 6px; font-size: 9pt; }
      .btn-print { display: block; margin: 24px auto; padding: 10px 32px; background: #1d4ed8; color: #fff; border: none; border-radius: 6px; font-size: 13px; font-weight: 700; cursor: pointer; }
      @media print { .no-print { display: none !important; } }
    </style></head><body>

    <div class="header">
      <div>
        <div class="empresa-name">${nombreEmpresa.toUpperCase()}</div>
        <div class="empresa-nit">NIT: 900.007.541-8</div>
      </div>
      <h1>INFORME DIARIO<br/>DE GERENCIA</h1>
    </div>

    <div class="params">
      <div><span>Fecha del informe: </span><strong>${fechaLabel}</strong></div>
      <div><span>Fecha de generación: </span><strong>${ahora}</strong></div>
    </div>

    <div class="main-box">
      <div class="main-box-title">📊 Resumen del Día — ${fechaLabel}</div>
      <div class="main-box-body">
        <div class="row ant">
          <span class="label">Saldo Anterior</span>
          <span class="val">${cop(saldoAnterior)}</span>
        </div>
        <div class="row ing">
          <span class="label">INGRESOS</span>
          <span class="val">+ ${cop(totalIngresosDia)}</span>
        </div>
        <div class="row egr">
          <span class="label">EGRESOS</span>
          <span class="val">− ${cop(egresosCajaDia)}</span>
        </div>
        <hr class="divider"/>
        <div class="row total">
          <span class="label">Nuevo Saldo</span>
          <span class="val">${cop(nuevoSaldo)}</span>
        </div>
      </div>
    </div>

    <div class="firma">
      <div class="firma-linea">
        <div>Elaborado por</div>
      </div>
      <div class="firma-linea">
        <div>Revisado por</div>
      </div>
    </div>

    <div class="footer">
      <span>${nombreEmpresa}</span>
      <span>Generado: ${ahora}</span>
    </div>

    <button class="btn-print no-print" onclick="window.print()">🖨️ Imprimir informe</button>
    </body></html>`;

    const w = window.open("", "_blank", "width=900,height=700");
    w.document.write(html);
    w.document.close();
  };

  useEffect(() => {
    // zonaUsuario === null para admin sin zona fija → trae todas (sin filtro). Secretario: solo su zona.
    db.getMovimientosCaja(zonaUsuario)
      .then(data => { setMovimientos(data); setErrorCarga(false); })
      .catch(e => { console.error("Error cargando caja:", e); setErrorCarga(true); })
      .finally(() => setCargando(false));
  }, [zonaUsuario]);

  // Total histórico cobrado en facturas (todos los abonos, todos los meses) — necesario para
  // que el Saldo total refleje la plata REAL disponible, no solo los movimientos manuales.
  const [cobradoFacturasHistorico, setCobradoFacturasHistorico] = useState(null);
  useEffect(() => {
    db.getTotalCobradoGlobal(zonaUsuario).then(setCobradoFacturasHistorico).catch(() => setCobradoFacturasHistorico(0));
  }, [zonaUsuario]);

  const totalIngresos = movimientos.filter(m => m.tipo === "Ingreso").reduce((s, m) => s + m.monto, 0);
  const totalEgresos = movimientos.filter(m => m.tipo === "Egreso").reduce((s, m) => s + m.monto, 0);
  // Saldo real disponible = base + TODO lo cobrado en facturas históricamente + ingresos manuales − egresos manuales.
  // Si alguien registra un egreso por esa plata, este número baja de inmediato — así tu jefe siempre
  // puede ver cuánto puede retirar de la oficina, sin sumar nada a mano.
  const saldo = saldoBase + (cobradoFacturasHistorico||0) + totalIngresos - totalEgresos;

  const guardar = async () => {
    setErrMsg("");
    if (!nuevoMov.concepto.trim()) { setErrMsg("Ingresa un concepto."); return; }
    const monto = Number(nuevoMov.monto);
    if (!monto || monto <= 0) { setErrMsg("Ingresa un monto válido."); return; }
    // Un secretario siempre registra en su propia zona. Un admin viendo "todas" debe elegir una zona específica.
    const zonaParaGuardar = zonaUsuario || nuevoMov.zonaId;
    if (!zonaParaGuardar) { setErrMsg("Selecciona la zona a la que pertenece este movimiento."); return; }
    try {
      const guardado = await db.crearMovimientoCaja({ ...nuevoMov, monto, registradoPor: usuario.id, zonaId: zonaParaGuardar });
      setMovimientos(prev => [guardado, ...prev]);
      setNuevoMov({ tipo: "Ingreso", concepto: "", monto: "", fecha: fechaLocal(), observacion: "", zonaId: "" });
      setShowForm(false);
    } catch(e) { setErrMsg("Error: " + e.message); }
  };

  const eliminar = async (id) => {
    try { await db.deleteMovimientoCaja(id); setMovimientos(prev => prev.filter(m => m.id !== id)); setConfirmDel(null); }
    catch(e) { alert("Error: " + e.message); }
  };

  const filtrados = filtroTipo === "todos" ? movimientos : movimientos.filter(m => m.tipo === filtroTipo);

  return (
    <div>
      {/* Saldo base — solo admin puede editar */}
      <div style={{ background: GC.bg2, border: "1px solid " + GC.border, borderRadius: 12, padding: "12px 16px", marginBottom: 14, display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
        <div>
          <div style={{ fontSize: 11, color: GC.ink3, textTransform: "uppercase", letterSpacing: 0.8 }}>💵 Saldo base de apertura</div>
          {editandoSaldoBase ? (
            <div style={{ display: "flex", gap: 8, marginTop: 6, alignItems: "center" }}>
              <Inp type="number" value={saldoBaseInput} onChange={e => setSaldoBaseInput(e.target.value)} placeholder="Ej: 50000" style={{ width: 140 }} autoFocus />
              <Btn onClick={guardarSaldoBase} style={{ fontSize: 12, padding: "7px 12px" }}>✅ Guardar</Btn>
              <Btn variant="ghost" onClick={() => setEditandoSaldoBase(false)} style={{ fontSize: 12, padding: "7px 12px" }}>Cancelar</Btn>
            </div>
          ) : (
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 4 }}>
              <span style={{ fontWeight: 800, fontSize: 18, color: GC.ink }}>{formatCOP(saldoBase)}</span>
              {esAdmin && (
                <button onClick={() => { setSaldoBaseInput(String(saldoBase)); setEditandoSaldoBase(true); }}
                  style={{ background: GC.bg3, border: "1px solid " + GC.border, borderRadius: 7, padding: "4px 10px", cursor: "pointer", fontSize: 12, color: GC.ink2 }}>
                  ✏️ Editar
                </button>
              )}
            </div>
          )}
        </div>
        <div style={{ flex: 1 }} />
        <div style={{ fontSize: 12, color: GC.ink3, textAlign: "right" }}>
          <div>Saldo base es el dinero con que inicia la caja cada día.</div>
          {esAdmin && <div style={{ color: GC.brand, fontWeight: 600 }}>Solo el administrador puede modificarlo.</div>}
        </div>
      </div>

      {/* Resumen */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px,1fr))", gap: 10, marginBottom: 18 }}>
        {[
          ["💵 Saldo base", formatCOP(saldoBase), "#64748b"],
          ["🧾 Cobrado en facturas", formatCOP(cobradoFacturasHistorico||0), "#0891b2"],
          ["💚 Ingresos", formatCOP(totalIngresos), "#22c55e"],
          ["🔴 Egresos", formatCOP(totalEgresos), "#ef4444"],
          ["💼 Saldo total (disponible)", formatCOP(saldo), saldo >= 0 ? "#0ea5e9" : "#ef4444"],
        ].map(([label, val, color]) => (
          <div key={label} style={{ background: "#fff", border: "1px solid " + color + "33", borderTop: "3px solid " + color, borderRadius: 12, padding: "14px 16px" }}>
            <div style={{ fontSize: 11, color: GC.ink3, marginBottom: 4 }}>{label}</div>
            <div style={{ fontWeight: 800, color, fontSize: 15 }}>{val}</div>
          </div>
        ))}
      </div>

      {/* Barra de acciones */}
      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        <Sel value={filtroTipo} onChange={e => setFiltroTipo(e.target.value)} style={{ width: "auto", minWidth: 130 }}>
          <option value="todos">Todos</option>
          <option value="Ingreso">Solo ingresos</option>
          <option value="Egreso">Solo egresos</option>
        </Sel>
        <div style={{ flex: 1 }} />
        {/* Informe diario */}
        <div style={{ display: "flex", alignItems: "center", gap: 6, background: GC.bg2, border: "1px solid " + GC.border, borderRadius: 8, padding: "4px 10px" }}>
          <span style={{ fontSize: 12, color: GC.ink3, whiteSpace: "nowrap" }}>📊 Informe:</span>
          <Inp type="date" value={fechaInforme} onChange={e => setFechaInforme(e.target.value)} style={{ width: 140, padding: "5px 8px", fontSize: 12 }} />
          <button onClick={generarInformeDiario}
            style={{ background: GC.ink, color: "#fff", border: "none", borderRadius: 7, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700, whiteSpace: "nowrap" }}>
            🖨️ Generar
          </button>
        </div>
        <button onClick={() => { setNuevoMov({ tipo: "Ingreso", concepto: "", monto: "", fecha: fechaLocal(), observacion: "" }); setShowForm(true); setErrMsg(""); }}
          style={{ background: GC.brandLight, color: GC.brand, border: "1px solid #bbf7d0", borderRadius: 8, padding: "8px 14px", cursor: "pointer", fontSize: 13, fontWeight: 700 }}>
          💚 + Ingreso
        </button>
        <button onClick={() => { setNuevoMov({ tipo: "Egreso", concepto: "", monto: "", fecha: fechaLocal(), observacion: "" }); setShowForm(true); setErrMsg(""); }}
          style={{ background: "#fef2f2", color: "#dc2626", border: "1px solid #fecaca", borderRadius: 8, padding: "8px 14px", cursor: "pointer", fontSize: 13, fontWeight: 700 }}>
          🔴 + Egreso
        </button>
      </div>

      {/* Modal nuevo movimiento */}
      {showForm && (
        <div style={{ position: "fixed", inset: 0, background: "#00000066", zIndex: 9000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setShowForm(false)}>
          <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "100%", maxWidth: 420, position: "relative" }}>
            <button onClick={() => setShowForm(false)} style={{ position: "absolute", top: 14, right: 14, background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            <h3 style={{ margin: "0 0 16px", color: nuevoMov.tipo === "Ingreso" ? "#16a34a" : "#dc2626", fontSize: 16 }}>
              {nuevoMov.tipo === "Ingreso" ? "💚 Registrar Ingreso" : "🔴 Registrar Egreso"}
            </h3>
            <Field label="Tipo">
              <Sel value={nuevoMov.tipo} onChange={e => setNuevoMov({ ...nuevoMov, tipo: e.target.value })}>
                <option value="Ingreso">💚 Ingreso</option>
                <option value="Egreso">🔴 Egreso</option>
              </Sel>
            </Field>
            <Field label="Concepto / Descripción">
              <Inp value={nuevoMov.concepto} onChange={e => setNuevoMov({ ...nuevoMov, concepto: e.target.value })} placeholder="Ej: Pago cliente zona norte, Compra cable..." />
            </Field>
            <Field label="Monto (COP)">
              <Inp type="number" value={nuevoMov.monto} onChange={e => setNuevoMov({ ...nuevoMov, monto: e.target.value })} placeholder="Ej: 150000" />
            </Field>
            <Field label="Fecha">
              <Inp type="date" value={nuevoMov.fecha} onChange={e => setNuevoMov({ ...nuevoMov, fecha: e.target.value })} />
            </Field>
            <Field label="Observación (opcional)">
              <Inp value={nuevoMov.observacion} onChange={e => setNuevoMov({ ...nuevoMov, observacion: e.target.value })} placeholder="Detalle adicional..." />
            </Field>
            {errMsg && <div style={{ color: GC.danger, fontSize: 13, marginBottom: 10 }}>⚠️ {errMsg}</div>}
            <div style={{ display: "flex", gap: 8 }}>
              <Btn onClick={guardar} variant={nuevoMov.tipo === "Ingreso" ? "success" : "danger"} style={{ flex: 1 }}>✅ Guardar</Btn>
              <Btn variant="ghost" onClick={() => setShowForm(false)}>Cancelar</Btn>
            </div>
          </div>
        </div>
      )}

      {/* Lista movimientos */}
      {cargando ? (
        <div style={{ textAlign: "center", color: GC.ink4, padding: 40 }}>Cargando...</div>
      ) : filtrados.length === 0 ? (
        <div style={{ textAlign: "center", color: GC.ink4, padding: 40 }}>
          <div style={{ fontSize: 36, marginBottom: 8 }}>💼</div>
          <div>No hay movimientos registrados.</div>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {filtrados.map(m => (
            <div key={m.id} style={{ background: "#fff", border: "1px solid " + (m.tipo === "Ingreso" ? "#bbf7d0" : "#fecaca"), borderLeft: "4px solid " + (m.tipo === "Ingreso" ? "#22c55e" : "#ef4444"), borderRadius: 12, padding: "12px 16px", display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
              <div style={{ flex: 1, minWidth: 160 }}>
                <div style={{ fontWeight: 700, color: GC.ink, fontSize: 14 }}>{m.concepto}</div>
                <div style={{ fontSize: 12, color: GC.ink3 }}>📅 {m.fecha} {m.observacion ? "· " + m.observacion : ""}</div>
              </div>
              <div style={{ fontWeight: 800, fontSize: 16, color: m.tipo === "Ingreso" ? "#16a34a" : "#dc2626" }}>
                {m.tipo === "Ingreso" ? "+" : "-"}{formatCOP(m.monto)}
              </div>
              <span style={{ background: m.tipo === "Ingreso" ? "#f0fdf4" : "#fef2f2", color: m.tipo === "Ingreso" ? "#16a34a" : "#dc2626", border: "1px solid " + (m.tipo === "Ingreso" ? "#bbf7d0" : "#fecaca"), borderRadius: 8, padding: "3px 10px", fontSize: 12, fontWeight: 700 }}>{m.tipo}</span>
              <button onClick={() => setConfirmDel(m)} style={{ background: "#fef2f2", color: GC.danger, border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>🗑️</button>
            </div>
          ))}
        </div>
      )}

      {confirmDel && (
        <ModalConfirm
          titulo="¿Eliminar movimiento?"
          mensaje={`Se eliminará "${confirmDel.concepto}" (${formatCOP(confirmDel.monto)}). Esta acción no se puede deshacer.`}
          onCancel={() => setConfirmDel(null)}
          onConfirm={() => eliminar(confirmDel.id)}
        />
      )}

      {/* SQL — solo visible si hay error de conexión con la tabla */}
      {errorCarga && (
        <div style={{ marginTop: 24, background: GC.bg2, border: "1px solid " + GC.border, borderRadius: 10, padding: "14px 16px" }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: GC.ink2, marginBottom: 8 }}>⚙️ Si ves errores, ejecuta este SQL en Supabase / SQL Editor:</div>
        <pre style={{ background: GC.ink, color: GC.brand, borderRadius: 8, padding: "10px 14px", fontSize: 11, margin: 0, overflowX: "auto", lineHeight: 1.6 }}>{`CREATE TABLE IF NOT EXISTS public.caja_movimientos (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  tipo text NOT NULL CHECK (tipo IN ('Ingreso','Egreso')),
  concepto text NOT NULL,
  monto numeric NOT NULL,
  fecha date NOT NULL DEFAULT CURRENT_DATE,
  registrado_por text DEFAULT NULL,
  observacion text DEFAULT '',
  created_at timestamptz DEFAULT now()
);
ALTER TABLE public.caja_movimientos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "allow_all" ON public.caja_movimientos FOR ALL USING (true);`}</pre>
        <button onClick={() => {
          const sql = `CREATE TABLE IF NOT EXISTS public.caja_movimientos (\n  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,\n  tipo text NOT NULL CHECK (tipo IN ('Ingreso','Egreso')),\n  concepto text NOT NULL,\n  monto numeric NOT NULL,\n  fecha date NOT NULL DEFAULT CURRENT_DATE,\n  registrado_por text DEFAULT NULL,\n  observacion text DEFAULT '',\n  created_at timestamptz DEFAULT now()\n);\nALTER TABLE public.caja_movimientos ENABLE ROW LEVEL SECURITY;\nCREATE POLICY "allow_all" ON public.caja_movimientos FOR ALL USING (true);`;
          navigator.clipboard.writeText(sql).then(() => alert("✅ SQL copiado al portapapeles")).catch(() => alert("Copia el SQL manualmente del recuadro de arriba"));
        }} style={{ marginTop: 10, background: GC.info, color: "#fff", border: "none", borderRadius: 8, padding: "7px 14px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
          📋 Copiar SQL
        </button>
      </div>
      )}
    </div>
  );
}

function TabPerfiles({ perfilesPago, setPerfilesPago, usuarios }) {
  const [editPerfil, setEditPerfil] = useState(null);
  const [showFormPerfil, setShowFormPerfil] = useState(false);
  const [confirmPerfil, setConfirmPerfil] = useState(null);
  const emptyPerfil = { id: "", nombre: "", diaInicio: 1, diaFin: 5, diaCorte: 20, descripcion: "", activo: true };
  const savePerfil = async (p) => {
    try {
      const guardado = await db.upsertPerfilPago(p);
      setPerfilesPago(prev => prev.find(x => x.id === guardado.id) ? prev.map(x => x.id === guardado.id ? guardado : x) : [...prev, guardado]);
      setShowFormPerfil(false); setEditPerfil(null);
    } catch (err) { alert("Error: " + err.message); }
  };
  const deletePerfil = async (id) => {
    try { await db.deletePerfilPago(id); setPerfilesPago(p => p.filter(x => x.id !== id)); }
    catch (err) { alert("Error: " + err.message); }
  };
  const togglePerfil = async (id) => {
    const p = perfilesPago.find(x => x.id === id);
    if (!p) return;
    try { await db.togglePerfilPago(id, !p.activo); setPerfilesPago(prev => prev.map(x => x.id === id ? { ...x, activo: !x.activo } : x)); }
    catch (err) { alert("Error: " + err.message); }
  };
  const clientesPorPerfil = (perfId) => usuarios.filter(u => u.rol === "cliente" && u.perfilPagoId === perfId).length;
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
        <span style={{ color: GC.ink2, fontSize: 14 }}>{perfilesPago.length} perfiles configurados</span>
        <Btn onClick={() => { setEditPerfil({ ...emptyPerfil }); setShowFormPerfil(true); }} style={{ fontSize: 13 }}>+ Nuevo perfil</Btn>
      </div>
      <div style={{ background: "#eff6ff", border: "1px solid #bfdbfe", borderLeft: "4px solid #0ea5e9", borderRadius: 10, padding: "10px 14px", marginBottom: 16, fontSize: 13, color: "#1e40af" }}>
        📅 Los perfiles de pago definen el rango de días del mes en que cada cliente debe pagar.
      </div>
      {showFormPerfil && editPerfil && (
        <div style={{ background: "#ffffff", border: "1px solid " + GC.border, borderRadius: 14, padding: 20, marginBottom: 16, boxShadow: "0 2px 8px #00000010" }}>
          <h3 style={{ color: GC.ink, marginTop: 0, marginBottom: 16, fontSize: 15 }}>{editPerfil.id ? "✏️ Editar perfil" : "📅 Nuevo perfil de pago"}</h3>
          <Field label="Nombre del perfil"><Inp value={editPerfil.nombre} onChange={e => setEditPerfil({ ...editPerfil, nombre: e.target.value })} placeholder="Ej: Quincena 1, Fin de mes..." /></Field>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "0 16px" }}>
            <Field label="Día inicio pago"><Inp type="number" min="1" max="28" value={editPerfil.diaInicio} onChange={e => setEditPerfil({ ...editPerfil, diaInicio: Number(e.target.value) })} /></Field>
            <Field label="Día límite pago"><Inp type="number" min="1" max="28" value={editPerfil.diaFin} onChange={e => setEditPerfil({ ...editPerfil, diaFin: Number(e.target.value) })} /></Field>
            <Field label="Día de corte">
              <Inp type="number" min="1" max="31" value={editPerfil.diaCorte || 20} onChange={e => setEditPerfil({ ...editPerfil, diaCorte: Number(e.target.value) })} />
              <div style={{ fontSize: 10, color: GC.ink3, marginTop: 3 }}>Dia en que se corta si no pagó</div>
            </Field>
          </div>
          <Field label="Descripción (opcional)"><Inp value={editPerfil.descripcion} onChange={e => setEditPerfil({ ...editPerfil, descripcion: e.target.value })} placeholder="Ej: Clientes zona norte" /></Field>
          <div style={{ display: "flex", gap: 8 }}>
            <Btn onClick={() => savePerfil(editPerfil)}>Guardar perfil</Btn>
            <Btn variant="ghost" onClick={() => { setShowFormPerfil(false); setEditPerfil(null); }}>Cancelar</Btn>
          </div>
        </div>
      )}
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {perfilesPago.length === 0 ? (
          <div style={{ textAlign: "center", color: GC.ink4, padding: 40 }}>
            <div style={{ fontSize: 36, marginBottom: 8 }}>📅</div>
            <div>No hay perfiles creados aún.</div>
          </div>
        ) : perfilesPago.map(p => (
          <div key={p.id} style={{ background: "#ffffff", border: "1px solid " + GC.border, borderLeft: "4px solid #0ea5e9", borderRadius: 12, padding: "14px 16px", opacity: p.activo ? 1 : 0.5 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, color: GC.ink, fontSize: 15 }}>📅 {p.nombre}</div>
                <div style={{ fontSize: 13, color: GC.info, fontWeight: 600, marginTop: 2 }}>Pago: días {p.diaInicio} al {p.diaFin} · Corte: día {p.diaCorte || 20}</div>
                {p.descripcion && <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>{p.descripcion}</div>}
                <div style={{ fontSize: 11, color: GC.ink4, marginTop: 4 }}>👥 {clientesPorPerfil(p.id)} clientes asignados</div>
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                <button onClick={() => togglePerfil(p.id)} style={{ background: p.activo ? "#f0fdf4" : "#f1f5f9", color: p.activo ? "#16a34a" : "#64748b", border: "none", borderRadius: 8, padding: "5px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>{p.activo ? "Activo" : "Inactivo"}</button>
                <button onClick={() => { setEditPerfil(p); setShowFormPerfil(true); }} style={{ background: GC.bg3, color: GC.ink2, border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>✏️</button>
                <button onClick={() => setConfirmPerfil(p)} style={{ background: GC.bg3, color: GC.danger, border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>🗑️</button>
              </div>
            </div>
          </div>
        ))}
      </div>
      {confirmPerfil && <ModalConfirm titulo="¿Eliminar perfil de pago?" mensaje={`Se eliminará el perfil "${confirmPerfil.nombre}". Los clientes asignados quedarán sin perfil.`} onCancel={() => setConfirmPerfil(null)} onConfirm={() => { deletePerfil(confirmPerfil.id); setConfirmPerfil(null); }} />}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// TAB TICKETS PARA ADMIN — ve todos los tickets de todas las zonas
// ══════════════════════════════════════════════════════════════
function TabTicketsAdmin({ tickets, setTickets, usuarios, ordenes, setOrdenes, sesion, zonas, planes, perfilesPago }) {
  const [ticketAbierto, setTicketAbierto] = useState(null);
  const [busqTicket, setBusqTicket] = useState("");
  const [modalOrden, setModalOrden] = useState(null);
  const [nuevaOrden, setNuevaOrden] = useState({ tipo: "Revisión / diagnóstico", descripcion: "", tecnicoId: "", fecha: fechaLocal(), hora: "08:00", otro: "", nuevaDireccionTraslado: "" });

  const pendientes = tickets.filter(t => t.estado === "Abierto").sort((a,b) => (b.prioridad === "alta" ? 1 : 0) - (a.prioridad === "alta" ? 1 : 0));
  const enProceso = tickets.filter(t => t.estado === "En proceso");
  const resueltos = tickets.filter(t => t.estado === "Resuelto").sort((a,b) => b.fechaCreacion - a.fechaCreacion);
  const tecnicos = usuarios.filter(u => u.rol === "tecnico" && u.activo);

  const enviarMsg = async (ticketId, texto, autor) => {
    try {
      const msg = await db.enviarMensaje(ticketId, autor, texto);
      await db.actualizarEstadoTicket(ticketId, "En proceso");
      setTickets(p => p.map(t => t.id === ticketId ? { ...t, mensajes: [...t.mensajes, msg], estado: "En proceso" } : t));
    } catch(err) { console.error("Error enviando mensaje:", err); }
  };

  const cambiarEstadoTicket = async (ticketId, estado) => {
    try { await db.actualizarEstadoTicket(ticketId, estado); setTickets(p => p.map(t => t.id === ticketId ? { ...t, estado } : t)); }
    catch(err) { console.error("Error cambiando estado ticket:", err); }
  };

  const crearOrden = async () => {
    if (!nuevaOrden.tecnicosIds || nuevaOrden.tecnicosIds.length === 0) return;
    const cliente = usuarios.find(u => u.id === modalOrden.clienteId);
    const ordenData = {
      ticketId: modalOrden.id, clienteId: modalOrden.clienteId,
      clienteNombre: modalOrden.clienteNombre, secretarioId: sesion.id,
      tecnicosIds: nuevaOrden.tecnicosIds,
      tecnicoId: nuevaOrden.tecnicosIds[0] || null,
      tipo: nuevaOrden.tipo === "Otro" ? (nuevaOrden.otro || "Otro") : nuevaOrden.tipo,
      descripcion: nuevaOrden.descripcion,
      direccion: cliente?.direccion || "Sin dirección",
      telefonoCliente: cliente?.telefono || null,
      fecha: nuevaOrden.fecha, hora: nuevaOrden.hora,
      estado: "Pendiente", prioridad: modalOrden.prioridad,
      notas: [], zonaId: cliente?.zonaId || null
    };
    try {
      const orden = await db.crearOrden(ordenData);
      setOrdenes(p => [...p, orden]);
      await db.actualizarEstadoTicket(modalOrden.id, "En proceso");
      await db.actualizarOrdenIdTicket(modalOrden.id, orden.id);
      setTickets(p => p.map(t => t.id === modalOrden.id ? { ...t, estado: "En proceso", ordenId: orden.id } : t));
      setModalOrden(null);
      setNuevaOrden({ tipo: "Revisión / diagnóstico", descripcion: "", tecnicosIds: [], fecha: fechaLocal(), hora: "08:00", otro: "", nuevaDireccionTraslado: "" });
    } catch(err) { console.error("Error creando orden:", err); }
  };

  if (ticketAbierto) {
    const t = tickets.find(x => x.id === ticketAbierto);
    if (!t) { setTicketAbierto(null); return null; }
    return (
      <div style={{ maxWidth: 700, margin: "0 auto" }}>
        <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 12, flexWrap: "wrap" }}>
          <button onClick={() => setTicketAbierto(null)} style={{ background: "transparent", border: "none", color: GC.info, cursor: "pointer", fontSize: 14, padding: 0 }}>← Tickets</button>
          <div style={{ flex: 1 }} />
          <Sel style={{ width: "auto" }} value={t.estado} onChange={e => cambiarEstadoTicket(t.id, e.target.value)}>
            <option>Abierto</option><option>En proceso</option><option>Resuelto</option>
          </Sel>
          {!t.ordenId && <Btn onClick={() => { setModalOrden(t); setTicketAbierto(null); }} style={{ fontSize: 13, padding: "7px 14px" }}>🔧 Crear orden</Btn>}
        </div>
        <div style={{ background: "#ffffff", border: "1px solid " + GC.border, borderRadius: 14, overflow: "hidden", height: 500 }}>
          <ChatTicket ticket={t} onSend={enviarMsg} autorActual={sesion.id} nombreActual={sesion.nombre} usuarios={usuarios} />
        </div>
      </div>
    );
  }

  const q = busqTicket.toLowerCase().trim();
  const filtrar = lista => !q ? lista : lista.filter(t => {
    const cliente = usuarios.find(u => u.id === t.clienteId);
    return (t.id && t.id.toLowerCase().includes(q)) || (cliente?.cedula && norm(cliente.cedula).includes(q)) || (t.clienteNombre && norm(t.clienteNombre).includes(q));
  });

  const TicketCard = ({ t }) => {
    const ult = t.mensajes[t.mensajes.length - 1];
    const zona = zonas.find(z => z.id === usuarios.find(u => u.id === t.clienteId)?.zonaId);
    return (
      <div onClick={() => setTicketAbierto(t.id)} style={{ background: "#fff", border: "1px solid " + (t.prioridad === "alta" ? "#8b5cf644" : "#e2e8f0"), borderLeft: "4px solid " + (t.prioridad === "alta" ? "#8b5cf6" : TICKET_COLOR[t.estado]), borderRadius: 12, padding: "11px 14px", cursor: "pointer", marginBottom: 8 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          <span>{ALL_OPCIONES.find(p => p.id === t.tipo)?.emoji || "🔧"}</span>
          <span style={{ fontWeight: 700, color: GC.ink, flex: 1, fontSize: 14 }}>{t.titulo}</span>
          {zona && <span style={{ fontSize: 11, color: zona.color, fontWeight: 700, background: zona.color + "22", borderRadius: 6, padding: "1px 7px" }}>📍 {zona.nombre}</span>}
          {t.prioridad === "alta" && <Badge text="🏢 PRIORIDAD" color="#8b5cf6" />}
          <Badge text={t.estado} color={TICKET_COLOR[t.estado]} />
        </div>
        <div style={{ fontSize: 12, color: GC.ink3, marginTop: 4 }}>{t.clienteNombre} · {formatTime(t.fechaCreacion)}</div>
        <div style={{ fontSize: 12, color: GC.ink2, marginTop: 3 }}>{ult?.texto?.slice(0,60)}{(ult?.texto?.length || 0) > 60 ? "..." : ""}</div>
      </div>
    );
  };

  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 16, alignItems: "center" }}>
        <Inp placeholder="🔍 Buscar por cliente, cédula o N° ticket..." value={busqTicket} onChange={e => setBusqTicket(e.target.value)} style={{ flex: 1 }} />
        {busqTicket && <button onClick={() => setBusqTicket("")} style={{ background: GC.bg3, color: GC.ink3, border: "none", borderRadius: 8, padding: "9px 12px", cursor: "pointer", fontSize: 13 }}>✕</button>}
      </div>
      {[
        { lista: filtrar(pendientes), titulo: "🔴 Abiertos", color: GC.danger },
        { lista: filtrar(enProceso), titulo: "🔵 En proceso", color: GC.info },
        { lista: filtrar(resueltos), titulo: `✅ Resueltos (${resueltos.length})`, color: GC.brand },
      ].map(({ lista, titulo, color }) => (
        <div key={titulo} style={{ marginBottom: 20 }}>
          <div style={{ color: GC.ink3, fontSize: 12, textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 8, display: "flex", alignItems: "center", gap: 6 }}>
            {titulo}
            {lista.length > 0 && <span style={{ background: color + "22", color, borderRadius: 20, padding: "1px 8px", fontSize: 11, fontWeight: 800 }}>{lista.length}</span>}
          </div>
          {lista.length === 0 ? <div style={{ color: GC.ink4, fontSize: 13, padding: "6px 0" }}>Sin tickets</div> : lista.map(t => <TicketCard key={t.id} t={t} />)}
        </div>
      ))}

      {/* Modal crear orden */}
      {modalOrden && (
        <div style={{ position: "fixed", inset: 0, background: "#00000055", zIndex: 100, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setModalOrden(null)}>
          <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "100%", maxWidth: 460, maxHeight: "90vh", overflowY: "auto", position: "relative" }}>
            <button onClick={() => setModalOrden(null)} style={{ position: "absolute", top: 14, right: 14, background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            <h3 style={{ color: GC.ink, margin: "0 0 16px", fontSize: 16 }}>🔧 Crear orden de trabajo</h3>
            <Field label="Tipo de orden">
              <Sel value={nuevaOrden.tipo} onChange={e => setNuevaOrden({ ...nuevaOrden, tipo: e.target.value })}>
                {TIPOS_ORDEN.map(t => <option key={t}>{t}</option>)}
              </Sel>
            </Field>
            {nuevaOrden.tipo === "Otro" && <Field label="Especificar"><Inp value={nuevaOrden.otro} onChange={e => setNuevaOrden({ ...nuevaOrden, otro: e.target.value })} /></Field>}
            <Field label="Descripción"><textarea value={nuevaOrden.descripcion} onChange={e => setNuevaOrden({ ...nuevaOrden, descripcion: e.target.value })} style={{ background: GC.bg2, border: "1px solid " + GC.border2, borderRadius: 8, color: GC.ink, padding: "9px 12px", fontSize: 14, width: "100%", boxSizing: "border-box", outline: "none", minHeight: 70, resize: "vertical" }} /></Field>
            <Field label="Asignar técnico">
              <Sel value={nuevaOrden.tecnicoId} onChange={e => setNuevaOrden({ ...nuevaOrden, tecnicoId: e.target.value })}>
                <option value="">— Seleccionar técnico —</option>
                {tecnicos.map(t => <option key={t.id} value={t.id}>{t.nombre} {zonas.find(z=>z.id===t.zonaId) ? `(${zonas.find(z=>z.id===t.zonaId).nombre})` : ""}</option>)}
              </Sel>
            </Field>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 12px" }}>
              <Field label="Fecha"><Inp type="date" value={nuevaOrden.fecha} onChange={e => setNuevaOrden({ ...nuevaOrden, fecha: e.target.value })} /></Field>
              <Field label="Hora"><Inp type="time" value={nuevaOrden.hora} onChange={e => setNuevaOrden({ ...nuevaOrden, hora: e.target.value })} /></Field>
            </div>
            <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
              <Btn onClick={crearOrden} disabled={nuevaOrden.tecnicosIds.length === 0}>Crear orden</Btn>
              <Btn variant="ghost" onClick={() => setModalOrden(null)}>Cancelar</Btn>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// TAB SUPERUSUARIO — gestión exclusiva del superusuario
// ══════════════════════════════════════════════════════════════
function TabSuperusuario({ usuarios, setUsuarios, sesion, zonas = [], setZonas }) {
  const [editU, setEditU] = useState(null);
  const [confirm, setConfirm] = useState(null);
  const [msg, setMsg] = useState(null);
  const [wisproMsg, setWisproMsg] = useState(null);

  // Solo admins y el superusuario mismo son visibles aquí
  const admins = usuarios.filter(u => u.rol === "admin" || u.rol === "superusuario");

  const toggleActivo = async (u) => {
    if (u.rol === "superusuario") { setMsg({ ok: false, texto: "No puedes desactivar al superusuario." }); return; }
    try {
      await db.toggleUsuario(u.id, !u.activo);
      setUsuarios(p => p.map(x => x.id === u.id ? { ...x, activo: !x.activo } : x));
    } catch(e) { setMsg({ ok: false, texto: "Error: " + e.message }); }
  };

  const eliminarAdmin = async (id) => {
    try {
      await db.deleteUsuario(id);
      setUsuarios(p => p.filter(u => u.id !== id));
      setConfirm(null);
    } catch(e) { setMsg({ ok: false, texto: "Error: " + e.message }); }
  };

  const guardarAdmin = async () => {
    if (!editU.nombre.trim() || !editU.usuario.trim() || !editU.clave.trim()) {
      setMsg({ ok: false, texto: "Nombre, usuario y clave son obligatorios." }); return;
    }
    try {
      const guardado = await db.upsertUsuario(editU);
      setUsuarios(p => p.find(x => x.id === guardado.id) ? p.map(x => x.id === guardado.id ? guardado : x) : [...p, guardado]);
      setEditU(null);
      setMsg({ ok: true, texto: "✅ Administrador guardado correctamente." });
    } catch(e) { setMsg({ ok: false, texto: "Error: " + e.message }); }
  };

  const toggleWispro = async (zona) => {
    const nuevoEstado = !zona.wisproActivo;
    try {
      await db.toggleWisproZona(zona.id, nuevoEstado);
      if (setZonas) setZonas(prev => prev.map(z => z.id === zona.id ? { ...z, wisproActivo: nuevoEstado } : z));
      setWisproMsg({ ok: true, texto: `✅ Wispro ${nuevoEstado ? "activado" : "desactivado"} para zona ${zona.nombre}.` });
      setTimeout(() => setWisproMsg(null), 3000);
    } catch(e) { setWisproMsg({ ok: false, texto: "Error: " + e.message }); }
  };

  return (
    <div>
      {/* Banner superusuario */}
      <div style={{ background: "linear-gradient(135deg, #dc262622, #dc262608)", border: "1px solid #dc262633", borderLeft: "4px solid #dc2626", borderRadius: 12, padding: "14px 18px", marginBottom: 20, display: "flex", alignItems: "center", gap: 12 }}>
        <span style={{ fontSize: 28 }}>👑</span>
        <div>
          <div style={{ fontWeight: 800, color: "#dc2626", fontSize: 15 }}>Panel Superusuario</div>
          <div style={{ fontSize: 13, color: GC.ink3, marginTop: 2 }}>
            Desde aquí puedes gestionar los administradores del sistema. Solo existe un superusuario y no puede ser eliminado.
          </div>
        </div>
      </div>

      {/* Panel Control Wispro por Zonas */}
      <div style={{ background: "#fff", border: "1px solid #e2e8f0", borderRadius: 14, padding: 20, marginBottom: 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
          <span style={{ fontSize: 22 }}>📡</span>
          <div>
            <div style={{ fontWeight: 800, color: GC.ink, fontSize: 15 }}>Control de integración Wispro por zona</div>
            <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>Activa o desactiva los cortes y reconexiones automáticas con Wispro para cada zona.</div>
          </div>
        </div>
        {wisproMsg && (
          <div style={{ background: wisproMsg.ok ? "#f0fdf4" : "#fef2f2", border: "1px solid " + (wisproMsg.ok ? "#bbf7d0" : "#fecaca"), borderRadius: 8, padding: "8px 12px", marginBottom: 12, fontSize: 13, color: wisproMsg.ok ? "#16a34a" : "#dc2626" }}>
            {wisproMsg.texto}
          </div>
        )}
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {zonas.length === 0 && <div style={{ color: GC.ink3, fontSize: 13 }}>No hay zonas configuradas.</div>}
          {zonas.map(z => (
            <div key={z.id} style={{ display: "flex", alignItems: "center", gap: 14, padding: "12px 16px", borderRadius: 12, border: "1px solid " + (z.wisproActivo ? z.color + "44" : "#e2e8f0"), background: z.wisproActivo ? z.color + "0a" : "#f8fafc" }}>
              <span style={{ width: 12, height: 12, borderRadius: "50%", background: z.color, flexShrink: 0 }} />
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, color: GC.ink, fontSize: 14 }}>📍 {z.nombre}</div>
                <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>
                  {z.wisproActivo
                    ? "✅ Cortes y reconexiones activos — el sistema controla Wispro"
                    : "🔒 Integración desactivada — los botones de corte/reconexión están bloqueados"}
                </div>
              </div>
              <button
                onClick={() => toggleWispro(z)}
                style={{
                  background: z.wisproActivo ? "#dcfce7" : "#fee2e2",
                  color: z.wisproActivo ? "#16a34a" : "#dc2626",
                  border: "1px solid " + (z.wisproActivo ? "#bbf7d0" : "#fecaca"),
                  borderRadius: 10, padding: "8px 18px", cursor: "pointer",
                  fontSize: 13, fontWeight: 800, whiteSpace: "nowrap"
                }}
              >
                {z.wisproActivo ? "🟢 Activo" : "🔴 Inactivo"}
              </button>
            </div>
          ))}
        </div>
      </div>

      {msg && (
        <div style={{ background: msg.ok ? "#f0fdf4" : "#fef2f2", border: "1px solid " + (msg.ok ? "#bbf7d0" : "#fecaca"), borderRadius: 10, padding: "10px 14px", marginBottom: 14, fontSize: 13, color: msg.ok ? "#16a34a" : "#dc2626", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          {msg.texto}
          <button onClick={() => setMsg(null)} style={{ background: "none", border: "none", cursor: "pointer", color: GC.ink4, fontSize: 16 }}>×</button>
        </div>
      )}

      {/* Botón nuevo admin */}
      <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 14 }}>
        <Btn onClick={() => setEditU({ id: "", usuario: "", clave: "", rol: "admin", nombre: "", activo: true, zonaId: "", zonasIds: [], telefono: "", privilegios: [] })}>
          + Nuevo administrador
        </Btn>
      </div>

      {/* Form crear/editar admin */}
      {editU && (
        <div style={{ position: "fixed", inset: 0, background: "#00000066", zIndex: 9000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={e => e.target === e.currentTarget && setEditU(null)}>
          <div style={{ background: "#fff", borderRadius: 16, padding: 24, width: "100%", maxWidth: 440, position: "relative" }}>
            <button onClick={() => setEditU(null)} style={{ position: "absolute", top: 14, right: 14, background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
            <h3 style={{ margin: "0 0 16px", color: GC.ink, fontSize: 16 }}>{editU.id ? "✏️ Editar administrador" : "➕ Nuevo administrador"}</h3>
            <Field label="Nombre completo"><Inp value={editU.nombre} onChange={e => setEditU({ ...editU, nombre: e.target.value })} /></Field>
            <Field label="Usuario (login)"><Inp value={editU.usuario} onChange={e => setEditU({ ...editU, usuario: e.target.value })} /></Field>
            <Field label="Clave"><Inp type="text" value={editU.clave} onChange={e => setEditU({ ...editU, clave: e.target.value })} /></Field>
            <Field label="Teléfono (opcional)"><Inp value={editU.telefono || ""} onChange={e => setEditU({ ...editU, telefono: e.target.value })} /></Field>
            <Field label="Teléfono 2 (opcional)"><Inp value={editU.telefono2 || ""} onChange={e => setEditU({ ...editU, telefono2: e.target.value })} placeholder="Segundo número de contacto" /></Field>
            {editU.rol !== "superusuario" && zonas.length > 0 && (
              <Field label="Zonas asignadas (puede seleccionar varias)">
                <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 4 }}>
                  {zonas.filter(z => z.activa).map(z => {
                    const seleccionada = (editU.zonasIds || []).includes(z.id);
                    return (
                      <label key={z.id} style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer", padding: "6px 10px", borderRadius: 8, border: "1px solid " + (seleccionada ? z.color : "#e2e8f0"), background: seleccionada ? z.color + "15" : "#fff" }}>
                        <input type="checkbox" checked={seleccionada} onChange={() => {
                          const ids = editU.zonasIds || [];
                          setEditU({ ...editU, zonasIds: seleccionada ? ids.filter(id => id !== z.id) : [...ids, z.id] });
                        }} style={{ accentColor: z.color, width: 16, height: 16 }} />
                        <span style={{ width: 10, height: 10, borderRadius: "50%", background: z.color, flexShrink: 0 }} />
                        <span style={{ fontSize: 13, fontWeight: seleccionada ? 700 : 400, color: seleccionada ? z.color : "#0f172a" }}>{z.nombre}</span>
                      </label>
                    );
                  })}
                  {(editU.zonasIds || []).length === 0 && <div style={{ fontSize: 11, color: "#94a3b8" }}>Sin zonas asignadas</div>}
                </div>
              </Field>
            )}
            <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
              <Btn onClick={guardarAdmin} style={{ flex: 1 }}>Guardar</Btn>
              <Btn variant="ghost" onClick={() => setEditU(null)}>Cancelar</Btn>
            </div>
          </div>
        </div>
      )}

      {/* Lista admins */}
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {admins.map(u => (
          <div key={u.id} style={{ background: "#fff", border: "1px solid " + (u.rol === "superusuario" ? "#dc262633" : "#e2e8f0"), borderLeft: "4px solid " + (u.rol === "superusuario" ? "#dc2626" : "#8b5cf6"), borderRadius: 12, padding: "14px 16px", opacity: u.activo ? 1 : 0.5, display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
            <div style={{ flex: 1 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ fontSize: 18 }}>{u.rol === "superusuario" ? "👑" : "🛡️"}</span>
                <span style={{ fontWeight: 700, color: GC.ink, fontSize: 14 }}>{u.nombre}</span>
                <Badge text={u.rol === "superusuario" ? "Superusuario" : "Administrador"} color={u.rol === "superusuario" ? "#dc2626" : "#8b5cf6"} />
              </div>
              <div style={{ fontSize: 12, color: GC.ink3, marginTop: 4 }}>@{u.usuario} {u.telefono ? "· 📞 " + u.telefono : ""}{u.rol !== "superusuario" && (u.zonasIds || []).length > 0 ? " · " + (u.zonasIds || []).map(id => { const z = zonas.find(x => x.id === id); return z ? "📍 " + z.nombre : ""; }).filter(Boolean).join(", ") : ""}</div>
            </div>
            <div style={{ display: "flex", gap: 6 }}>
              {u.rol !== "superusuario" && (
                <>
                  <button onClick={() => toggleActivo(u)} style={{ background: u.activo ? "#f0fdf4" : "#f1f5f9", color: u.activo ? "#16a34a" : "#64748b", border: "none", borderRadius: 8, padding: "5px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>
                    {u.activo ? "Activo" : "Inactivo"}
                  </button>
                  <button onClick={() => setEditU({ ...u, privilegios: u.privilegios || [], zonasIds: u.zonasIds || [] })} style={{ background: GC.bg3, color: GC.ink2, border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>✏️</button>
                  <button onClick={() => setConfirm(u)} style={{ background: "#fef2f2", color: GC.danger, border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>🗑️</button>
                </>
              )}
              {u.rol === "superusuario" && u.id === sesion.id && (
                <button onClick={() => setEditU({ ...u })} style={{ background: GC.bg3, color: GC.ink2, border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>✏️ Editar mi cuenta</button>
              )}
            </div>
          </div>
        ))}
      </div>

      {confirm && (
        <ModalConfirm
          titulo="¿Eliminar administrador?"
          mensaje={`Se eliminará a "${confirm.nombre}" del sistema. Esta acción no se puede deshacer.`}
          onCancel={() => setConfirm(null)}
          onConfirm={() => eliminarAdmin(confirm.id)}
        />
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
//  ASIGNACIÓN MASIVA — Zona, Plan, Perfil de Pago
// ══════════════════════════════════════════════════════════════
function AsignacionMasiva({ usuarios, setUsuarios, zonas, planes, perfilesPago }) {
  const [filtroZona,    setFiltroZona]    = React.useState("");
  const [filtroPlan,    setFiltroPlan]    = React.useState("");
  const [filtroPerfil,  setFiltroPerfil]  = React.useState("");
  const [filtroEstado,  setFiltroEstado]  = React.useState("");
  const [busq,          setBusq]          = React.useState("");
  const [seleccionados, setSeleccionados] = React.useState(new Set());
  const [asigZonaId,    setAsigZonaId]    = React.useState("");
  const [asigPlanId,    setAsigPlanId]    = React.useState("");
  const [asigPerfilId,  setAsigPerfilId]  = React.useState("");
  const [aplicando,     setAplicando]     = React.useState(false);
  const [progreso,      setProgreso]      = React.useState(0);
  const [resultado,     setResultado]     = React.useState(null);
  const [confirmando,   setConfirmando]   = React.useState(false);

  const clientes = React.useMemo(() => usuarios.filter(u => u.rol === "cliente"), [usuarios]);

  const clientesFiltrados = React.useMemo(() => {
    const q = norm(busq);
    return clientes.filter(u => {
      if (filtroZona   && u.zonaId       !== filtroZona)   return false;
      if (filtroPlan   && u.planId       !== filtroPlan)   return false;
      if (filtroPerfil && u.perfilPagoId !== filtroPerfil) return false;
      if (filtroEstado && u.estado       !== filtroEstado) return false;
      if (q && !(
        norm(u.nombre).includes(q) ||
        norm(u.cedula).includes(q) ||
        norm(u.usuario).includes(q) ||
        norm(u.telefono).includes(q)
      )) return false;
      return true;
    });
  }, [clientes, filtroZona, filtroPlan, filtroPerfil, filtroEstado, busq]);

  const todosSeleccionados = clientesFiltrados.length > 0 && clientesFiltrados.every(u => seleccionados.has(u.id));
  const algunoSeleccionado = seleccionados.size > 0;
  const hayAlgoParaAsignar = asigZonaId || asigPlanId || asigPerfilId;

  const toggleTodos = () => {
    if (todosSeleccionados) {
      setSeleccionados(prev => { const n = new Set(prev); clientesFiltrados.forEach(u => n.delete(u.id)); return n; });
    } else {
      setSeleccionados(prev => { const n = new Set(prev); clientesFiltrados.forEach(u => n.add(u.id)); return n; });
    }
  };
  const toggleUno = (id) => setSeleccionados(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const limpiarFiltros = () => { setFiltroZona(""); setFiltroPlan(""); setFiltroPerfil(""); setFiltroEstado(""); setBusq(""); };
  const limpiarAsignacion = () => { setAsigZonaId(""); setAsigPlanId(""); setAsigPerfilId(""); };
  const limpiarSeleccion = () => setSeleccionados(new Set());

  const nombreZona   = id => zonas.find(z => z.id === id)?.nombre || id;
  const nombrePlan   = id => planes.find(p => p.id === id)?.nombre || id;
  const nombrePerfil = id => perfilesPago.find(p => p.id === id)?.nombre || id;

  const aplicar = async () => {
    if (!algunoSeleccionado || !hayAlgoParaAsignar) return;
    setAplicando(true); setProgreso(0); setResultado(null); setConfirmando(false);
    const ids = [...seleccionados];
    let ok = 0, err = 0;
    for (let i = 0; i < ids.length; i++) {
      const u = usuarios.find(x => x.id === ids[i]);
      if (!u) { err++; continue; }
      const patch = { ...u };
      if (asigZonaId)   patch.zonaId      = asigZonaId;
      if (asigPerfilId) patch.perfilPagoId = asigPerfilId;
      if (asigPlanId) {
        const plan = planes.find(p => p.id === asigPlanId);
        patch.planId = asigPlanId;
        if (plan) { patch.plan = plan.nombre; patch.monto = plan.precio; }
      }
      try {
        const guardado = await db.upsertUsuario(patch);
        setUsuarios(prev => prev.map(x => x.id === guardado.id ? guardado : x));
        ok++;
      } catch (e) { console.error("Error asignando a", u.nombre, e); err++; }
      setProgreso(Math.round(((i + 1) / ids.length) * 100));
    }
    setResultado({ ok, err });
    setAplicando(false);
    if (ok > 0) { limpiarSeleccion(); limpiarAsignacion(); }
  };

  const selStyle = (activo, activeColor, activeBg, activeBdr) => ({
    width: "100%", padding: "8px 10px", borderRadius: 8,
    border: "1px solid " + (activo ? activeColor : GC.border2),
    background: activo ? activeBg : GC.bg,
    color: GC.ink, fontSize: 13, fontFamily: "inherit",
  });

  const tagStyle = (color, bg) => ({
    display: "inline-block", background: bg, color: color,
    borderRadius: 6, padding: "2px 8px", fontSize: 11, fontWeight: 700,
  });

  return (
    <div style={{ maxWidth: 960 }}>
      <div style={{ marginBottom: 16 }}>
        <div style={{ fontSize: 13, color: GC.ink3 }}>
          Filtra clientes por zona, plan o perfil actual y asígnales nuevos valores de forma simultánea.
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 340px", gap: 16, alignItems: "start" }}>

        {/* ── COLUMNA IZQUIERDA: filtros + lista ── */}
        <div>
          {/* Filtros */}
          <div style={{ background: "#ffffff", border: "1px solid " + GC.border, borderRadius: 14, padding: "16px 20px", marginBottom: 14 }}>
            <div style={{ fontSize: 11, color: GC.ink2, textTransform: "uppercase", letterSpacing: 0.9, fontWeight: 700, marginBottom: 10 }}>🔍 Filtrar clientes</div>
            <input
              value={busq} onChange={e => setBusq(e.target.value)}
              placeholder="Nombre, cédula, usuario, teléfono…"
              style={{ width: "100%", boxSizing: "border-box", padding: "9px 12px", borderRadius: 8, fontSize: 14, border: "1px solid " + GC.border2, background: GC.bg, color: GC.ink, outline: "none", fontFamily: "inherit", marginBottom: 12 }}
            />
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px 12px" }}>
              <div>
                <div style={{ fontSize: 11, color: GC.ink3, marginBottom: 4 }}>📍 Zona actual</div>
                <select value={filtroZona} onChange={e => setFiltroZona(e.target.value)} style={selStyle(!!filtroZona, GC.brand, GC.brandLight, GC.brandMid)}>
                  <option value="">Todas las zonas</option>
                  {zonas.map(z => <option key={z.id} value={z.id}>{z.nombre}</option>)}
                </select>
              </div>
              <div>
                <div style={{ fontSize: 11, color: GC.ink3, marginBottom: 4 }}>📦 Plan actual</div>
                <select value={filtroPlan} onChange={e => setFiltroPlan(e.target.value)} style={selStyle(!!filtroPlan, GC.info, GC.infoBg, GC.infoBdr)}>
                  <option value="">Todos los planes</option>
                  {planes.map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
                </select>
              </div>
              <div>
                <div style={{ fontSize: 11, color: GC.ink3, marginBottom: 4 }}>📅 Perfil de pago actual</div>
                <select value={filtroPerfil} onChange={e => setFiltroPerfil(e.target.value)} style={selStyle(!!filtroPerfil, GC.purple, GC.purpleBg, GC.purpleBdr)}>
                  <option value="">Todos los perfiles</option>
                  {perfilesPago.map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
                </select>
              </div>
              <div>
                <div style={{ fontSize: 11, color: GC.ink3, marginBottom: 4 }}>🚦 Estado de pago</div>
                <select value={filtroEstado} onChange={e => setFiltroEstado(e.target.value)} style={selStyle(!!filtroEstado, GC.warning, GC.warningBg, GC.warningBdr)}>
                  <option value="">Todos los estados</option>
                  <option value="Al día">✅ Al día</option>
                  <option value="Pendiente">⚠️ Pendiente</option>
                  <option value="Vencido">🔴 Vencido</option>
                </select>
              </div>
            </div>
            {(filtroZona || filtroPlan || filtroPerfil || filtroEstado || busq) && (
              <button onClick={limpiarFiltros} style={{ marginTop: 10, background: "none", border: "none", color: GC.danger, fontSize: 12, cursor: "pointer", padding: 0, fontFamily: "inherit" }}>
                ✕ Limpiar filtros
              </button>
            )}
          </div>

          {/* Controles de selección */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8, padding: "0 4px" }}>
            <span style={{ fontSize: 13, color: GC.ink2, fontWeight: 600 }}>
              {clientesFiltrados.length} cliente{clientesFiltrados.length !== 1 ? "s" : ""}
              {seleccionados.size > 0 && <span style={{ marginLeft: 8, color: GC.brand, fontWeight: 800 }}>· {seleccionados.size} seleccionado{seleccionados.size !== 1 ? "s" : ""}</span>}
            </span>
            <div style={{ display: "flex", gap: 8 }}>
              {seleccionados.size > 0 && (
                <button onClick={limpiarSeleccion} style={{ background: "none", border: "none", color: GC.ink3, fontSize: 12, cursor: "pointer", fontFamily: "inherit" }}>Deseleccionar todo</button>
              )}
              {clientesFiltrados.length > 0 && (
                <button onClick={toggleTodos} style={{ background: todosSeleccionados ? GC.brandLight : GC.bg3, color: todosSeleccionados ? GC.brandText : GC.ink2, border: "1px solid " + (todosSeleccionados ? GC.brand : GC.border), borderRadius: 8, padding: "5px 12px", cursor: "pointer", fontSize: 12, fontWeight: 700, fontFamily: "inherit" }}>
                  {todosSeleccionados ? "✓ Todos seleccionados" : "Seleccionar todos"}
                </button>
              )}
            </div>
          </div>

          {/* Lista de clientes */}
          <div style={{ maxHeight: 460, overflowY: "auto", borderRadius: 12, border: "1px solid " + GC.border }}>
            {clientesFiltrados.length === 0 ? (
              <div style={{ padding: 32, textAlign: "center", color: GC.ink3, fontSize: 14 }}>😶 No hay clientes con esos filtros</div>
            ) : (
              clientesFiltrados.map((u, idx) => {
                const sel = seleccionados.has(u.id);
                const zona   = zonas.find(z => z.id === u.zonaId);
                const plan   = planes.find(p => p.id === u.planId);
                const perfil = perfilesPago.find(p => p.id === u.perfilPagoId);
                const eColor = ESTADO_COLOR[u.estado] || GC.ink3;
                const eBg    = { "Activo": GC.brandLight, "Al día": GC.brandLight, "DPP": GC.dangerBg, "DPS": GC.infoBg, "Cortesía": GC.purpleBg, Pendiente: GC.warningBg, Vencido: GC.dangerBg }[u.estado] || GC.bg3;
                return (
                  <div key={u.id} onClick={() => toggleUno(u.id)} style={{ display: "flex", alignItems: "center", gap: 12, padding: "10px 14px", background: sel ? GC.brandLight : idx % 2 === 0 ? "#ffffff" : GC.bg, borderBottom: "1px solid " + GC.border, cursor: "pointer" }}>
                    <div style={{ width: 20, height: 20, borderRadius: 5, flexShrink: 0, border: "2px solid " + (sel ? GC.brand : GC.border2), background: sel ? GC.brand : "#fff", display: "flex", alignItems: "center", justifyContent: "center" }}>
                      {sel && <span style={{ color: "#fff", fontSize: 13, lineHeight: 1 }}>✓</span>}
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontWeight: 700, color: GC.ink, fontSize: 13, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{u.nombre}</div>
                      <div style={{ display: "flex", gap: 5, marginTop: 3, flexWrap: "wrap" }}>
                        {zona   ? <span style={tagStyle(zona.color, zona.color + "22")}>📍 {zona.nombre}</span> : <span style={tagStyle(GC.ink4, GC.bg3)}>Sin zona</span>}
                        {plan   ? <span style={tagStyle(GC.info, GC.infoBg)}>📦 {plan.nombre}</span>         : <span style={tagStyle(GC.ink4, GC.bg3)}>Sin plan</span>}
                        {perfil ? <span style={tagStyle(GC.purple, GC.purpleBg)}>📅 {perfil.nombre}</span>   : <span style={tagStyle(GC.ink4, GC.bg3)}>Sin perfil</span>}
                      </div>
                    </div>
                    {u.estado && <span style={tagStyle(eColor, eBg)}>{u.estado}</span>}
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* ── COLUMNA DERECHA: panel de asignación ── */}
        <div style={{ position: "sticky", top: 80 }}>
          <div style={{ background: "#ffffff", border: "2px solid " + (algunoSeleccionado && hayAlgoParaAsignar ? GC.brand : GC.border), borderRadius: 14, padding: "16px 20px", marginBottom: 12 }}>
            <div style={{ fontSize: 11, color: GC.ink2, textTransform: "uppercase", letterSpacing: 0.9, fontWeight: 700, marginBottom: 14 }}>⚡ Qué asignar</div>

            <div style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 12, color: GC.ink2, fontWeight: 600, marginBottom: 5 }}>📍 Nueva zona</div>
              <select value={asigZonaId} onChange={e => setAsigZonaId(e.target.value)} style={selStyle(!!asigZonaId, GC.brand, GC.brandLight, GC.brandMid)}>
                <option value="">— No cambiar zona —</option>
                {zonas.filter(z => z.activa).map(z => <option key={z.id} value={z.id}>{z.nombre}</option>)}
              </select>
            </div>

            <div style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 12, color: GC.ink2, fontWeight: 600, marginBottom: 5 }}>📦 Nuevo plan</div>
              <select value={asigPlanId} onChange={e => setAsigPlanId(e.target.value)} style={selStyle(!!asigPlanId, GC.info, GC.infoBg, GC.infoBdr)}>
                <option value="">— No cambiar plan —</option>
                {planes.filter(p => p.activo).map(p => <option key={p.id} value={p.id}>{p.nombre} — {formatCOP(p.precio)}</option>)}
              </select>
            </div>

            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 12, color: GC.ink2, fontWeight: 600, marginBottom: 5 }}>📅 Nuevo perfil de pago</div>
              <select value={asigPerfilId} onChange={e => setAsigPerfilId(e.target.value)} style={selStyle(!!asigPerfilId, GC.purple, GC.purpleBg, GC.purpleBdr)}>
                <option value="">— No cambiar perfil —</option>
                {perfilesPago.filter(p => p.activo).map(p => <option key={p.id} value={p.id}>{p.nombre} (días {p.diaInicio}–{p.diaFin})</option>)}
              </select>
            </div>

            {/* Resumen pre-aplicación */}
            {algunoSeleccionado && hayAlgoParaAsignar && (
              <div style={{ background: GC.brandLight, border: "1px solid " + GC.brandMid, borderRadius: 10, padding: "10px 12px", marginBottom: 14, fontSize: 12, color: GC.brandText }}>
                <div style={{ fontWeight: 800, marginBottom: 5 }}>Resumen de la operación:</div>
                <div>👥 <strong>{seleccionados.size}</strong> cliente{seleccionados.size !== 1 ? "s" : ""} afectado{seleccionados.size !== 1 ? "s" : ""}</div>
                {asigZonaId   && <div>📍 Zona: <strong>{nombreZona(asigZonaId)}</strong></div>}
                {asigPlanId   && <div>📦 Plan: <strong>{nombrePlan(asigPlanId)}</strong></div>}
                {asigPerfilId && <div>📅 Perfil: <strong>{nombrePerfil(asigPerfilId)}</strong></div>}
              </div>
            )}

            {/* Botón / confirmación */}
            {!confirmando ? (
              <button
                onClick={() => { if (algunoSeleccionado && hayAlgoParaAsignar) setConfirmando(true); }}
                disabled={!algunoSeleccionado || !hayAlgoParaAsignar || aplicando}
                style={{ width: "100%", padding: "11px 0", borderRadius: 10, background: (algunoSeleccionado && hayAlgoParaAsignar) ? GC.brand : GC.bg3, color: (algunoSeleccionado && hayAlgoParaAsignar) ? "#fff" : GC.ink3, border: "none", fontWeight: 800, fontSize: 14, cursor: (algunoSeleccionado && hayAlgoParaAsignar) ? "pointer" : "not-allowed", fontFamily: "inherit", opacity: aplicando ? 0.7 : 1 }}
              >
                {!algunoSeleccionado ? "Selecciona clientes primero" : !hayAlgoParaAsignar ? "Elige qué asignar" : `⚡ Aplicar a ${seleccionados.size} cliente${seleccionados.size !== 1 ? "s" : ""}`}
              </button>
            ) : (
              <div style={{ background: GC.dangerBg, border: "1px solid " + GC.dangerBdr, borderRadius: 10, padding: 12 }}>
                <div style={{ fontSize: 13, color: "#7f1d1d", fontWeight: 700, marginBottom: 6 }}>⚠️ ¿Confirmas esta asignación masiva?</div>
                <div style={{ fontSize: 12, color: GC.danger, marginBottom: 10 }}>Se modificarán <strong>{seleccionados.size}</strong> clientes. Esta acción no se puede deshacer fácilmente.</div>
                <div style={{ display: "flex", gap: 8 }}>
                  <button onClick={aplicar} style={{ flex: 1, padding: "9px 0", background: GC.danger, color: "#fff", border: "none", borderRadius: 8, fontWeight: 800, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>Sí, aplicar</button>
                  <button onClick={() => setConfirmando(false)} style={{ flex: 1, padding: "9px 0", background: GC.bg3, color: GC.ink2, border: "1px solid " + GC.border, borderRadius: 8, fontWeight: 700, fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>Cancelar</button>
                </div>
              </div>
            )}

            {/* Barra de progreso */}
            {aplicando && (
              <div style={{ marginTop: 14 }}>
                <div style={{ fontSize: 12, color: GC.ink3, marginBottom: 5 }}>Aplicando… {progreso}%</div>
                <div style={{ height: 6, background: GC.bg3, borderRadius: 99, overflow: "hidden" }}>
                  <div style={{ height: "100%", width: progreso + "%", background: GC.brand, borderRadius: 99, transition: "width .2s" }} />
                </div>
              </div>
            )}

            {/* Resultado */}
            {resultado && (
              <div style={{ marginTop: 14, background: resultado.err === 0 ? GC.brandLight : GC.warningBg, border: "1px solid " + (resultado.err === 0 ? GC.brandMid : GC.warningBdr), borderRadius: 10, padding: "10px 12px", fontSize: 13 }}>
                {resultado.err === 0
                  ? <span style={{ color: GC.brandText, fontWeight: 700 }}>✅ {resultado.ok} cliente{resultado.ok !== 1 ? "s" : ""} actualizados correctamente.</span>
                  : <span style={{ color: GC.warning, fontWeight: 700 }}>⚠️ {resultado.ok} OK · {resultado.err} con error. Revisa la consola.</span>}
                <button onClick={() => setResultado(null)} style={{ display: "block", marginTop: 6, background: "none", border: "none", color: GC.ink3, fontSize: 11, cursor: "pointer", padding: 0, fontFamily: "inherit" }}>Cerrar</button>
              </div>
            )}

            {(asigZonaId || asigPlanId || asigPerfilId) && !confirmando && (
              <button onClick={limpiarAsignacion} style={{ display: "block", marginTop: 10, background: "none", border: "none", color: GC.ink3, fontSize: 12, cursor: "pointer", fontFamily: "inherit", width: "100%", textAlign: "center" }}>
                ✕ Limpiar selección de asignación
              </button>
            )}
          </div>

          <div style={{ padding: "4px 4px", fontSize: 11, color: GC.ink4, lineHeight: 1.8 }}>
            <div>💡 Combina filtros para segmentar exactamente los clientes que quieres.</div>
            <div>✅ Solo se modifican los campos que seleccionaste. Los demás permanecen igual.</div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// AGENTE DE IMPRESIÓN — corre silenciosamente en cada PC con impresora
// Se activa automáticamente si el usuario tiene una impresora asignada
// ════════════════════════════════════════════════════════════════
function AgentImpresora({ impresoraId, qzNombre, db }) {
  const [estado, setEstado] = useState("inactivo");

  useEffect(() => {
    if (!impresoraId || !window.qz) return;

    let channel = null;
    let activo = true;

    const iniciar = async () => {
      try {
        // Conectar QZ Tray
        if (!qz.websocket.isActive()) {
          await qz.websocket.connect({ retries: 3, delay: 1 });
        }
        setEstado("activo");
        await db.pingImpresora(impresoraId);

        // Suscribir a la cola de impresión via Realtime
        channel = sb.channel("print_queue_" + impresoraId)
          .on("postgres_changes", {
            event: "INSERT",
            schema: "public",
            table: "print_queue",
            filter: "impresora_id=eq." + impresoraId
          }, async (payload) => {
            const job = payload.new;
            if (job.estado !== "pendiente") return;

            try {
              await db.actualizarEstadoCola(job.id, "imprimiendo", null);

              // Decodificar ESC/POS
              const escpos = decodeURIComponent(escape(atob(job.datos_escpos)));

              // Encontrar impresora
              let imp = null;
              if (qzNombre) {
                try { const l = await qz.printers.find(qzNombre); imp = Array.isArray(l) ? l[0] : l; } catch {}
              }
              if (!imp) {
                try { const l = await qz.printers.find("TM-U220"); imp = Array.isArray(l) ? l[0] : l; } catch {}
              }
              if (!imp) imp = await qz.printers.getDefault();

              const config = qz.configs.create(imp, { encoding: "Cp1252", copies: 1 });
              await qz.print(config, [{ type: "raw", format: "plain", data: escpos }]);
              await db.actualizarEstadoCola(job.id, "completado", null);
            } catch (e) {
              await db.actualizarEstadoCola(job.id, "error", e.message);
            }
          })
          .subscribe();

        // Ping cada 30 segundos para mostrar que está activo
        const pingInterval = setInterval(async () => {
          if (!activo) { clearInterval(pingInterval); return; }
          await db.pingImpresora(impresoraId);
        }, 30000);

      } catch (e) {
        setEstado("error");
        console.error("AgentImpresora error:", e);
      }
    };

    iniciar();

    return () => {
      activo = false;
      if (channel) sb.removeChannel(channel);
      setEstado("inactivo");
    };
  }, [impresoraId]);

  if (estado === "inactivo") return null;

  return (
    <div style={{ position: "fixed", bottom: 12, right: 12, background: estado === "activo" ? "#f0fdf4" : "#fef2f2", border: "1px solid " + (estado === "activo" ? "#bbf7d0" : "#fecaca"), borderRadius: 10, padding: "6px 12px", fontSize: 11, color: estado === "activo" ? "#16a34a" : "#ef4444", zIndex: 9999, display: "flex", alignItems: "center", gap: 6 }}>
      <span style={{ width: 8, height: 8, borderRadius: "50%", background: estado === "activo" ? "#16a34a" : "#ef4444", display: "inline-block" }} />
      {estado === "activo" ? "Impresora activa" : "Error de impresora"}
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// PANEL DE IMPRESORAS — gestión desde el admin
// ════════════════════════════════════════════════════════════════
function PanelImpresoras({ zonas, db }) {
  const [impresoras, setImpresoras] = useState([]);
  const [editP, setEditP] = useState(null);
  const [cargando, setCargando] = useState(false);
  const EMPTY = { id: "", nombre: "", zonaId: "", zonaNombre: "", modelo: "TM-U220D", qzNombre: "", activa: true };

  useEffect(() => { db.getImpresoras().then(setImpresoras).catch(console.error); }, []);

  const guardar = async () => {
    if (!editP.nombre) { alert("Ingresa un nombre para la impresora."); return; }
    setCargando(true);
    try {
      const zona = zonas.find(z => z.id === editP.zonaId);
      const r = await db.upsertImpresora({ ...editP, zonaNombre: zona?.nombre || "" });
      setImpresoras(prev => editP.id ? prev.map(p => p.id === r.id ? r : p) : [r, ...prev]);
      setEditP(null);
    } catch(e) { alert("Error: " + e.message); }
    setCargando(false);
  };

  const ahora = new Date();
  const estaActiva = (p) => p.ultima_vez && (ahora - new Date(p.ultima_vez)) < 60000; // activa si ping < 1 min

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <div style={{ fontWeight: 700, fontSize: 15, color: GC.ink }}>🖨️ Impresoras registradas</div>
        <Btn onClick={() => setEditP({ ...EMPTY })} style={{ fontSize: 13 }}>+ Agregar impresora</Btn>
      </div>

      {/* Instrucciones */}
      <div style={{ background: "#eff6ff", border: "1px solid #bfdbfe", borderRadius: 10, padding: "12px 16px", marginBottom: 16, fontSize: 12, color: "#1e40af" }}>
        <strong>Cómo funciona:</strong> Registra cada impresora con su nombre exacto en Windows. En el PC donde está conectada la impresora, el agente se activará automáticamente cuando ese usuario inicie sesión. Cualquier otro PC puede enviarle trabajos de impresión en tiempo real.
      </div>

      {/* Formulario */}
      {editP && (
        <div style={{ background: "#fff", border: "1px solid " + GC.border, borderRadius: 14, padding: 20, marginBottom: 16 }}>
          <div style={{ fontWeight: 700, marginBottom: 14 }}>{editP.id ? "Editar impresora" : "Nueva impresora"}</div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }}>
            <Field label="Nombre de la impresora">
              <Inp value={editP.nombre} onChange={e => setEditP(p => ({ ...p, nombre: e.target.value }))} placeholder="Ej: Epson Vijes Principal" />
            </Field>
            <Field label="Zona">
              <Sel value={editP.zonaId || ""} onChange={e => setEditP(p => ({ ...p, zonaId: e.target.value }))}>
                <option value="">Sin zona específica</option>
                {zonas.filter(z => z.activa).map(z => <option key={z.id} value={z.id}>{z.nombre}</option>)}
              </Sel>
            </Field>
            <Field label="Nombre exacto en Windows / QZ Tray">
              <Inp value={editP.qzNombre || ""} onChange={e => setEditP(p => ({ ...p, qzNombre: e.target.value }))} placeholder="Ej: EPSON TM-U220D Receipt" />
              <div style={{ fontSize: 10, color: GC.ink3, marginTop: 2 }}>Nombre que aparece en Panel de control → Dispositivos e impresoras</div>
            </Field>
            <Field label="Modelo">
              <Sel value={editP.modelo || "TM-U220D"} onChange={e => setEditP(p => ({ ...p, modelo: e.target.value }))}>
                <option>TM-U220D</option><option>TM-T20</option><option>TM-T88</option><option>Otra</option>
              </Sel>
            </Field>
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
            <Btn onClick={guardar} disabled={cargando}>{cargando ? "Guardando..." : "Guardar"}</Btn>
            <button onClick={() => setEditP(null)} style={{ padding: "9px 16px", background: GC.bg3, border: "none", borderRadius: 9, cursor: "pointer", fontSize: 13, fontFamily: "inherit" }}>Cancelar</button>
          </div>
        </div>
      )}

      {/* Lista */}
      {impresoras.length === 0 ? (
        <div style={{ textAlign: "center", color: GC.ink3, padding: 40 }}>No hay impresoras registradas</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {impresoras.map(p => {
            const activa = estaActiva(p);
            return (
              <div key={p.id} style={{ background: "#fff", border: "1px solid " + GC.border, borderLeft: "4px solid " + (activa ? "#16a34a" : "#94a3b8"), borderRadius: 10, padding: "12px 16px", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
                <div>
                  <div style={{ fontWeight: 700, fontSize: 14, color: GC.ink }}>{p.nombre}</div>
                  <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>
                    {p.zona_nombre || "Sin zona"} · {p.modelo}
                    {p.qz_nombre && <span> · QZ: <em>{p.qz_nombre}</em></span>}
                  </div>
                  <div style={{ fontSize: 11, marginTop: 4 }}>
                    <span style={{ background: activa ? "#f0fdf4" : "#f1f5f9", color: activa ? "#16a34a" : "#94a3b8", borderRadius: 6, padding: "2px 8px", fontWeight: 700 }}>
                      {activa ? "🟢 Agente activo" : p.ultima_vez ? "🔴 Desconectada" : "⚪ Sin conectar"}
                    </span>
                    {p.ultima_vez && <span style={{ color: GC.ink4, marginLeft: 8 }}>Último ping: {new Date(p.ultima_vez).toLocaleTimeString("es-CO")}</span>}
                  </div>
                </div>
                <div style={{ display: "flex", gap: 6 }}>
                  <button onClick={() => setEditP({ id: p.id, nombre: p.nombre, zonaId: p.zona_id || "", zonaNombre: p.zona_nombre || "", modelo: p.modelo, qzNombre: p.qz_nombre || "", activa: p.activa })}
                    style={{ background: GC.bg3, border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>✏️</button>
                  <button onClick={async () => { if (confirm("¿Eliminar impresora " + p.nombre + "?")) { await db.deleteImpresora(p.id); setImpresoras(prev => prev.filter(x => x.id !== p.id)); } }}
                    style={{ background: "#fef2f2", color: "#ef4444", border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer" }}>🗑️</button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function PanelCortes({ usuarios, perfilesPago, sesion, db }) {
  const [subTab, setSubTab] = useState("config");
  const [cfg, setCfg]       = useState({ hora_corte: 0, minuto_corte: 5, dias_gracia: 0, activo: true });
  const [excepciones, setExcepciones] = useState([]);
  const [promesas, setPromesas]       = useState([]);
  const [newExc, setNewExc] = useState({ fecha: "", motivo: "", nuevaFecha: "" });
  const [newProm, setNewProm] = useState({ clienteId: "", fechaPromesa: "", montoPrometer: "", notas: "" });
  const [guardando, setGuardando] = useState(false);
  const [msg, setMsg] = useState(null);

  useEffect(() => {
    db.getCortesConfig().then(setCfg).catch(console.error);
    db.getExcepciones().then(setExcepciones).catch(console.error);
    db.getPromesas().then(setPromesas).catch(console.error);
  }, []);

  const saveCfg = async () => {
    setGuardando(true);
    try {
      await db.saveCortesConfig({ ...cfg, updated_by: sesion?.usuario });
      // Actualizar cron con nueva hora
      setMsg({ ok: true, txt: "Configuracion guardada. El cron se ejecutará a las " + String(cfg.hora_corte).padStart(2,"0") + ":" + String(cfg.minuto_corte).padStart(2,"0") + " UTC" });
    } catch(e) { setMsg({ ok: false, txt: "Error: " + e.message }); }
    setGuardando(false);
    setTimeout(() => setMsg(null), 4000);
  };

  const saveExc = async () => {
    if (!newExc.fecha || !newExc.motivo) { alert("Ingresa fecha y motivo"); return; }
    try {
      const r = await db.upsertExcepcion({ ...newExc, createdBy: sesion?.usuario });
      setExcepciones(prev => [...prev.filter(e => e.fecha !== r.fecha), r].sort((a,b) => a.fecha.localeCompare(b.fecha)));
      setNewExc({ fecha: "", motivo: "", nuevaFecha: "" });
    } catch(e) { alert("Error: " + e.message); }
  };

  const saveProm = async () => {
    if (!newProm.clienteId || !newProm.fechaPromesa) { alert("Selecciona cliente y fecha"); return; }
    const cliente = usuarios.find(u => u.id === newProm.clienteId);
    try {
      const r = await db.upsertPromesa({ ...newProm, clienteNombre: cliente?.nombre, createdBy: sesion?.usuario });
      setPromesas(prev => [r, ...prev]);
      setNewProm({ clienteId: "", fechaPromesa: "", montoPrometer: "", notas: "" });
    } catch(e) { alert("Error: " + e.message); }
  };

  const HORAS = Array.from({length:24}, (_,i) => i);
  const clientes = usuarios.filter(u => u.rol === "cliente" && u.activo);
  const hoy = new Date().toISOString().split("T")[0];

  return (
    <div>
      {/* Sub-tabs */}
      <div style={{ display: "flex", gap: 4, marginBottom: 20, background: GC.bg3, borderRadius: 12, padding: 4 }}>
        {[["config","⚙️ Configuración"],["excepciones","📆 Excepciones"],["promesas","🤝 Promesas de pago"]].map(([k,l]) => (
          <button key={k} onClick={() => setSubTab(k)} style={{ flex: 1, padding: "9px 6px", borderRadius: 9, border: "none", cursor: "pointer", background: subTab === k ? GC.ink : "transparent", color: subTab === k ? "#fff" : GC.ink3, fontWeight: subTab === k ? 700 : 500, fontSize: 13, fontFamily: "inherit" }}>{l}</button>
        ))}
      </div>

      {/* ── CONFIG ── */}
      {subTab === "config" && (
        <div>
          <div style={{ background: "#fff", border: "1px solid " + GC.border, borderRadius: 14, padding: 20, marginBottom: 16 }}>
            <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 16, color: GC.ink }}>⚙️ Configuracion de cortes automaticos</div>

            {/* ON/OFF */}
            <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 20, background: cfg.activo ? "#f0fdf4" : "#fef2f2", border: "1px solid " + (cfg.activo ? "#bbf7d0" : "#fecaca"), borderRadius: 10, padding: "12px 16px" }}>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, color: cfg.activo ? "#16a34a" : "#ef4444" }}>{cfg.activo ? "Corte automatico ACTIVO" : "Corte automatico INACTIVO"}</div>
                <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>Cuando esta inactivo ningun cliente sera cortado automaticamente</div>
              </div>
              <button onClick={() => setCfg(c => ({ ...c, activo: !c.activo }))}
                style={{ background: cfg.activo ? "#16a34a" : "#94a3b8", color: "#fff", border: "none", borderRadius: 8, padding: "8px 16px", cursor: "pointer", fontWeight: 700, fontSize: 13 }}>
                {cfg.activo ? "Desactivar" : "Activar"}
              </button>
            </div>

            {/* Hora */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "0 16px" }}>
              <Field label="Hora del corte (UTC)">
                <Sel value={cfg.hora_corte} onChange={e => setCfg(c => ({ ...c, hora_corte: Number(e.target.value) }))}>
                  {HORAS.map(h => <option key={h} value={h}>{String(h).padStart(2,"0")}:00 UTC ({String((h - 5 + 24) % 24).padStart(2,"0")}:00 Colombia)</option>)}
                </Sel>
              </Field>
              <Field label="Minuto">
                <Sel value={cfg.minuto_corte} onChange={e => setCfg(c => ({ ...c, minuto_corte: Number(e.target.value) }))}>
                  {[0,5,10,15,20,30,45].map(m => <option key={m} value={m}>{String(m).padStart(2,"0")}</option>)}
                </Sel>
              </Field>
              <Field label="Dias de gracia despues del vencimiento">
                <Inp type="number" min="0" max="30" value={cfg.dias_gracia} onChange={e => setCfg(c => ({ ...c, dias_gracia: Number(e.target.value) }))} />
              </Field>
            </div>

            <div style={{ background: "#eff6ff", borderRadius: 8, padding: "10px 14px", marginBottom: 16, fontSize: 13, color: "#1e40af" }}>
              El cron corre a las <strong>{String(cfg.hora_corte).padStart(2,"0")}:{String(cfg.minuto_corte).padStart(2,"0")} UTC</strong> = <strong>{String((cfg.hora_corte - 5 + 24) % 24).padStart(2,"0")}:{String(cfg.minuto_corte).padStart(2,"0")} hora Colombia</strong> cada dia. Con {cfg.dias_gracia} dia(s) de gracia adicional.
            </div>

            {msg && <div style={{ background: msg.ok ? "#f0fdf4" : "#fef2f2", border: "1px solid " + (msg.ok ? "#bbf7d0" : "#fecaca"), borderRadius: 8, padding: "10px 14px", marginBottom: 12, fontSize: 13, color: msg.ok ? "#16a34a" : "#ef4444" }}>{msg.txt}</div>}
            <Btn onClick={saveCfg} disabled={guardando}>{guardando ? "Guardando..." : "Guardar configuracion"}</Btn>
          </div>

          {/* Info perfiles */}
          <div style={{ background: "#fff", border: "1px solid " + GC.border, borderRadius: 14, padding: 20 }}>
            <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 12, color: GC.ink }}>📅 Dia de corte por perfil de pago</div>
            <div style={{ fontSize: 12, color: GC.ink3, marginBottom: 12 }}>Para cambiar el dia de corte de cada perfil, ve a la seccion Perfiles pago y edita el campo "Dia de corte".</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {perfilesPago.map(p => (
                <div key={p.id} style={{ display: "flex", justifyContent: "space-between", background: GC.bg3, borderRadius: 8, padding: "10px 14px" }}>
                  <span style={{ fontWeight: 600, color: GC.ink }}>{p.nombre}</span>
                  <span style={{ fontSize: 13, color: GC.ink3 }}>Pago: dias {p.diaInicio}-{p.diaFin} · <strong style={{ color: "#ef4444" }}>Corte: dia {p.diaCorte || 20}</strong></span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ── EXCEPCIONES ── */}
      {subTab === "excepciones" && (
        <div>
          <div style={{ background: "#fff", border: "1px solid " + GC.border, borderRadius: 14, padding: 20, marginBottom: 16 }}>
            <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 4, color: GC.ink }}>📆 Agregar excepcion de corte</div>
            <div style={{ fontSize: 12, color: GC.ink3, marginBottom: 14 }}>Si cae un festivo o necesitas suspender el corte un dia especifico, agrega una excepcion aqui.</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }}>
              <Field label="Fecha a exceptuar">
                <Inp type="date" value={newExc.fecha} min={hoy} onChange={e => setNewExc(x => ({ ...x, fecha: e.target.value }))} />
              </Field>
              <Field label="Fecha alternativa de corte (opcional)">
                <Inp type="date" value={newExc.nuevaFecha} min={hoy} onChange={e => setNewExc(x => ({ ...x, nuevaFecha: e.target.value }))} />
                <div style={{ fontSize: 10, color: GC.ink3, marginTop: 2 }}>Dejar vacío = no cortar ese dia</div>
              </Field>
            </div>
            <Field label="Motivo (festivo, emergencia, etc.)">
              <Inp value={newExc.motivo} onChange={e => setNewExc(x => ({ ...x, motivo: e.target.value }))} placeholder="Ej: Festivo nacional, Semana Santa..." />
            </Field>
            <Btn onClick={saveExc}>Agregar excepcion</Btn>
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {excepciones.length === 0 ? (
              <div style={{ textAlign: "center", color: GC.ink3, padding: 30 }}>No hay excepciones configuradas</div>
            ) : excepciones.map(e => (
              <div key={e.id} style={{ background: "#fff", border: "1px solid #fcd34d", borderLeft: "4px solid #f59e0b", borderRadius: 10, padding: "12px 16px", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                <div>
                  <div style={{ fontWeight: 700, color: GC.ink }}>{e.fecha} — {e.motivo}</div>
                  <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>
                    {e.nueva_fecha ? "Corte pospuesto al " + e.nueva_fecha : "No se corta ese dia"}
                  </div>
                </div>
                <button onClick={async () => { await db.deleteExcepcion(e.id); setExcepciones(p => p.filter(x => x.id !== e.id)); }}
                  style={{ background: "#fef2f2", color: "#ef4444", border: "none", borderRadius: 7, padding: "6px 10px", cursor: "pointer", fontSize: 12 }}>Eliminar</button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── PROMESAS DE PAGO ── */}
      {subTab === "promesas" && (
        <div>
          <div style={{ background: "#fff", border: "1px solid " + GC.border, borderRadius: 14, padding: 20, marginBottom: 16 }}>
            <div style={{ fontWeight: 700, fontSize: 15, marginBottom: 4, color: GC.ink }}>🤝 Nueva promesa de pago</div>
            <div style={{ fontSize: 12, color: GC.ink3, marginBottom: 14 }}>El cliente se compromete a pagar antes de la fecha indicada. El corte automatico lo respetara.</div>
            <Field label="Cliente">
              <Sel value={newProm.clienteId} onChange={e => setNewProm(x => ({ ...x, clienteId: e.target.value }))}>
                <option value="">Seleccionar cliente...</option>
                {clientes.sort((a,b) => a.nombre.localeCompare(b.nombre)).map(c => (
                  <option key={c.id} value={c.id}>{c.nombre} {c.estado === "DPP" ? "(DPP)" : ""}</option>
                ))}
              </Sel>
            </Field>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }}>
              <Field label="Se compromete a pagar antes del">
                <Inp type="date" value={newProm.fechaPromesa} min={hoy} onChange={e => setNewProm(x => ({ ...x, fechaPromesa: e.target.value }))} />
              </Field>
              <Field label="Monto prometido (opcional)">
                <Inp type="number" value={newProm.montoPrometer} onChange={e => setNewProm(x => ({ ...x, montoPrometer: e.target.value }))} placeholder="Ej: 37000" />
              </Field>
            </div>
            <Field label="Notas (opcional)">
              <Inp value={newProm.notas} onChange={e => setNewProm(x => ({ ...x, notas: e.target.value }))} placeholder="Acuerdo, motivo, etc." />
            </Field>
            <Btn onClick={saveProm}>Registrar promesa</Btn>
          </div>

          {/* Lista promesas */}
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {promesas.length === 0 ? (
              <div style={{ textAlign: "center", color: GC.ink3, padding: 30 }}>No hay promesas de pago registradas</div>
            ) : promesas.map(p => {
              const vencida = p.fecha_promesa < hoy && p.estado === "Pendiente";
              const estadoColor = { Pendiente: "#f59e0b", Cumplida: "#16a34a", Incumplida: "#ef4444", Cancelada: "#94a3b8" }[p.estado] || "#94a3b8";
              return (
                <div key={p.id} style={{ background: "#fff", border: "1px solid " + (vencida ? "#fecaca" : "#e2e8f0"), borderLeft: "4px solid " + estadoColor, borderRadius: 10, padding: "12px 16px" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 8 }}>
                    <div>
                      <div style={{ fontWeight: 700, color: GC.ink }}>{p.cliente_nombre}</div>
                      <div style={{ fontSize: 13, color: GC.ink3, marginTop: 2 }}>
                        Promete pagar antes del <strong>{p.fecha_promesa}</strong>
                        {p.monto_prometido ? ` · ${formatCOP(Number(p.monto_prometido))}` : ""}
                      </div>
                      {p.notas && <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>{p.notas}</div>}
                      {vencida && <div style={{ fontSize: 11, color: "#ef4444", marginTop: 4, fontWeight: 700 }}>Promesa vencida sin marcar</div>}
                    </div>
                    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                      {p.estado === "Pendiente" && (
                        <>
                          <button onClick={async () => { await db.upsertPromesa({ id: p.id, clienteId: p.cliente_id, clienteNombre: p.cliente_nombre, fechaPromesa: p.fecha_promesa, estado: "Cumplida" }); setPromesas(prev => prev.map(x => x.id === p.id ? { ...x, estado: "Cumplida" } : x)); }}
                            style={{ background: "#f0fdf4", color: "#16a34a", border: "1px solid #bbf7d0", borderRadius: 7, padding: "5px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>Cumplida</button>
                          <button onClick={async () => { await db.upsertPromesa({ id: p.id, clienteId: p.cliente_id, clienteNombre: p.cliente_nombre, fechaPromesa: p.fecha_promesa, estado: "Incumplida" }); setPromesas(prev => prev.map(x => x.id === p.id ? { ...x, estado: "Incumplida" } : x)); }}
                            style={{ background: "#fef2f2", color: "#ef4444", border: "1px solid #fecaca", borderRadius: 7, padding: "5px 10px", cursor: "pointer", fontSize: 12, fontWeight: 700 }}>Incumplida</button>
                        </>
                      )}
                      {p.estado !== "Pendiente" && <span style={{ fontSize: 12, fontWeight: 700, color: estadoColor, padding: "5px 10px" }}>{p.estado}</span>}
                      <button onClick={async () => { await db.deletePromesa(p.id); setPromesas(prev => prev.filter(x => x.id !== p.id)); }}
                        style={{ background: GC.bg3, color: GC.ink3, border: "none", borderRadius: 7, padding: "5px 8px", cursor: "pointer", fontSize: 12 }}>🗑️</button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function ProntoPagoPanel({ z, prontoPagos, setProntoPagos, planes, editPP, setEditPP, db }) {
  const ppZona = prontoPagos.filter(p => p.zona_id === z.id);
  return (
    <div style={{ marginTop: 14, borderTop: "1px dashed #f59e0b", paddingTop: 14 }}>
      <div style={{ fontWeight: 700, color: "#d97706", fontSize: 13, marginBottom: 10 }}>🏷️ Pronto pago — {z.nombre}</div>
      {ppZona.length > 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 12 }}>
          {ppZona.map(pp => (
            <div key={pp.id} style={{ display: "flex", alignItems: "center", gap: 10, background: pp.activo ? "#fef3c7" : "#f1f5f9", borderRadius: 8, padding: "8px 12px", flexWrap: "wrap" }}>
              <div style={{ flex: 1 }}>
                <span style={{ fontWeight: 700, color: "#111", fontSize: 13 }}>
                  {pp.plan_nombre ? "Plan: " + pp.plan_nombre : "Todos los planes"}
                </span>
                <span style={{ fontSize: 12, color: "#64748b", marginLeft: 8 }}>
                  Descuento: <strong style={{ color: "#d97706" }}>${Number(pp.descuento).toLocaleString("es-CO")}</strong> si paga antes del día <strong>{pp.dia_limite}</strong>
                </span>
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                <button onClick={async () => { await db.upsertProntoPago({ id: pp.id, zonaId: pp.zona_id, planId: pp.plan_id, planNombre: pp.plan_nombre, descuento: pp.descuento, diaLimite: pp.dia_limite, activo: !pp.activo }); setProntoPagos(await db.getProntoPago()); }} style={{ background: pp.activo ? "#dcfce7" : "#e2e8f0", color: pp.activo ? "#16a34a" : "#64748b", border: "none", borderRadius: 6, padding: "4px 10px", cursor: "pointer", fontSize: 11, fontWeight: 700 }}>{pp.activo ? "Activo" : "Inactivo"}</button>
                <button onClick={async () => { await db.deleteProntoPago(pp.id); setProntoPagos(await db.getProntoPago()); }} style={{ background: "#fef2f2", color: "#ef4444", border: "none", borderRadius: 6, padding: "4px 8px", cursor: "pointer", fontSize: 12 }}>🗑️</button>
              </div>
            </div>
          ))}
        </div>
      )}
      <div style={{ background: "#fff", border: "1px solid #fcd34d", borderRadius: 10, padding: 14 }}>
        <div style={{ fontSize: 12, color: "#64748b", marginBottom: 10, fontWeight: 600 }}>Agregar descuento de pronto pago</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 12px" }}>
          <Field label="Plan (opcional)">
            <Sel value={editPP.planId || ""} onChange={e => { const plan = planes.find(p => p.id === e.target.value); setEditPP({ ...editPP, planId: e.target.value, planNombre: plan ? plan.nombre : "" }); }}>
              <option value="">Todos los planes</option>
              {planes.filter(p => p.activo).map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
            </Sel>
          </Field>
          <Field label="Descuento fijo ($)">
            <Inp type="number" value={editPP.descuento} onChange={e => setEditPP({ ...editPP, descuento: e.target.value })} placeholder="Ej: 2000" />
          </Field>
          <Field label="Si paga antes del dia #">
            <Inp type="number" min="1" max="31" value={editPP.diaLimite} onChange={e => setEditPP({ ...editPP, diaLimite: e.target.value })} placeholder="Ej: 10" />
          </Field>
        </div>
        {editPP.descuento && editPP.diaLimite && (
          <div style={{ fontSize: 11, color: "#92400e", margin: "8px 0 10px", background: "#fef3c7", padding: "6px 10px", borderRadius: 6 }}>
            Si paga antes del dia {editPP.diaLimite}: descuento de ${Number(editPP.descuento).toLocaleString("es-CO")}
          </div>
        )}
        <Btn onClick={async () => {
          if (!editPP.descuento || !editPP.diaLimite) { alert("Ingresa el descuento y el dia limite."); return; }
          try {
            await db.upsertProntoPago({ zonaId: z.id, planId: editPP.planId || null, planNombre: editPP.planNombre || null, descuento: editPP.descuento, diaLimite: editPP.diaLimite, activo: true });
            setProntoPagos(await db.getProntoPago());
            setEditPP({ zonaId: "", planId: "", planNombre: "", descuento: "", diaLimite: 10, activo: true });
          } catch(e) { alert("Error: " + e.message); }
        }} style={{ fontSize: 13 }}>Guardar descuento</Btn>
      </div>
    </div>
  );
}

function ExportClientesModal({ usuarios, zonas, planes, perfilesPago, db, onClose }) {
  const [filtros, setFiltros] = useState({
    zona:     "",
    servicio: "",   // Internet | TV | Combo | todos
    estado:   "",   // Al día | DPP | DPS | Cortesía | todos
    deuda:    "",   // con_deuda | sin_deuda | todos
  });
  const [cargando, setCargando] = useState(false);

  // Previsualización: cuántos clientes coinciden
  const clientes = usuarios.filter(u => {
    if (u.rol !== "cliente" || !u.activo) return false;
    if (filtros.zona && u.zonaId !== filtros.zona) return false;
    if (filtros.estado && u.estado !== filtros.estado) return false;
    if (filtros.servicio) {
      const srv = (u.servicio || "Internet").toLowerCase();
      if (filtros.servicio === "Internet" && !srv.includes("internet")) return false;
      if (filtros.servicio === "TV"       && !srv.includes("tv"))       return false;
      if (filtros.servicio === "Combo"    && !(srv.includes("internet") && srv.includes("tv"))) return false;
    }
    return true;
  });

  const doExport = async () => {
    setCargando(true);
    try {
      const todasFacturas = await db.getFacturas();
      // Aplicar filtro de deuda después de tener las facturas
      let clientesFinal = clientes;
      if (filtros.deuda === "con_deuda") {
        clientesFinal = clientes.filter(c => {
          const deuda = todasFacturas.filter(f => f.clienteId === c.id && f.estado !== "Anulada").reduce((s,f) => s + (f.saldoPendiente||0), 0);
          return deuda > 0;
        });
      } else if (filtros.deuda === "sin_deuda") {
        clientesFinal = clientes.filter(c => {
          const deuda = todasFacturas.filter(f => f.clienteId === c.id && f.estado !== "Anulada").reduce((s,f) => s + (f.saldoPendiente||0), 0);
          return deuda === 0;
        });
      }
      exportarClientes(clientesFinal, todasFacturas, zonas, planes, perfilesPago);
      onClose();
    } catch(e) { alert("Error: " + e.message); }
    setCargando(false);
  };

  const SERVICIOS = ["Internet", "TV", "Combo"];
  const ESTADOS   = ["Al día", "DPP", "DPS", "Cortesía", "Pendiente"];

  return (
    <div style={{ position: "fixed", inset: 0, background: "#00000066", zIndex: 9000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
      onClick={e => e.target === e.currentTarget && onClose()}>
      <div style={{ background: "#fff", borderRadius: 16, width: "100%", maxWidth: 480, boxShadow: "0 20px 60px #00000033", overflow: "hidden" }}>

        {/* Header */}
        <div style={{ padding: "18px 20px", borderBottom: "1px solid #e2e8f0", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontWeight: 800, fontSize: 16, color: GC.ink }}>📋 Exportar clientes</div>
            <div style={{ fontSize: 12, color: GC.ink3, marginTop: 2 }}>Aplica filtros y descarga el CSV</div>
          </div>
          <button onClick={onClose} style={{ background: GC.bg3, border: "none", borderRadius: 8, width: 32, height: 32, cursor: "pointer", fontSize: 18, color: GC.ink3 }}>×</button>
        </div>

        <div style={{ padding: 20 }}>

          {/* Filtro zona */}
          <Field label="Zona">
            <Sel value={filtros.zona} onChange={e => setFiltros(f => ({ ...f, zona: e.target.value }))}>
              <option value="">Todas las zonas</option>
              {zonas.filter(z => z.activa).map(z => <option key={z.id} value={z.id}>{z.nombre}</option>)}
            </Sel>
          </Field>

          {/* Filtro servicio */}
          <Field label="Tipo de servicio">
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {["", ...SERVICIOS].map(s => (
                <button key={s} onClick={() => setFiltros(f => ({ ...f, servicio: s }))}
                  style={{ padding: "7px 14px", borderRadius: 8, border: "2px solid " + (filtros.servicio === s ? GC.brand : "#e2e8f0"), background: filtros.servicio === s ? GC.brandLight : "#fff", color: filtros.servicio === s ? GC.brand : GC.ink2, cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit" }}>
                  {s || "Todos"}
                </button>
              ))}
            </div>
          </Field>

          {/* Filtro estado servicio */}
          <Field label="Estado del servicio">
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              {["", ...ESTADOS].map(s => (
                <button key={s} onClick={() => setFiltros(f => ({ ...f, estado: s }))}
                  style={{ padding: "7px 14px", borderRadius: 8, border: "2px solid " + (filtros.estado === s ? GC.brand : "#e2e8f0"), background: filtros.estado === s ? GC.brandLight : "#fff", color: filtros.estado === s ? GC.brand : GC.ink2, cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit" }}>
                  {s || "Todos"}
                </button>
              ))}
            </div>
          </Field>

          {/* Filtro deuda */}
          <Field label="Estado financiero">
            <div style={{ display: "flex", gap: 8 }}>
              {[["", "Todos"], ["con_deuda", "Con deuda"], ["sin_deuda", "Al día"]].map(([val, lbl]) => (
                <button key={val} onClick={() => setFiltros(f => ({ ...f, deuda: val }))}
                  style={{ flex: 1, padding: "9px 8px", borderRadius: 8, border: "2px solid " + (filtros.deuda === val ? (val === "con_deuda" ? "#ef4444" : val === "sin_deuda" ? "#16a34a" : GC.brand) : "#e2e8f0"), background: filtros.deuda === val ? (val === "con_deuda" ? "#fef2f2" : val === "sin_deuda" ? "#f0fdf4" : GC.brandLight) : "#fff", color: filtros.deuda === val ? (val === "con_deuda" ? "#ef4444" : val === "sin_deuda" ? "#16a34a" : GC.brand) : GC.ink2, cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit" }}>
                  {lbl}
                </button>
              ))}
            </div>
          </Field>

          {/* Preview */}
          <div style={{ background: filtros.deuda === "con_deuda" ? "#fef2f2" : "#f0fdf4", border: "1px solid " + (filtros.deuda === "con_deuda" ? "#fecaca" : "#bbf7d0"), borderRadius: 10, padding: "12px 16px", marginBottom: 16, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <span style={{ fontSize: 13, color: GC.ink2 }}>Clientes que se exportarán:</span>
            <span style={{ fontWeight: 800, fontSize: 18, color: GC.brand }}>{clientes.length}</span>
          </div>
          <div style={{ fontSize: 11, color: GC.ink3, marginBottom: 16 }}>
            * El filtro "Con deuda / Al día" se aplica al descargar (requiere cargar facturas).
          </div>

          {/* Botones */}
          <div style={{ display: "flex", gap: 8 }}>
            <Btn onClick={doExport} disabled={cargando || clientes.length === 0} style={{ flex: 1 }}>
              {cargando ? "⏳ Generando..." : `📥 Descargar CSV (${clientes.length} clientes)`}
            </Btn>
            <button onClick={onClose} style={{ padding: "10px 16px", background: GC.bg3, border: "none", borderRadius: 9, cursor: "pointer", fontSize: 13, color: GC.ink2, fontFamily: "inherit" }}>Cancelar</button>
          </div>
        </div>
      </div>
    </div>
  );
}

function exportarClientes(usuarios, facturas, zonas, planes, perfilesPago) {
  const MESES_N = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];

  // Solo clientes finales y empresa
  const clientes = usuarios.filter(u => u.rol === "cliente" && u.activo);

  // Para cada cliente calcular deuda total
  const rows = clientes.map(c => {
    const facturasClienteRaw = facturas.filter(f => f.clienteId === c.id && f.estado !== "Anulada");
    // Deduplicar por (mes, anio): si hay dos facturas del mismo mes, sumar los saldos pendientes en una sola entrada
    const facturasMap = new Map();
    for (const f of facturasClienteRaw) {
      const key = `${f.anio}-${String(f.mes).padStart(2,"0")}`;
      if (!facturasMap.has(key)) {
        facturasMap.set(key, { ...f });
      } else {
        // Hay duplicado — acumular el saldo pendiente real (no duplicar el monto base)
        const existing = facturasMap.get(key);
        existing.saldoPendiente = (existing.saldoPendiente || 0) + (f.saldoPendiente || 0);
      }
    }
    const facturasCliente = Array.from(facturasMap.values());
    const deudaTotal = facturasCliente.reduce((s, f) => s + (f.saldoPendiente || 0), 0);
    const facturasPendientes = facturasCliente.filter(f => f.saldoPendiente > 0);
    const ultimaFactura = [...facturasCliente].sort((a,b) => (b.anio*12+b.mes) - (a.anio*12+a.mes))[0];

    const zona = zonas.find(z => z.id === c.zonaId);
    const plan = planes.find(p => p.id === c.planId);
    const perfil = perfilesPago.find(p => p.id === c.perfilPagoId);

    const estadoFinanciero = deudaTotal > 0
      ? `EN DEUDA - $${deudaTotal.toLocaleString("es-CO")}`
      : "AL DIA";

    const factPend = facturasPendientes.map(f =>
      `${MESES_N[(f.mes||1)-1]} ${f.anio}: $${(f.saldoPendiente||0).toLocaleString("es-CO")}`
    ).join(" | ");

    return {
      "Nombre":              c.nombre || "",
      "Tipo":                c.tipo === "empresa" ? "Empresa" : "Cliente final",
      "Cédula / NIT":        c.cedula || "",
      "Usuario":             c.usuario || "",
      "Teléfono":            c.telefono || "",
      "Teléfono 2":          c.telefono2 || "",
      "Correo":              c.correo || "",
      "Dirección":           c.direccion || "",
      "Zona":                zona?.nombre || "",
      "Plan":                plan?.nombre || c.plan || "",
      "Servicio":            c.servicio || "",
      "Monto mensual":       c.monto ? `$${Number(c.monto).toLocaleString("es-CO")}` : "",
      "Perfil de pago":      perfil?.nombre || "",
      "IP":                  c.ip || "",
      "Clave WiFi":          c.claveWifi || "",
      "Estado servicio":     c.estado || "",
      "Estado financiero":   estadoFinanciero,
      "Deuda total":         deudaTotal > 0 ? deudaTotal : 0,
      "Facturas pendientes": factPend || "Ninguna",
      "Última factura":      ultimaFactura ? `${MESES_N[(ultimaFactura.mes||1)-1]} ${ultimaFactura.anio}` : "",
      "UUID Wispro":         c.wisproUuid || "",
      "Activo":              c.activo ? "Sí" : "No",
    };
  });

  if (rows.length === 0) { alert("No hay clientes para exportar."); return; }

  // Generar CSV
  const headers = Object.keys(rows[0]);
  const sep = ";"; // punto y coma para Excel en español

  const escape = val => {
    const s = String(val ?? "").replace(/"/g, '""');
    return s.includes(sep) || s.includes("\n") || s.includes('"') ? `"${s}"` : s;
  };

  const csv = [
    "\uFEFF" + headers.map(escape).join(sep), // BOM para UTF-8 en Excel
    ...rows.map(r => headers.map(h => escape(r[h])).join(sep))
  ].join("\n");

  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url  = URL.createObjectURL(blob);
  const link = document.createElement("a");
  const fecha = new Date().toISOString().split("T")[0];
  link.href     = url;
  link.download = `clientes_gchogar_${fecha}.csv`;
  link.click();
  URL.revokeObjectURL(url);
}

